// Story script for "Space 夜调 / Last Call at Space" — written in the style of a Japanese AVG.
// Step helpers:
//   S(who,zh,en)  a character speaks (portrait switches to the speaker; cameos allowed)
//   ME(zh,en)     the bartender (player) speaks      N(zh,en)  narration / inner monologue （……）
//   C(...opts)    choice; each opt = [zh, en, affinity, followUpSteps, need?]  (need = condition, shown with 🔑)
//   CT(sec,timeoutSteps,...opts)  timed choice; if nothing is picked in `sec` s, timeoutSteps play
//   MIX(accept,best,great,ok,bad) the player mixes; branch plays by result tier
//   AFF(n) affinity change   FLAG(name) set a persisted flag   IF(cond,then,else)
//   FX('shake'|'flash'|'dark'|'light'|'rain'|'clear')   EMO('💦'|'💢'|'❗'|'❓'|'♪'|'💤'|'✨'|'…')
//   CARD(zh,en)   full-screen caption card (time stamps, time skips)
// Conditions: 'flag' | '!flag' | {aff:'who',min:n} | {tier:'great'|'ok'|'bad'} | [cond, cond, ...] (all)
// The engine auto-sets `<who>_<tier>` flags after every mix (e.g. jiuge_great).
// 【】 marks a flavour clue; the engine highlights it and collects it into the clue notebook.
const S=(who,zh,en)=>({s:who,t:[zh,en]});
const ME=(zh,en)=>({s:'me',t:[zh,en]});
const N=(zh,en)=>({s:'n',t:[zh,en]});
const C=(...opts)=>({c:opts.map(([zh,en,aff,then,need])=>({t:[zh,en],aff,then:then||[],need}))});
const CT=(sec,timeout,...opts)=>({...C(...opts),timer:sec,timeout});
const MIX=(accept,best,great,ok,bad)=>({mix:{accept,best},great,ok,bad});
const AFF=(n)=>({aff:n});
const FLAG=n=>({flag:n});
const IF=(cond,then,els)=>({if:cond,then,else:els||[]});
const FX=t=>({fx:t});
const EMO=e=>({emo:e});
const CARD=(zh,en)=>({card:[zh,en]});
//   WHO(k)        switch the "current guest" mid-scene (portrait / hearts / AFF / mix now target k)
//   END(id,zh,en) record an ending (see ENDINGS at the bottom) and show a full-screen ending card
//   TIP(n)        tips / money reward (spent in the ingredient shop)
//   MIX2({accept,best,want,avoid,str,great,ok,bad,wow})  taste-first freestyle mix:
//       want  = flavour/style tags the guest is really after; avoid = tags that ruin it; str = 'low'|'mid'|'high'
//       any drink hitting `want` without `avoid` (sensible glass/ice/method) can score great; best/accept still work.
//       wow   = 歪打正着: the drink also hit the guest's hidden favourite flavour (falls back to great if omitted)
//   MX(o,great,ok,bad,wow)  positional shorthand for MIX2 (o = {accept,best,want,avoid,str})
// Clue flags: every 【word】 shown sets flag 'clue:word', so options can require need:'clue:word'.
// Extra conditions: {tier:'wow'} (only wow) — {tier:'great'} is also true for wow.
const WHO=k=>({who:k});
const END=(id,zh,en)=>({ending:[id,zh,en]});
const TIP=n=>({tip:n});
const MIX2=o=>({mix:{accept:o.accept||[],best:o.best,want:o.want,avoid:o.avoid,str:o.str},great:o.great||[],ok:o.ok||[],bad:o.bad||[],wow:o.wow});
const MX=(o,great,ok,bad,wow)=>MIX2({...o,great,ok,bad,wow});

const STORY=[
// ===================== NIGHT 1 =====================
{title:['开业之夜','Opening Night'],
 preview:['下回——午夜的包厢里，有人被冤枉成了凶手；隔壁酒吧的粉发调酒师来「验货」；还有一首练了一个月的情歌。','Next time: someone gets framed in a midnight murder game, the pink-haired bartender from next door comes to size you up, and a love song rehearsed for a month finally gets sung.'],
 intro:[CARD('— 第一夜 · 21:00 —','— Night One · 9:00 PM —'),
        N('Space KTV 新店开张。今天，是你第一天站在吧台后面。','Space KTV has just opened. Tonight is your first shift behind the bar.'),
        N('身后一整面紫光方格酒柜，正中挂着大电视；下面一排青绿色的圆形灯位里，酒瓶像展品一样立着。','Behind you, a wall of purple-lit cubbies frames a big TV; beneath it, a row of teal portholes displays the bottles like museum pieces.'),
        N('黑色吧台擦得能照出人影。台前一圈圈粉色霓虹，「啪」地一声，全亮了。','The black counter is polished to a mirror. With a soft click, the pink neon rings along its front light up.'),
        FX('flash'),
        N('（金汤力，45 毫升金酒，汤力水加满……古典，方糖、苦精、一块大冰……）','(Gin and tonic: 45 ml gin, top with tonic… Old Fashioned: sugar cube, bitters, one big cube…)'),
        N('（——冷静。配方背了一个月。不会有事的。）','(Calm down. You\'ve drilled these for a month. You\'ll be fine.)'),
        N('门上的风铃响了。第一位客人，到了。','The bell over the door chimes. Your first guest has arrived.')],
 scenes:[
 {who:'jiuge',steps:[
  N('一个留着短胡子、半扎着头发的男人坐上吧台凳。他先用指节敲了两下台面——像在跟一位老朋友打招呼。','A man with a trimmed beard and half-tied hair takes a stool. He raps the counter twice with his knuckles, like greeting an old friend.'),
  N('（这个动作……只有在吧台后面站过很多年的人才会有。）','(That gesture… only someone who\'s spent years behind a bar does that.)'),
  S('jiuge','新来的调酒师？我是这儿的常客，大家都叫我酒哥。','New bartender? I\'m a regular. Everyone calls me Brother Jiu.'),
  S('jiuge','先说清楚——别看我叫"酒哥"，我酒量差得要命。两杯就开始唱歌，三杯就开始哭。','Fair warning: despite the name, I can barely hold my drink. Two and I start singing. Three and I start crying.'),
  EMO('♪'),
  C(['那您为什么叫酒哥？','So why "Brother Jiu"?',1,[
      S('jiuge','以前在老街开过一家小酒馆，叫「九号」。酒馆倒了，名字留下了。','I ran a little bar on the old street once. Called "Number Nine". The bar closed; the name stuck.'),
      S('jiuge','房租涨了三倍，撑了半年。最后一晚，我把剩下的酒全请客人喝了。','Rent tripled; I held on six months. On the last night I poured every bottle I had left, on the house.'),
      S('jiuge','哈哈，别这副表情，都过去了。……都过去了。','Ha, don\'t look at me like that. It\'s all in the past. …All in the past.'),
      FLAG('jiu_story')]],
    ['酒量差没关系，我给您调杯温和的。','No problem, I\'ll make you something gentle.',2,[
      S('jiuge','懂事！我就喜欢不劝酒的调酒师。','Now that\'s a good bartender. Never pushes the booze.'),
      S('jiuge','以前我自己站吧台的时候，最烦那种灌客人的。','Back when I tended bar myself, I hated people who pushed drinks on guests.'),
      S('jiuge','……哦，忘了说。我以前也开过酒馆，叫「九号」。小店，倒了。','…Oh, did I mention? I used to run a bar. Number Nine. Small place. It closed.'),
      FLAG('jiu_story')]],
    ['常客就别客气，来点烈的？','Come on, a regular can handle something strong!',-1,[
      EMO('💦'),
      S('jiuge','……你是想让我第一天就躺在你吧台上？','…You want me passed out on your counter on day one?'),
      S('jiuge','年轻人，调酒不是比谁酒精多。我以前开酒馆的时候也犯过这个错。','Kid, mixing isn\'t a contest of who pours the most. I made that mistake when I had my own bar.')]]),
  N('走廊尽头的包厢里，传来有人跑调跑到天上去的高音。酒哥听着，笑出了声。','From a room down the corridor comes a high note so off-key it reaches orbit. Brother Jiu laughs out loud.'),
  S('jiuge','今天我在包厢唱了三个小时《海阔天空》，嗓子快冒烟了。','I\'ve been belting the same rock anthem for three hours. My throat\'s on fire.'),
  C(['三个小时同一首？','Three hours of one song?',1,[
      S('jiuge','那是我酒馆关门那晚，大家一起唱的。每次唱，都像回到那天。','It\'s what everyone sang the night my bar closed. Every time I sing it, I\'m back there.')]],
    ['先喝口温水吧。（递上一杯水）','Have some warm water first. (Slide him a glass)',2,[
      S('jiuge','（愣了一下，笑着接过）……你这孩子，有点意思。','(Pauses, then takes it with a smile) …You\'re an interesting one.'),
      S('jiuge','以前我也是这么照顾客人的。客人喝什么都可以，嗓子不能坏。','That\'s how I used to look after my guests. Drink what you like, but protect the voice.')]],
    ['唱那么久，是不是心里有事？','Singing that long, something on your mind?',0,[
      EMO('…'),
      S('jiuge','……眼睛挺毒啊。今天，是我那家酒馆关门三周年。','…Sharp eyes. Today\'s three years since my bar closed.'),
      FLAG('jiu_anniv')]],
    ['（不说话，看他敲台面的那只手）','(Say nothing. Watch the hand that knocked on the counter)',1,[
      N('他的手腕上系着一根洗得发白的【红绳】，绳结打得很怪——是调酒师绑围裙那种死结。','Around his wrist is a faded 【red string】, tied in an odd knot: the dead knot bartenders use on apron strings.'),
      S('jiuge','（发现你在看，把袖子往下拉了拉）……老物件。开店那天我妈给系的，说保生意。','(Notices, tugs his sleeve down) …Old thing. My mom tied it on opening day. For luck in business.'),
      S('jiuge','结果嘛，生意没保住，绳子倒是一直没断。哈。','Didn\'t save the business. The string never snapped, though. Ha.'),
      FLAG('jiu_string')]]),
  S('jiuge','给我来点【带茶味】的，【甜一点】，喝了【不上头】的。','Make me something 【with tea】 in it, 【a bit sweet】, nothing 【that goes to my head】.'),
  S('jiuge','以前我店里有杯招牌，就是这个路子。你看着办，看能不能猜中。','My old place had a signature drink along those lines. Let\'s see if you can guess it.'),
  C(['再给点提示？','Any more hints?',1,[
      S('jiuge','（他想了想）夏天的夜市，【一大桶冰冰的、甜甜的那种茶】……','(He thinks.) Summer night markets. 【That big icy barrel of sweet tea】…'),
      S('jiuge','再往里面，加一点点【会让人想起老电影的酒】。','And into it, just a little 【liquor that reminds you of old movies】.')]],
    ['交给我吧。','Leave it to me.',1,[
      S('jiuge','口气挺稳。行，我等着。','Steady voice. Alright, I\'ll wait.')]],
    ['（默默把威士忌和冬瓜茶摆上台面）','(Quietly set the whiskey and the winter melon tea on the counter)',2,[
      EMO('❗'),
      S('jiuge','……喂喂，你是不是偷看过我的日记？','…Hey, hey. Have you been reading my diary?')],'jiu_anniv']),
  N('（带茶、偏甜、又温和……台湾夜市那种冬瓜茶，配一点点威士忌？——也不一定非得照着猜。让他喝得开心，才是正经事。）','(Tea, sweet, mellow… night-market winter melon tea, with a splash of whiskey? Then again, you don\'t have to guess his old recipe. Making him happy is the real job.)'),
  MX({accept:['jager_tea','osmanthus_oolong','matcha_highball','jasmine_gin'],best:'wm_whisky',want:['茶','甜','温和'],avoid:['烈','苦'],str:'low'},
   [S('jiuge','（喝了一大口，愣住）……冬瓜茶配威士忌？','(Takes a big sip and freezes) …Winter melon tea and whiskey?'),
    EMO('❗'),
    S('jiuge','这不就是「九号」当年的招牌吗！你怎么知道的？','That was Number Nine\'s signature! How did you know?'),
    N('他低头笑了好一会儿，眼眶有点红。杯里的冰块轻轻碰了一下杯壁。','He laughs quietly into the glass for a while, eyes a little red. The ice gives the glass a soft knock.'),
    S('jiuge','行，你这手艺，我以后天天来。','Alright. With hands like yours, I\'ll be here every night.'),
    S('jiuge','对了……以前有个老客人，每周五都点这杯。西装笔挺，话很少，喝完就走。好多年没见了。','Funny… there was an old regular who ordered this every Friday. Sharp suit, barely spoke, left right after. Haven\'t seen him in years.'),
    FLAG('suit_regular'),TIP(20)],
   [S('jiuge','嗯，有茶味，挺顺口。不是我那杯，但也不错。','Mm, tea, goes down easy. Not my drink, but not bad.'),
    S('jiuge','给你个提示：冬瓜茶。我那家「九号」就靠它撑了好几年。','Here\'s a hint: winter melon tea. Number Nine lived on it for years.'),
    S('jiuge','下次调对了，我给你讲讲它的来历。','Get it right next time and I\'ll tell you where it came from.')],
   [EMO('💦'),
    S('jiuge','咳咳咳——这也……不太对。','*cough cough* That\'s… not it.'),
    S('jiuge','我刚才说的可是「茶味、偏甜、不上头」啊。','I did say tea, sweet, won\'t go to my head.'),
    S('jiuge','（他还是把杯子推远了一点）没事，第一天嘛。我以前第一天把盐当糖放了。','(He nudges the glass away.) Relax, it\'s your first day. On mine I used salt instead of sugar.'),
    C(['……能教教我吗？','…Could you show me?',2,[
        N('酒哥看了你两秒，然后撑着吧台一翻——人已经站到了你旁边。','Brother Jiu looks at you for two seconds, then vaults the counter. He\'s standing next to you.'),
        S('jiuge','手。冰先下，酒后下，茶最后——别搅太狠，茶会苦。','Hands. Ice first, spirit next, tea last. Don\'t stir too hard or the tea turns bitter.'),
        N('他的动作快得不像一个"酒量差"的人。三秒，一杯冬瓜威士忌立在台面上，冰块都没响一下。','He moves far too fast for a man who "can\'t hold his drink." Three seconds, and a winter melon whiskey stands on the counter, the ice silent.'),
        S('jiuge','……三年没碰了。手还记得。','…Three years since I touched one. My hands remember.'),
        N('他翻回客人那一侧，自己端起来喝了一口，像什么都没发生过。','He hops back to the guest side and sips it like nothing happened.'),
        FLAG('jiu_taught'),FLAG('suit_regular'),
        S('jiuge','以前有个西装笔挺的老客人，每周五就点这杯。……你刚才那个手势，跟他点单时一模一样。','There was an old regular in a sharp suit, every Friday, this exact drink. …That gesture you just made, same as his when he ordered.')]],
      ['（把杯子收回来）下次一定调对。','(Take the glass back) I\'ll get it right next time.',0,[
        S('jiuge','行，我记着。','Sure. I\'ll hold you to it.')]])],
   [S('jiuge','（一口下去，整个人停住了）……桂花？','(One sip and he goes completely still) …Osmanthus?'),
    EMO('❗'),
    S('jiuge','你……你怎么会知道。','How… how did you know.'),
    N('他转着杯子，看了很久。','He turns the glass for a long time.'),
    S('jiuge','「九号」门口以前有棵桂花，我妈种的。每年秋天，满街都是这个味道。客人进门第一句都是「好香」。','There was an osmanthus tree outside Number Nine. My mom planted it. Every autumn the whole street smelled like this. Every guest walked in saying "what a smell."'),
    S('jiuge','我嘴上说喜欢喝苦的、烈的……其实我最爱的，就是这种甜得没出息的花香。别告诉别人。','I tell everyone I like it bitter and strong… but what I really love is this hopelessly sweet floral stuff. Don\'t tell anyone.'),
    N('他把袖子往上捋了捋。手腕上，一根洗得发白的【红绳】。','He pushes up his sleeve. On his wrist, a faded 【red string】.'),
    S('jiuge','这是开店那天我妈系的。……行，你这手艺，我以后天天来。','My mom tied this on opening day. …Alright. With hands like yours, I\'ll be here every night.'),
    S('jiuge','对了……以前有个老客人，每周五都点我那杯冬瓜威士忌。西装笔挺，话很少。好多年没见了。','Funny… there was an old regular who ordered my winter melon whiskey every Friday. Sharp suit, barely spoke. Haven\'t seen him in years.'),
    FLAG('suit_regular'),FLAG('jiu_string'),TIP(30)]),
  S('jiuge','好了，我回包厢了。今晚有人约我玩谜案游戏。','Right, back to the room. Someone talked me into a murder-mystery game.'),
  S('jiuge','听说凶手，往往是最不像凶手的那个。','They say the killer is always the one who looks least like one.'),
  EMO('✨'),
  N('酒哥摆摆手，消失在走廊深处。不一会儿，那首老歌又隐约响了起来。','Brother Jiu waves and disappears down the corridor. Soon, faintly, that old song starts up again.')]},

 {who:'boluobao',steps:[
  CARD('— 22:15 —','— 10:15 PM —'),
  N('一个金橙色卷发、穿黄卫衣的男生几乎是蹦到吧台前的，手里还拎着一顶纸做的生日帽。','A guy with golden-orange curls and a yellow hoodie bounces up to the bar, a paper party hat in his hand.'),
  N('他身上有一股刚出炉的黄油香味。（……面包店？）','He smells of fresh-baked butter. (…A bakery?)'),
  S('boluobao','今天是我生日！！朋友们都在包厢等我，我出来点一杯特别的！','It\'s my birthday!! Everyone\'s waiting in the room, I came out to get something special!'),
  S('boluobao','我叫菠萝包！因为我小时候圆圆的、黄黄的，还特别爱吃菠萝包。嘿嘿。','I\'m Pineapple Bun! Because as a kid I was round, yellow, and obsessed with pineapple buns. Hehe.'),
  EMO('✨'),
  C(['生日快乐！今年多大啦？','Happy birthday! How old today?',1,[
      S('boluobao','二十四！我在面包店当学徒，今天师傅终于让我自己烤一炉了！','Twenty-four! I\'m a bakery apprentice, and today the boss finally let me bake a whole batch myself!'),
      S('boluobao','双喜临门！','Double celebration!')]],
    ['生日的话，要不要来杯颜色好看、适合拍照的？','For a birthday, how about something pretty for photos?',2,[
      S('boluobao','对对对！你太懂我了！要【颜色好看】的！','Yes yes yes! You totally get me! Something 【really colourful】!'),
      S('boluobao','我要发给我妈看。她总说我只会吃，不会生活。','I\'m sending it to my mom. She says all I know how to do is eat.')]],
    ['就你一个人出来点？','Just you out here?',0,[
      S('boluobao','他们在里面抢麦呢，哈哈。抢不过，我就出来了。','They\'re fighting over the mic, haha. I lost, so here I am.'),
      S('boluobao','生日的人居然抢不到麦，你说过分不过分！','The birthday boy can\'t even get the mic. Outrageous, right?'),
      EMO('💢')]]),
  S('boluobao','我跟你说个秘密——今天我其实，有点紧张。','Can I tell you a secret? I\'m actually a bit nervous today.'),
  C(['紧张什么？','Nervous about what?',1,[
      S('boluobao','我偷偷烤了一个蛋糕带过来，第一次自己做的。怕大家不爱吃……','I secretly baked a cake and brought it. My first one, all by myself. What if nobody likes it…')]],
    ['生日有什么好紧张的？','What\'s there to be nervous about on your birthday?',0,[
      S('boluobao','哎呀，你不懂！我烤了个蛋糕，第一次自己烤！','Ugh, you don\'t get it! I baked a cake. My first solo cake!')]],
    ['让我猜猜……你准备了惊喜？','Let me guess… you\'ve got a surprise planned?',2,[
      EMO('❗'),
      S('boluobao','你怎么知道！我自己烤了蛋糕！第一次！','How did you know! I baked the cake myself! First time ever!'),
      S('boluobao','菠萝口味的。所以饮料千万别抢了蛋糕的风头——要【水果味】的，跟菠萝做朋友！','Pineapple flavour. So the drink can\'t upstage the cake: 【something fruity】 that gets along with pineapple!')]]),
  S('boluobao','所以要来一杯能配蛋糕的！我不太能喝苦的，要【甜的】、【水果味】的……','So I need a drink to go with cake! I can\'t do bitter. 【Sweet】 and 【fruity】…'),
  S('boluobao','啊不对不对——要不要【颜色好看】呢？还是要【配蛋糕】？还是……你帮我选！','Wait, no no, should it be 【pretty】? Or 【match the cake】? Or… you pick for me!'),
  C(['先拍照！今晚要发给你妈看的。','Photos first! Your mom\'s waiting for the picture.',1,[
      S('boluobao','对！要【像早上太阳出来那样，橙橙红红的】！我就是早上出生的！','Yes! 【Orange fading into red, like the sun coming up】! I was born at dawn!'),
      FLAG('bolo_photo')]],
    ['蛋糕是主角，饮料给它当配角。','The cake\'s the star. The drink plays support.',2,[
      S('boluobao','（眼睛一亮）……你是第一个说我的蛋糕是主角的人。','(His eyes light up) …You\'re the first person to call my cake the star.'),
      S('boluobao','那要【清清爽爽、冒泡泡】的！吃完奶油，嘴里要一下子"啵"地干净！','Then 【light and bubbly】! After all that cream, your mouth should go "pop", clean!'),
      FLAG('bolo_cake')]],
    ['（拿起一块他的蛋糕先尝一口）','(Taste a bite of his cake first)',2,[
      N('菠萝的酸，黄油的香，奶油有点太甜了——但烤得真好，边上焦得刚刚好。','Tart pineapple, rich butter, the cream a bit too sweet. But beautifully baked, the edges caramelised just right.'),
      S('boluobao','怎、怎么样？','H-how is it?'),
      ME('奶油有点甜。饮料得帮它解解腻——酸一点，带点气泡。','Cream\'s a little sweet. The drink should cut through it. A bit tart, some bubbles.'),
      S('boluobao','……专业！你比我师傅还专业！','…Pro! You\'re more pro than my boss!'),
      FLAG('bolo_cake'),FLAG('bolo_tasted')]]),
  IF('bolo_cake',[N('（配蛋糕：甜得收敛一点，要有果味、有气泡，帮奶油解腻。）','(For the cake: not too sweet, fruity and fizzy to cut the cream.)'),
    MX({accept:['mimosa','sunrise','umeshu_soda','limoncello_spritz','hugo','kir_royale'],best:'aperol_spritz',want:['果味','气泡'],avoid:['烈','奶香'],str:'low'},
     [S('boluobao','（一口蛋糕，一口酒）……啵！真的啵了！嘴里一下子干净了！','(A bite of cake, a sip) …Pop! It really popped! My mouth is all clean!'),
      S('boluobao','我要把这个搭配写进我的小本本——以后店里卖蛋糕，就推荐配这个！','I\'m writing this pairing in my notebook. When the shop sells cake, this is what I\'ll recommend!'),
      IF('bolo_tasted',[S('boluobao','你还说我的奶油太甜……我回去就改配方！','And you said my cream was too sweet… I\'m fixing the recipe tonight!')]),
      S('boluobao','你等着，我给你留最大的那块！','Wait right there, I\'m saving you the biggest slice!'),TIP(15)],
     [S('boluobao','好喝！就是……跟蛋糕好像没怎么当朋友，哈哈。','Tasty! Just… it and the cake aren\'t really friends, haha.'),
      S('boluobao','没事，各自好吃就行！','Whatever, they\'re both good on their own!')],
     [S('boluobao','呃……好像跟蛋糕打起来了……','Uh… I think it\'s fighting with the cake…'),
      S('boluobao','（还是很礼貌地喝了半杯）没关系！生日不许不开心！','(He politely drinks half anyway.) It\'s fine! No sad faces on birthdays!')],
     [S('boluobao','（喝了一口，整个人僵住）……这个、这个泡泡，这个香味……','(One sip and he freezes) …These bubbles, this smell…'),
      S('boluobao','像我们面包店早上第一炉出来，【牛奶面包】掰开的那一下！热气"噗"地冒出来！','It\'s like the first batch of the morning at the bakery, when you tear open a 【milk bun】 and the steam goes "poof"!'),
      S('boluobao','我每天四点起床，就是为了那一下。……我从来没跟人说过，我是因为这个才学烘焙的。','I get up at four every day just for that moment. …I\'ve never told anyone that\'s why I became a baker.'),
      EMO('💦'),
      S('boluobao','以后你吧台上的面包，我包了！每周！不，每天！','From now on your bar\'s bread is on me! Every week! No, every day!'),
      FLAG('bolo_bread'),TIP(20)])],
   [N('（橙色到红色的渐变……橙汁打底，最后让一样重重的红色沉下去？）','(An orange-to-red gradient… orange juice base, then let something heavy and red sink to the bottom?)'),
    MX({accept:['mango_mojito','screwdriver','sex_beach','watermelon_marg','passion_martini'],best:'sunrise',want:['甜','果味','好看'],avoid:['苦'],str:'low'},
   [S('boluobao','哇——橙色慢慢变成红色，像日出一样！','Whoa, orange fading into red, like a sunrise!'),
    S('boluobao','（咔嚓咔嚓拍了十几张）这杯叫龙舌兰日出？我就是早上出生的！太巧了吧！','(Snaps a dozen photos) Tequila Sunrise? I was born at dawn! No way!'),
    S('boluobao','我妈秒回了：「这杯好看，你也好看。」呜呜呜。','My mom replied instantly: "Pretty drink, pretty son." I\'m gonna cry.'),
    EMO('💦'),
    S('boluobao','你等着，我一会儿给你送块蛋糕！最大的那块！','Wait right there, I\'m bringing you cake! The biggest slice!')],
   [S('boluobao','好喝！甜甜的！就是……拍出来有点普通，哈哈。','Tasty! Sweet! Just… a bit plain in photos, haha.'),
    S('boluobao','没事，好喝最重要！我妈也说好吃的东西不用好看。','Whatever, tasty is what matters! Mom says good food doesn\'t need to look good.'),
    S('boluobao','……不过她说的是我做的面包。','…She was talking about my bread, though.')],
   [S('boluobao','呃……好像不是我想要的味道……','Uh… not quite the taste I had in mind…'),
    S('boluobao','（还是很礼貌地喝了半杯）没关系！生日不许不开心！','(He politely drinks half anyway.) It\'s fine! No sad faces on birthdays!'),
    S('boluobao','下次！下次你一定要给我调杯好看的！','Next time! Next time you owe me a pretty one!')],
   [S('boluobao','（拍完照喝了一口，愣住）……咦？这个味道……','(Snaps a photo, sips, and freezes) …Huh? This taste…'),
    S('boluobao','像我们面包店早上第一炉出来，【牛奶面包】掰开的那一下！又香又软，还"噗"地冒热气！','It\'s like the first batch of the morning when you tear open a 【milk bun】! Soft and fragrant, steam going "poof"!'),
    S('boluobao','我每天四点起床，就是为了那一下。……我从来没跟人说过，我是因为这个才学烘焙的。','I get up at four every day just for that moment. …I\'ve never told anyone that\'s why I became a baker.'),
    S('boluobao','以后你吧台上的面包，我包了！','From now on your bar\'s bread is on me!'),
    FLAG('bolo_bread'),TIP(20)])]),
  N('半小时后，吧台上真的多了一块菠萝包形状的蛋糕，还插着一根小蜡烛。','Half an hour later, a pineapple-bun-shaped slice of cake appears on the counter, a tiny candle stuck in it.'),
  N('旁边一张纸条：「第一个蛋糕，第一个吃的是你。——菠萝包」','A note beside it: "My first cake. You get the first slice. – Pineapple Bun"'),
  N('（……甜得有点过头。但是，是很好的味道。）','(…A little too sweet. But it tastes like a good day.)')]},

 {who:'luoyu',steps:[
  CARD('— 23:40 —','— 11:40 PM —'),
  N('一个穿背带裤、娃娃脸的男孩踮着脚，趴到了吧台上。他的下巴刚好够得到台面。','A baby-faced boy in denim overalls stands on tiptoe and leans on the counter. His chin barely clears the top.'),
  S('luoyu','你好！我……我也要一杯酒！','Hi! I… I want a drink too!'),
  S('luoyu','我哥他们在包厢里都在喝，我也想试试！','My brother and his friends are all drinking in there. I want to try!'),
  EMO('✨'),
  CT(8,[N('（你犹豫的这几秒里，男孩已经自己说了下去。）','(While you hesitate, the boy keeps talking on his own.)'),
        S('luoyu','……你、你不说话，是不是看出来我没成年了？','…Y-you\'re not saying anything. You can tell I\'m under age, can\'t you?'),
        S('luoyu','十六。我十六岁。……可我很快就成年了！还有两年！','Sixteen. I\'m sixteen. …But I\'ll be an adult soon! Two more years!')],
    ['你今年多大了？','How old are you?',1,[
      S('luoyu','……十、十六。可是我很快就成年了！还有两年！','…S-sixteen. But I\'ll be an adult soon! Two more years!')]],
    ['好啊，给你来杯最烈的。','Sure, I\'ll make you the strongest one.',-2,[
      N('（等等。他看起来明显没成年。你真的要给他上酒吗？）','(Wait. He\'s clearly a minor. Are you really going to serve him alcohol?)'),
      EMO('❓'),
      S('luoyu','真的吗？！……不过，我哥说我才十六，喝了会被骂死。','Really?! …Though my brother says I\'m only sixteen and he\'d kill me.')]],
    ['我给你调一杯看起来像酒、但没有酒精的，怎么样？','How about something that looks like a cocktail but has 【no alcohol】?',2,[
      S('luoyu','真、真的有这种吗？！','Th-that exists?!'),
      S('luoyu','……那你别告诉我哥它【没有酒精】！','…Then don\'t tell my brother it\'s 【alcohol-free】!'),
      FLAG('luoyu_cool')]]),
  S('luoyu','我哥他们总说我是小屁孩，唱歌都不让我点。','My brother\'s friends call me a little kid. They won\'t even let me pick a song.'),
  C(['你想唱什么？','What do you want to sing?',2,[
      S('luoyu','我练了好久一首说唱！可快了！我能一口气唱完！','I practised a rap for ages! It\'s super fast! I can do it in one breath!'),
      N('他当场念了两句，真的挺快。舌头打了个结，又硬是绕了回来。','He spits two lines on the spot. Fast, really fast. His tongue trips once and he forces it back on track.'),
      EMO('♪')]],
    ['小孩子早点回家吧。','Kids should head home early.',-1,[
      S('luoyu','……你也这么说。','…You too, huh.'),
      N('洛羽的脸垮了下来。','Luo Yu\'s face falls.')]],
    ['等你拿着帅气的饮料回去，他们就不敢小看你了。','Walk back in with a cool drink and they won\'t call you a kid.',1,[
      S('luoyu','对！要帅！要看起来很大人！','Yes! Cool! Grown-up!'),
      FLAG('luoyu_cool')]]),
  N('就在这时，走廊里冲出来一个金色卷发——菠萝包端着一盘蛋糕，差点撞上洛羽。','Just then a mop of golden curls comes barrelling down the corridor: Pineapple Bun with a plate of cake, nearly colliding with Luo Yu.'),
  WHO('boluobao'),
  S('boluobao','哎哟！小朋友你没事吧？……咦，你一个人在这儿？','Whoa! You okay, little guy? …Huh, you\'re out here alone?'),
  S('luoyu','我哥他们不让我点歌……','My brother\'s lot won\'t let me pick songs…'),
  C(['菠萝包，你包厢不是正缺人抢麦吗？','Pineapple Bun, isn\'t your room short of people fighting for the mic?',2,[
      S('boluobao','对哦！寿星特批——小朋友，来我们包厢，第一首给你唱！','Oh yeah! Birthday-boy decree: little guy, come to our room, first song\'s yours!'),
      WHO('luoyu'),
      S('luoyu','真、真的？！我可以唱说唱吗？','R-really?! Can I do my rap?'),
      AFF(2),FLAG('luoyu_party')]],
    ['（递给洛羽一块蛋糕）先吃块蛋糕吧。','(Hand Luo Yu a slice of cake) Have some cake first.',1,[
      WHO('luoyu'),
      S('luoyu','（嘴里塞满）……好吃！比我哥买的好吃一百倍！','(Mouth full) …So good! A hundred times better than what my brother buys!'),
      WHO('boluobao'),
      S('boluobao','（骄傲地挺胸）那当然，我烤的！','(Puffs out his chest) Obviously. I baked it!')]],
    ['你们各回各的包厢吧，别在走廊乱跑。','Back to your own rooms, both of you. No running in the corridor.',-1,[
      S('boluobao','……哦。','…Okay.'),
      N('菠萝包端着蛋糕走了。洛羽看着他的背影，又看看你，没说话。','Pineapple Bun walks off with his cake. Luo Yu watches him go, then looks at you, silent.')]]),
  WHO('luoyu'),
  S('luoyu','我想要【甜甜的】、【有气泡的】……【红红的】那种！','Something 【sweet】 and 【fizzy】… and 【red】!'),
  S('luoyu','上面最好还有个【小装饰】，看起来要像大人喝的！但是……【不能有酒】哦，我会被骂的。','With 【a little garnish】 on top so it looks grown-up! But… 【no alcohol】, okay? I\'d get in trouble.'),
  N('（甜、气泡、红色、一颗装饰……还要零酒精。经典的那杯"给小孩的鸡尾酒"。不过，只要不放酒、看起来帅，怎么搭都行。）','(Sweet, fizzy, red, a garnish, zero alcohol. The classic "kiddie cocktail". But as long as it\'s booze-free and looks cool, you can build it however you like.)'),
  MX({accept:['virgin_mojito','virgin_colada','cucumber_cooler'],best:'shirley',want:['甜','气泡','好看','无酒精'],avoid:['烈'],str:'low'},
   [S('luoyu','哇……红红的，还有一颗樱桃！','Whoa… it\'s red, and there\'s a cherry!'),
    S('luoyu','跟大人的酒一模一样！我要拿回去给我哥看！','It looks exactly like a real cocktail! I\'m showing my brother!'),
    S('luoyu','谢谢你没把我当小孩……虽然我就是小孩。','Thanks for not treating me like a kid… even though I am one.'),
    IF('luoyu_cool',[S('luoyu','（他郑重地伸出小拇指）以后我就是你的眼线！这条街上发生什么，我第一个告诉你！','(He solemnly holds out his pinky) From now on I\'m your lookout! Anything happens on this street, you hear it from me first!'),FLAG('luoyu_friend')]),
    N('洛羽捧着杯子，小心翼翼地走回包厢，像捧着什么宝贝。','Luo Yu carries the glass back with both hands, like a treasure.'),
    N('不一会儿，包厢里炸开一阵欢呼——他好像终于抢到麦了。','Soon a cheer erupts from the room. Sounds like he finally got the mic.')],
   [S('luoyu','好清爽！不过我还以为会是红红甜甜的。','So fresh! I thought it\'d be red and sweet, though.'),
    S('luoyu','嘿嘿，没关系，没有酒精就好！我还是很喜欢！','Hehe, it\'s fine, no alcohol is what matters! I still like it!'),
    N('洛羽端着杯子蹦蹦跳跳地回了包厢。','Luo Yu skips back to the room with his drink.')],
   [EMO('💢'),
    S('luoyu','（凑近闻了一下就皱起眉头）……这里面有酒吧？','(Sniffs it and frowns) …There\'s alcohol in this, isn\'t there?'),
    S('luoyu','我才十六岁！我哥要是知道了会打死我的！','I\'m only sixteen! My brother would kill me!'),
    N('洛羽把杯子推了回来，转身就跑。','Luo Yu shoves the glass back and turns to run.'),
    CT(6,[N('（他已经跑进走廊了。）','(He\'s already gone down the corridor.)'),N('（给未成年人上酒可不行。这件事，他大概会记很久。）','(Serving a minor is a no. He\'ll probably remember this for a long time.)')],
      ['「等一下！是我弄错了——给我三十秒。」','"Wait! My mistake. Give me thirty seconds."',2,[
        N('你把那杯倒掉，当着他的面，只用汽水、红石榴糖浆和一颗樱桃，重新堆了一杯。','You pour it out and, right in front of him, build a new one from nothing but soda, grenadine and a cherry.'),
        S('luoyu','……（他盯着杯子看了半天）这回没酒了？','…(He stares at it a long time) No alcohol this time?'),
        ME('我拿工作担保。','I swear on my job.'),
        S('luoyu','……那、那原谅你了。大人也会犯错的嘛。','…Th-then I forgive you. Grown-ups make mistakes too.'),
        FLAG('luoyu_forgive')]],
      ['（算了，让他走吧）','(Let it go)',-1,[
        N('（给未成年人上酒可不行。下次记得调无酒精的。）','(Serving a minor is a no. Next time, go alcohol-free.)')]])],
   [S('luoyu','（喝了一口，眼睛一下子睁圆）……这个味道！','(One sip and his eyes go round) …This taste!'),
    S('luoyu','像我奶奶睡前给我煮的那种……【香香的、软软的】味道！她每次都偷偷给我加两勺糖，说不许告诉我哥。','It\'s like what my grandma makes me before bed… that 【soft, sweet-smelling】 taste! She always sneaks in two extra spoons of sugar and says not to tell my brother.'),
    S('luoyu','我哥什么都管我，只有奶奶……（他吸了吸鼻子）……你怎么知道我最喜欢这个？','My brother bosses me about everything. Only Grandma… (He sniffs.) …How did you know this is my favourite?'),
    N('他把杯子抱在怀里，没舍得一口喝完。','He hugs the glass and can\'t bring himself to finish it in one go.'),
    S('luoyu','（伸出小拇指）以后我就是你的眼线！这条街上发生什么，我第一个告诉你！','(Holds out his pinky) From now on I\'m your lookout! Anything happens on this street, you hear it from me first!'),
    FLAG('luoyu_friend'),TIP(10)]),
  CARD('— 02:00 · 打烊 —','— 2:00 AM · Closing —'),
  N('打烊时，你在吧台上发现一张蛋糕纸条、一只空杯，还有一张小孩画的涂鸦：一个调酒师，头上写着「酷」。','At closing you find a cake note, an empty glass, and a child\'s doodle on the counter: a bartender, with "COOL" written above.'),
  IF('luoyu_party',[N('涂鸦背面还有一行歪歪扭扭的字：「菠萝包哥哥让我唱了三首！！！」','On the back, in wobbly letters: "Pineapple Bun let me sing THREE songs!!!"')]),
  IF('luoyu_forgive',[N('涂鸦旁边多画了一个小人，在倒掉一杯酒。下面写着：「知错能改，还是酷。」','Next to it, a little stick figure pouring a drink away. Underneath: "Fixed your mistake. Still cool."')]),
  IF('jiu_taught',[N('（酒哥翻过吧台那三秒……那不是"以前开过酒馆"的手。那是一双从来没停过的手。）','(Those three seconds when Brother Jiu vaulted the bar… those weren\'t the hands of someone who "used to" run a bar. Those hands never stopped.)')]),
  IF('suit_regular',[N('（每周五、西装、只点那一杯……酒哥说的那位老客人，现在在哪呢？）','(Every Friday, a suit, always that one drink… where is Brother Jiu\'s old regular now?)')]),
  N('你关掉霓虹。黑色吧台上，倒映着最后一点紫光。','You switch off the neon. The black counter holds the last of the purple glow.'),
  N('第一个晚上，就这样结束了。','And so your first night comes to an end.')]}
 ]},

// ===================== NIGHT 2 =====================
{title:['午夜包厢','Midnight Rooms'],
 preview:['下回——红色暴雨预警。收起湿伞的女人，谈崩了一笔三个月的合作；在国外长大的男生想念一口姜汤；还有一个手机泡了水、找不到朋友的女孩。打烊时，街对面站着一个撑黑伞的人。','Next time: a red storm warning. A woman whose three-month deal just collapsed, a guy raised abroad who misses his mother\'s ginger soup, a girl with a drowned phone and no way to find her friends. And at closing, someone with a black umbrella, watching from across the street.'],
 intro:[CARD('— 第二夜 · 00:05 —','— Night Two · 12:05 AM —'),
        N('第二天午夜，包厢里的歌声此起彼伏，墙壁跟着低音一起轻轻发抖。','Past midnight on the second night, songs spill from every room, the walls trembling faintly with the bass.'),
        N('吧台角落里放着一个小盘子——菠萝包说，以后每周给你带一块面包。','A little plate sits at the end of the counter. Pineapple Bun promised to bring you a bun every week.'),
        IF('jiuge_great',[N('酒哥今天进门时，冲你竖了个大拇指，然后径直去了包厢。（看来那杯冬瓜威士忌，他记住了。）','Brother Jiu gave you a thumbs-up on his way to the rooms. (Looks like he remembers that winter melon whiskey.)')],
           [N('酒哥今天进门时，冲你挥了挥手：「今天我自己带了茶！」……他是在开玩笑吧？','Brother Jiu waved on his way in: "Brought my own tea today!" …He\'s joking, right?')]),
        N('（今晚的客人，好像都带着心事。）','(Tonight\'s guests all seem to be carrying something.)')],
 scenes:[
 {who:'xiangge',steps:[
  N('一个穿橙色皮夹克的男人重重地坐下，「啪」地把手机扣在了吧台上。','A man in an orange leather jacket drops onto a stool and slaps his phone face-down on the counter.'),
  FX('shake'),
  S('xiangge','气死我了。','Unbelievable.'),
  S('xiangge','刚在包厢里玩谜案，我明明推理对了，结果他们投票把我当凶手给票出去了！','We\'re playing the murder game. I solved it, and they voted ME out as the killer!'),
  EMO('💢'),
  S('xiangge','真凶是那个留胡子的，一直装醉，说自己酒量差。','The real killer was the bearded guy. Kept acting drunk, saying he can\'t hold his liquor.'),
  N('（……留胡子、说自己酒量差？好像是酒哥。「凶手往往是最不像凶手的那个」——原来他是在说自己。）','(…Bearded, claims he can\'t hold his drink? Brother Jiu. "The killer is the one who looks least like one." He was talking about himself.)'),
  C(['他们投你，是不是因为你看起来最可疑？','Maybe you just looked the most suspicious?',-1,[
      S('xiangge','……你是在安慰我，还是在补刀？','…Is that comfort or a second stab?'),
      S('xiangge','行吧，我承认我嗓门大了点。','Fine, I admit I was a bit loud.')]],
    ['推理对了还被冤枉，确实憋屈。','Solving it and still getting framed, that stings.',2,[
      S('xiangge','对吧！还是你懂。','Right?! Finally someone gets it.'),
      S('xiangge','我白天在律所当助理，天天被人冤枉，晚上玩个游戏还被冤枉。','I\'m a paralegal by day. I get blamed for everything at work, and now at night too.')]],
    ['那个留胡子的，是不是叫酒哥？他以前开过一家叫「九号」的酒馆。','The bearded guy, Brother Jiu? He used to run a bar called Number Nine.',2,[
      EMO('❗'),
      S('xiangge','你认识他？！连他的老底都知道？','You know him?! You even know his backstory?'),
      S('xiangge','……难怪他装醉装得那么像。开过酒馆的人，见过的醉鬼比我见过的卷宗还多。','…No wonder he plays drunk so well. A barkeep\'s seen more drunks than I\'ve seen case files.')],'jiu_story']),
  S('xiangge','其实我气的不是游戏。','Honestly, it\'s not about the game.'),
  S('xiangge','我下周要考律师执照，第三次了。这次再不过，我就回老家。','My bar exam is next week. Third attempt. If I fail again, I\'m moving back home.'),
  N('他用指甲一下一下地刮着杯垫的边。（……这个人，紧张的时候手停不下来。）','He scrapes the edge of a coaster with his thumbnail, over and over. (…His hands can\'t stay still when he\'s nervous.)'),
  C(['第三次，说明你没放弃过。','Third try means you never quit.',2,[
      S('xiangge','……（他沉默了一会儿）这话我得记下来。','…(He\'s quiet for a moment.) I need to write that down.'),
      FLAG('xiang_promise')]],
    ['回老家也不是坏事。','Going home isn\'t the worst thing.',0,[
      S('xiangge','是不坏。就是……不甘心。','It isn\'t. I\'m just… not ready to give up.')]],
    ['今晚就别想考试了，喝一杯就回去睡觉。','Forget the exam tonight. One drink, then bed.',1,[
      S('xiangge','嗯。一杯就走。','Yeah. One and I\'m out.')]]),
  S('xiangge','给我来杯【够劲的】，【老派一点】的。冰要【大块，慢慢化的那种】。','Give me something 【strong】, 【old-school】. 【One big cube that melts slow】.'),
  S('xiangge','【别给我加什么果汁汽水】，花里胡哨的我不要。','【No juice, no soda】. None of that fancy stuff.'),
  C(['威士忌可以吗？','Whiskey okay?',1,[
      S('xiangge','可以。【一点点甜，几滴苦】，就像我这一年。','Yeah. 【A little sweet, a few drops of bitter】. Like my year.')]],
    ['要不要加点柠檬，清爽一点？','Some lemon to brighten it up?',-1,[
      S('xiangge','我刚说什么来着？','What did I just say?')]],
    ['（直接拿出古典杯和一块大冰）','(Just reach for a rocks glass and a big cube)',2,[
      S('xiangge','……行。你是懂行的。','…Good. You know your stuff.')]]),
  MX({accept:['manhattan','negroni','sazerac','mezcal_negroni','penicillin'],best:'old_fashioned',want:['烈','苦'],avoid:['气泡','果味'],str:'high'},
   [S('xiangge','（慢慢转着杯子，大冰块碰着杯壁）……这才叫酒。','(Slowly swirls the glass, the big ice clinking) …Now that\'s a drink.'),
    S('xiangge','这种酒，讲究的就是不着急。','The thing about a drink like this is you can\'t rush it.'),
    S('xiangge','我刚才就是太急着证明自己了。考试也是。','I was too eager to prove myself back there. Same with the exam.'),
    IF('xiang_promise',[S('xiangge','"第三次，说明没放弃过"……我写在杯垫上了。考场上我就看这个。','"Third try means you never quit"… I wrote it on the coaster. I\'ll look at it in the exam hall.')]),
    S('xiangge','（他笑了）下一局，我慢慢来。考完了，我回来请你喝。','(He grins.) Next round, I\'ll take my time. After the exam, the drinks are on me.'),TIP(15)],
   [S('xiangge','嗯，方向对了，就是还差点火候。','Mm, right idea. Not quite there.'),
    S('xiangge','跟我刚才那局推理一样，哈。','Just like my detective work tonight, ha.'),
    S('xiangge','不过够劲。行，就它了。','Still, it\'s got a kick. It\'ll do.')],
   [S('xiangge','……这不是我要的。','…This isn\'t what I asked for.'),
    S('xiangge','我说了老派、够劲、别花里胡哨。','I said old-school, strong, no frills.'),
    S('xiangge','算了算了，今天就是诸事不顺。','Forget it. Today\'s just one of those days.')],
   [S('xiangge','（喝了一口，眼睛猛地睁大）……嘶——！这后劲，辣到天灵盖了！','(One sip and his eyes snap wide) …Sss! That kick went straight to the top of my skull!'),
    S('xiangge','我每天在律所靠三杯黑咖啡续命，晚上靠一顿变态辣的烤串活过来。……你给我这一杯，两样全占了。','I survive the office on three black coffees and survive the night on stupidly spicy skewers. …This glass has both.'),
    S('xiangge','我从来不跟人说我爱吃辣——当律师要"冷静"。可冷静的人，谁不想偷偷辣一下？','I never tell anyone I love spice. Lawyers are supposed to be "calm." But who among the calm doesn\'t want a secret burn?'),
    FLAG('xiang_spice'),TIP(25)]),
  N('包厢门「砰」地开了。酒哥端着一杯水冲了出来——显然是刚被罚完。','The room door bangs open. Brother Jiu storms out with a glass of water, clearly fresh from a penalty.'),
  WHO('jiuge'),
  S('jiuge','向哥！你在这儿跟新来的告我状是吧？','Xiang! Badmouthing me to the new kid, are we?'),
  WHO('xiangge'),
  S('xiangge','告你状？你本来就是凶手！装醉！说自己酒量差！','Badmouthing? You WERE the killer! Faking drunk! "Can\'t hold my liquor"!'),
  WHO('jiuge'),
  S('jiuge','我是真的酒量差！两杯就唱歌！你见我唱了没有？唱了！','I really CAN\'T hold it! Two drinks and I sing! Did I sing? I sang!'),
  S('jiuge','（拍吧台）小调酒师，你来评评理。游戏里，死者的酒杯上有个【口红印】——我涂口红吗？我涂吗？！','(Slaps the counter) Little bartender, you be the judge. In the game, the victim\'s glass had a 【lipstick mark】. Do I wear lipstick? DO I?!'),
  WHO('xiangge'),
  S('xiangge','口红印是你故意印上去嫁祸的！你开过酒馆，杯子上什么痕迹你不懂？','You put that lipstick mark there to frame someone! You ran a bar; you know every mark a glass can carry!'),
  N('（两个人同时转头看着你。包厢里还有人在起哄：「法官！法官！」）','(They both turn to look at you. From the room, people chant: "Judge! Judge!")'),
  CT(10,[N('（你还没开口，两个人已经吵到了「你上次欠我的烤串」上。）','(Before you say a word, they\'ve moved on to "those skewers you still owe me.")'),
         S('jiuge','……算了算了，下局再说！','…Forget it, next round!')],
    ['「向哥说得对。口红印是酒哥故意留的——开过酒馆的人最懂杯子。」','"Xiang\'s right. Jiu left that mark on purpose. A barkeep knows glasses best."',2,[
      WHO('xiangge'),
      S('xiangge','（猛地站起来）听见没有！法官判了！','(Leaps up) Hear that? The judge has ruled!'),
      WHO('jiuge'),
      S('jiuge','……（他眯起眼睛，然后笑了）好眼力。没错，是我。','…(He narrows his eyes, then laughs.) Good eye. Yep. It was me.'),
      S('jiuge','不过记住——【在杯子上留痕迹的人，往往是最想被看见的那个】。','But remember: 【the one who leaves a mark on a glass is usually the one who most wants to be seen】.'),
      FLAG('side_xiang')]],
    ['「酒哥是被冤枉的。真要嫁祸，谁会用自己没有的东西？」','"Jiu was framed. Who frames someone with a thing they don\'t even own?"',2,[
      WHO('jiuge'),
      S('jiuge','（一把搂住你的肩膀）听见没有！这孩子讲道理！','(Throws an arm around your shoulders) Hear that? This kid\'s reasonable!'),
      WHO('xiangge'),
      S('xiangge','……行，你们俩一伙的。（他嘟囔着，嘴角却在笑）','…Fine, you two are in cahoots. (He grumbles, but he\'s smiling.)'),
      WHO('jiuge'),
      S('jiuge','（压低声音）其实是我。但你替我说话，我记着了。','(Lowering his voice) It was me, actually. But you stood up for me. I won\'t forget.'),
      FLAG('side_jiu')]],
    ['「罚你们俩合唱一首，谁跑调谁是凶手。」','"Penalty: you two sing a duet. Whoever goes off-key is the killer."',1,[
      N('五分钟后，包厢里传来两个男人撕心裂肺的《海阔天空》。两个人都跑调了。','Five minutes later the room fills with two men screaming a rock anthem. Both are off-key.'),
      N('这一局，没有凶手。','No killer this round.'),
      FLAG('side_both')]]),
  WHO('xiangge'),
  S('xiangge','谢了。','Thanks.'),
  N('几分钟后，包厢里传来一阵欢呼——好像他真的赢了一局。','A few minutes later a cheer erupts from the room. Sounds like he won a round.'),
  N('紧接着是酒哥的惨叫：「我就说凶手是最不像的那个吧——但我说的不是我啊！」','Followed by Brother Jiu\'s howl: "I SAID the killer looks least like one, but I didn\'t mean ME!"')]},

 {who:'kc',steps:[
  CARD('— 00:50 —','— 12:50 AM —'),
  N('一个粉色长发、穿黑马甲打着领结的女生坐下。她没看菜单，目光直接从左到右扫过你的酒柜，像在点名。','A woman with long pink hair, a black vest and a bow tie sits down. She ignores the menu and scans your shelves left to right, like taking roll call.'),
  S('kc','你就是新来的？我在隔壁「Pink Hour」上班，那条街最好的酒吧。','You\'re the new one? I work at Pink Hour next door. Best bar on the street.'),
  S('kc','听说你昨天把酒哥哄哭了。我来验验货。','Heard you made Brother Jiu cry yesterday. I\'m here to check you out.'),
  EMO('…'),
  C(['欢迎指教。','Happy to learn from you.',1,[
      S('kc','嘴挺甜，就看手上功夫了。','Smooth talker. Let\'s see your hands.')]],
    ['同行何必为难同行？','Come on, bartender to bartender?',0,[
      S('kc','这不叫为难，这叫切磋。','It\'s not a challenge, it\'s professional curiosity.')]],
    ['你想喝什么都行，我都会。','Order anything. I know them all.',-1,[
      EMO('💢'),
      S('kc','口气不小。那我可要挑剔了。','Big talk. Then I\'ll be picky.')]]),
  S('kc','（她看了眼你的手）手腕太紧了。摇壶不是用手臂，是用腰。','(She glances at your hands.) Your wrist is too stiff. You shake from the hips, not the arm.'),
  C(['能教我吗？','Could you teach me?',2,[
      S('kc','……哼，你倒是不要面子。','…Hmph. No ego at all, huh.'),
      S('kc','看好了。（她隔空比划了一下，动作干净漂亮）听到冰在壶里「沙沙」变成「嚓嚓」，就停。','Watch. (She mimes a shake in the air, clean and sharp.) When the ice goes from a rattle to a hiss, stop.'),
      S('kc','我师父当年也是这么教我的。他现在……不调了。','My mentor taught me just like that. He doesn\'t… mix anymore.'),
      FLAG('kc_lesson')]],
    ['我习惯这样了。','This is just how I do it.',-1,[
      S('kc','习惯是最难改的。随你。','Habits are hard to break. Your call.')]],
    ['你观察得真仔细。','You don\'t miss a thing.',1,[
      S('kc','干这行，看的就是细节。我师父说，客人的手比嘴诚实。','In this job, details are everything. My mentor said a guest\'s hands are more honest than their mouth.')]]),
  C(['你师父为什么不调了？','Why did your mentor quit?',1,[
      S('kc','……（她转了一下手里的杯垫）他的店关了。他说，没有自己的吧台，就不站别人的吧台。','…(She turns a coaster in her fingers.) His bar closed. He said if he couldn\'t stand behind his own counter, he wouldn\'t stand behind anyone else\'s.'),
      S('kc','倔得要死。','Stubborn as hell.'),
      FLAG('kc_mentor')]],
    ['那你一定很想他。','You must miss him.',1,[
      S('kc','（她愣了一下）……谁说的。','(She blinks.) …Who said that.'),
      EMO('💦')]],
    ['（不追问，给她倒一杯冰水）','(Don\'t pry. Pour her some ice water)',2,[
      S('kc','……谢谢。','…Thanks.')]]),
  S('kc','我要一杯【酸的】、【带点咸味】的【经典款】，【要摇，不加冰】。','I want 【a classic】. 【Sour】, 【a little salty】. 【Shaken, served up, no ice】.'),
  S('kc','杯沿怎么处理，不用我教你吧？','I trust I don\'t need to explain the rim.'),
  C(['就照你说的来，一杯标准的。','Exactly as ordered. Textbook.',1,[
      S('kc','标准就好。我倒要看看你的"标准"有多标准。','Textbook\'s fine. Let\'s see how textbook your textbook is.')]],
    ['照单调太没意思了——我给你调一杯"我的版本"。','Following orders is boring. I\'ll make you "my version".',1,[
      EMO('❗'),
      S('kc','（她挑起眉毛，第一次正眼看你）……有种。','(She raises an eyebrow and looks at you properly for the first time.) …Gutsy.'),
      S('kc','行。酸和咸给我留着，别的随你。调砸了，你就当着我的面喝掉。','Fine. Keep the sour and the salt; the rest is yours. If you botch it, you drink it in front of me.'),
      FLAG('kc_freestyle')]],
    ['今天是酒哥的店关门三周年。……你知道吗？','Today\'s the third anniversary of Brother Jiu\'s bar closing. …Did you know?',1,[
      N('KC 手里的杯垫，停住了。','The coaster in KC\'s fingers stops turning.'),
      S('kc','……你跟我说这个干什么。我又不认识什么酒哥。','…Why are you telling me that. I don\'t know any Brother Jiu.'),
      N('（可她的手指，把杯垫掐出了一道折痕。）','(But her fingers have pressed a crease into the coaster.)'),
      FLAG('kc_knows_anniv')],'jiu_anniv']),
  N('（酸、咸、杯沿……盐边。基酒是龙舌兰吗？——或者，换个思路？）','(Sour, salty, the rim… a salt rim. Tequila base? Or… something else entirely?)'),
  MX({accept:['daiquiri','paloma','spicy_marg','watermelon_marg','pisco_sour','michelada'],best:'margarita',want:['酸','咸'],avoid:['甜','奶香'],str:'mid'},
   [S('kc','（先抿了一下杯沿的盐，再喝一口）……比例对，摇得也够冰。','(Tastes the salt, then sips) …Ratios are right. Well chilled.'),
    IF('kc_lesson',[S('kc','……还真用腰了。学得挺快嘛。','…You actually used your hips. Quick learner.'),EMO('✨')]),
    IF('kc_freestyle',[S('kc','"你的版本"……哼，不是我点的东西，但我挑不出毛病。烦。','"Your version"… hmph. Not what I ordered, and I can\'t find a flaw. Annoying.')],
      [S('kc','行吧，你过关了。','Fine. You pass.')]),
    S('kc','我师父说过，一杯好的玛格丽特，是酸和咸在吵架，最后和好了。','My mentor used to say a good Margarita is sour and salt arguing until they make up.'),
    S('kc','有空来我们店，我请你喝一杯——当然，是我调的。','Come by sometime. Drink\'s on me. Made by me, of course.'),
    N('她走之前，在吧台上留下一张名片，背面写着：「你是对手。」','Before leaving she drops a business card. On the back: "Consider yourself a rival."'),
    FLAG('kc_card'),TIP(20)],
   [S('kc','嗯……能喝。但不是我点的那杯。','Mm… drinkable. Not what I ordered, though.'),
    S('kc','酸对了，咸呢？盐边呢？','Sour, yes. Where\'s the salt? The rim?'),
    S('kc','再练练吧。','Keep practising.'),
    N('她走之前，在吧台上留下一张名片，背面写着：「其实还行。」','Before leaving she drops a business card. On the back: "Not bad, actually."'),
    FLAG('kc_card')],
   [S('kc','这不是我要的那杯。','That\'s not the drink.'),
    S('kc','酸、咸、经典、摇、不加冰——五个提示，一个都没用上？','Sour, salty, classic, shaken, no ice. Five clues and you used none?'),
    IF('kc_freestyle',[S('kc','说好的。喝掉。','A deal\'s a deal. Drink it.'),N('你当着她的面，把那杯喝了下去。……确实很难喝。','You drink it in front of her. …It really is bad.')]),
    IF('kc_lesson',[S('kc','……白教你了。','…Wasted my lesson on you.')]),
    S('kc','（她站起来，拿起包）','(She stands and picks up her bag.)'),
    CT(8,[N('她把钱放在吧台上就走了，连名片都没留。','She leaves the money on the counter and walks out without a word.')],
      ['「再给我一次。就一次。」','"One more shot. Just one."',2,[
        S('kc','（她停在门口，回头）……我师父说过，敢要第二次的人，才配站吧台。','(She stops at the door and turns.) …My mentor said only people who dare ask for a second go deserve the bar.'),
        S('kc','给你一句话：【酸和咸在吵架，最后和好了】。去吧。','One line for you: 【sour and salt arguing until they make up】. Go.'),
        FLAG('kc_rematch'),
        MX({accept:['paloma','spicy_marg','watermelon_marg','michelada'],best:'margarita',want:['酸','咸'],avoid:['甜','奶香'],str:'mid'},
         [S('kc','（喝完，把杯子轻轻放下）……第二次就对了。比第一次就对的人，更难得。','(She finishes and sets the glass down softly.) …Right on the second try. That\'s rarer than getting it first time.'),
          N('她在吧台上留下一张名片，背面写着：「你是对手。」','She leaves a business card on the counter. On the back: "Consider yourself a rival."'),
          FLAG('kc_card'),AFF(2)],
         [S('kc','……及格。下次别让我等。','…Passing grade. Don\'t make me wait next time.'),
          N('她留下一张名片，背面写着：「其实还行。」','She leaves a card: "Not bad, actually."'),FLAG('kc_card')],
         [S('kc','……算了。','…Forget it.'),N('她走了。门口的风铃响了很久。','She leaves. The door chime rings for a long time.')])]],
      ['（低头擦杯子，不说话）','(Look down and polish a glass, saying nothing)',0,[
        N('她把钱放在吧台上就走了，连名片都没留。','She leaves the money on the counter and walks out without a word.')]])],
   [S('kc','（喝了一口，整个人停住）……','(One sip, and she goes completely still)…'),
    S('kc','这股苦，这股药草味……你从哪学的？','This bitterness, this herbal edge… where did you learn this?'),
    S('kc','我十八岁第一次站吧台，师父给我的第一杯酒，就是这个味道。他说：「苦的东西，要慢慢喝，才知道后面是甜的。」','When I first stood behind a bar at eighteen, the first drink my mentor gave me tasted like this. He said, "Bitter things you drink slowly. That\'s how you find the sweet at the end."'),
    S('kc','……我跟所有人说我爱喝酸的。其实我最爱这个。我师父也是。我们俩，都是嘴硬的人。','…I tell everyone I like sour. This is what I actually love. So did he. We\'re both too stubborn to say what we like.'),
    EMO('💦'),
    N('她把名片放在吧台上。背面原本写好的「你是对手」被划掉了，改成：「你是第二个懂我舌头的人。」','She sets her card on the counter. "Consider yourself a rival" is crossed out on the back, replaced with: "You\'re the second person who\'s understood my palate."'),
    FLAG('kc_card'),FLAG('kc_palate'),TIP(25)]),
  N('（她说的那个"不再调酒"的师父，会是谁呢？店关了、倔、不站别人的吧台……）','(Who is this mentor who "doesn\'t mix anymore"? His bar closed, he\'s stubborn, won\'t work someone else\'s counter…)'),
  IF(['kc_mentor','jiu_story'],[N('（……等一下。这描述，怎么好像在哪听过？）','(…Wait. Why does that sound familiar?)'),EMO('❓')])]},

 {who:'liyutong',steps:[
  CARD('— 01:30 —','— 1:30 AM —'),
  N('一个棕色中分刘海、穿米色针织衫的男生在吧台前站了好一会儿，才小心地坐下。他手里攥着一张折了很多次的歌词纸。','A guy with soft brown curtain bangs and a cream sweater hovers by the bar before finally sitting. He clutches a lyric sheet folded over and over.'),
  S('liyutong','那个……可以点单吗？','Um… can I order?'),
  S('liyutong','等一下我要上去唱一首歌，是……唱给一个人听的。','I\'m about to sing a song… for someone.'),
  S('liyutong','我有点紧张，手一直在抖。','I\'m nervous. My hands won\'t stop shaking.'),
  EMO('💦'),
  C(['是要表白吗？','Is it a confession?',1,[
      S('liyutong','（脸一下子红了）……嗯。','(Turns bright red) …Yeah.'),
      S('liyutong','她叫小满，是我大学同学。我们认识四年了，我一直没敢说。','Her name\'s Xiaoman. We\'ve been friends since uni, four years. I never had the nerve.')]],
    ['紧张很正常，说明你很在乎她。','Being nervous just means you care.',2,[
      S('liyutong','……谢谢你这么说。','…Thank you for saying that.'),
      S('liyutong','她叫小满。下个月她要去别的城市工作了，今天是最后的机会。','Her name\'s Xiaoman. She moves to another city next month. Tonight\'s my last chance.')]],
    ['喝多一点就不紧张了。','Drink more and the nerves go away.',-2,[
      S('liyutong','不、不行，我要【清醒地】把这首歌唱完。','N-no, I want to sing it 【clear-headed】.'),
      S('liyutong','这首歌我练了一个月。','I\'ve practised this song for a month.')]]),
  S('liyutong','我要唱的是《小幸运》……她第一次听我唱歌，就是这首，那时候我们才大一。','I\'m singing the song I sang the first time she ever heard me. We were freshmen.'),
  C(['那她一定会记得。','Then she\'ll remember.',2,[
      S('liyutong','……你觉得会吗？（他的眼睛亮了一下）','…You think so? (His eyes brighten.)')]],
    ['万一她拒绝呢？','What if she says no?',-1,[
      S('liyutong','……那、那至少我说出来了。','…Th-then at least I said it.'),
      S('liyutong','你别吓我啊。','Don\'t scare me like that.')]],
    ['要不要先在这儿练一句？','Want to try a line here first?',1,[
      S('liyutong','（他小声哼了一句，声音很干净）','(He hums one line under his breath. His voice is clear and gentle.)'),
      EMO('♪'),
      S('liyutong','……我是不是唱得还行？','…Was that okay?')]]),
  S('liyutong','我想要一杯【甜一点】、【清爽一点】的，有点【薄荷那种凉凉的】……','Something 【a little sweet】, 【refreshing】, with that 【cool minty feeling】…'),
  S('liyutong','能让我稍微放松，但【不会喝醉】的。对了，她最喜欢【芒果】。……啊，我为什么要说这个。','To calm me down 【without getting drunk】. Oh, and 【mangoes】 are her favourite. …Ugh, why did I say that.'),
  C(['那就调两杯。一杯给你壮胆，一杯你端进去给她。','Then I\'ll make two. One for your nerves, one you carry in for her.',2,[
      S('liyutong','……端、端进去？当着所有人？','…C-carry it in? In front of everyone?'),
      ME('唱完歌，把杯子放到她面前。什么都不用说，杯子替你说。','After the song, set it in front of her. You don\'t have to say a word. The glass says it.'),
      S('liyutong','（他盯着你看了三秒，然后用力点头）……那她那杯，一定要有【芒果】。要【好看】。','(He stares at you for three seconds, then nods hard.) …Then hers has to have 【mango】. And it has to be 【pretty】.'),
      FLAG('ytong_two')]],
    ['先管好你自己。喝完这杯，上台。','Worry about yourself first. Finish this, then go on.',1,[
      S('liyutong','嗯……对。先管好我自己。','Yeah… right. Me first.')]],
    ['她最喜欢芒果，那你最喜欢什么？','Mango\'s her favourite. What\'s yours?',1,[
      S('liyutong','我？（他愣住了）……我好像，从来没想过。','Me? (He blinks.) …I guess I\'ve never thought about it.'),
      S('liyutong','大一那年社团招新，她递给我一杯【接骨木花】汽水。……那应该算吧。','Freshman year, at the club fair, she handed me an 【elderflower】 soda. …I guess that counts.')]]),
  N('（薄荷、清爽、气泡……莫吉托的骨架。至于往里放什么，你说了算。）','(Mint, refreshing, bubbles… a Mojito\'s bones. What goes into it is your call.)'),
  MX({accept:['mojito','virgin_mojito','hugo','cucumber_cooler','midori_sour'],best:'mango_mojito',want:['草本','气泡'],avoid:['烈','苦'],str:'low'},
   [S('liyutong','（喝了一口，薄荷的凉意让他深吸一口气）……好像真的没那么抖了。','(Sips; the cool mint makes him breathe deep) …My hands are steadier.'),
    IF('ytong_two',[N('你把第二杯推到他面前。他双手捧起来，像捧着一封没拆的信。','You slide the second glass over. He lifts it with both hands, like an unopened letter.')],
      [S('liyutong','就当是她在给我加油吧。','I\'ll take it as her cheering me on.')]),
    FLAG('xiaoman_mango')],
   [S('liyutong','嗯……很清爽，谢谢你。','Mm… refreshing. Thank you.'),
    S('liyutong','……不过我想，重要的是我自己，不是杯子。','…But I guess what matters is me, not the glass.')],
   [S('liyutong','这个……味道不太对……','This… doesn\'t taste right…'),
    S('liyutong','我好像更紧张了。手……手更抖了。','I think I\'m even more nervous now. My hands… they\'re worse.'),
    EMO('💦'),
    C(['（把手按在他手背上）跟我数：吸——二、三、四。','(Rest a hand on his) Breathe with me: in, two, three, four.',2,[
        N('你们一起数了三遍。他的手，慢慢不抖了。','You count it together three times. His hands slowly go still.'),
        S('liyutong','……原来不用酒也行啊。','…Turns out I didn\'t need the drink.'),
        FLAG('ytong_breath')]],
      ['那再喝一杯，压一压？','Then have another to settle it?',-2,[
        S('liyutong','不、不行……我要清醒着唱。','N-no… I want to sing sober.')]])],
   [S('liyutong','（喝了一口，整个人安静下来）……这个花香。','(One sip and he goes quiet) …This floral smell.'),
    S('liyutong','大一社团招新，她站在太阳底下，递给我一杯花香味的汽水，说：「你唱歌真好听，要不要来合唱团？」','Freshman club fair. She was standing in the sun, handed me a floral soda and said, "You sing really well. Join the choir?"'),
    S('liyutong','我就是因为那杯汽水，才开始唱歌的。……这件事，我连她都没告诉过。','That soda is the reason I started singing. …I\'ve never even told her that.'),
    N('他把那张皱巴巴的歌词纸翻过来，在背面写下一行字，折好，塞进了口袋。','He flips the crumpled lyric sheet over, writes a line on the back, folds it, and tucks it in his pocket.'),
    FLAG('ytong_letter')]),
  N('走廊那头，有人探出头喊：「李宇童！到你了！」','Someone leans out from down the corridor: "Li Yutong! You\'re up!"'),
  S('liyutong','我、我……','I-I…'),
  N('他站起来，又坐下，又站起来。歌词纸在手里捏得发皱。','He stands, sits back down, stands again. The lyric sheet crumples in his fist.'),
  CT(7,[N('（你还没来得及开口，他已经深吸一口气，转身跑向了包厢。）','(Before you can say a word, he takes a deep breath and runs for the room.)')],
    ['「去吧。你已经练了一个月了。」','"Go. You\'ve practised for a month."',2,[
      S('liyutong','……嗯！','…Yeah!'),
      FLAG('ytong_push')]],
    ['「歌词纸给我，你不需要它了。」','"Give me the lyric sheet. You don\'t need it."',2,[
      N('他愣了一下，把那张皱巴巴的纸放在了吧台上。上面写满了换气的记号。','He hesitates, then sets the crumpled sheet on the counter. It\'s covered in little breathing marks.'),
      S('liyutong','……对，我都背下来了。','…Right. I know it by heart.'),
      FLAG('ytong_push')]],
    ['「要不……下次再说？」','"Maybe… next time?"',-2,[
      S('liyutong','没有下次了。她下个月就走了。','There is no next time. She leaves next month.'),
      N('他自己咬了咬牙，转身走了。','He grits his teeth and goes anyway.')]]),
  IF({tier:'bad'},[N('包厢那边传来他的歌声。开头两句抖得厉害，到副歌才慢慢稳住。','His voice drifts from the room. The first lines shake badly; only at the chorus does it steady.')],
     [N('不一会儿，包厢那边传来一首有点跑调、但很认真的情歌。','Soon a slightly off-key but very sincere love song drifts from the room.')]),
  IF('ytong_breath',[N('（吸——二、三、四。你在吧台后面，跟着他的换气，一起数。）','(In, two, three, four. Behind the bar, you count along with his breaths.)')]),
  N('唱到副歌时，有个女生的声音，跟着一起唱了起来。','At the chorus, a girl\'s voice joins in.'),
  CARD('— 半小时后 —','— Half an hour later —'),
  N('李宇童又回到了吧台，身边多了一个扎马尾的女生。两个人的耳朵都是红的。','Li Yutong is back at the bar, a girl with a ponytail beside him. Both of their ears are red.'),
  S('liyutong','她……她说，她不去别的城市了。','She… she said she\'s not moving after all.'),
  IF('ytong_push',[S('liyutong','谢谢你推了我一把。不然我现在可能还坐在这张凳子上。','Thanks for the push. Otherwise I\'d probably still be on this stool.')]),
  IF('ytong_two',[N('马尾女生手里捧着那第二杯酒，冰都快化了，一口都没舍得喝。「他唱完就把这个放我面前，一句话都不说……笨死了。」','The ponytailed girl is holding that second glass, ice nearly melted, not a sip taken. "He finished the song, put this in front of me and didn\'t say a word… what an idiot."')]),
  IF('xiaoman_mango',[N('马尾女生戳了戳他的杯子，笑着说：「你连我爱吃芒果都记得？」','She pokes his glass, laughing: "You even remembered I love mango?"')]),
  IF('ytong_letter',[N('她手里攥着一张皱巴巴的歌词纸。背面那行字，她没给任何人看，只是一直在笑。','She\'s clutching a crumpled lyric sheet. Whatever\'s written on the back, she won\'t show anyone. She just keeps smiling.')]),
  IF([{aff:'liyutong',min:6},'ytong_push'],[
     S('liyutong','（他鼓起勇气）那个……下个月我们……想在这儿办一个小小的纪念日。第一杯，能请你调吗？','(Working up his nerve) Um… next month we… want to have a little anniversary here. Would you make the first drink?'),
     END('little_fortune','小幸运','Little Fortune')]),
  S('liyutong','下次我们一起来，喝你调的酒！','Next time we\'re both coming, for your drinks!'),
  TIP(15),
  N('（今晚，好像有好几个人，都往前走了一步。）','(Tonight, it seems, quite a few people took one step forward.)')]}
 ]},

// ===================== NIGHT 3 =====================
{title:['暴雨夜','Stormy Night'],
 preview:['下回——一个只写着字母「R」的神秘预订锁住了所有包厢。修网站的程序员、举着自拍杆的直播主，还有一个撑着黑伞、终于推门进来的人。','Next time: a mysterious booking under the single letter "R" locks every room. A programmer racing to fix the site, a streamer with a selfie stick, and the man with the black umbrella, finally walking through the door.'],
 intro:[CARD('— 第三夜 · 22:30 · 红色暴雨预警 —','— Night Three · 10:30 PM · Red Storm Warning —'),
        FX('rain'),
        N('外面下起了暴雨。雨点砸在玻璃门上，像有人在不停地敲。','A storm has rolled in. Rain hammers the glass door like someone knocking without pause.'),
        N('大电视上在放天气预报：红色预警。门口的地垫湿了一大片，包厢里的歌声都被雨声压低了半截。','The big TV shows a red weather warning. The doormat is soaked, and even the karaoke sounds half-drowned by the rain.'),
        IF('kc_card',[N('吧台上那张粉色名片，被你插在了酒柜的格子里。紫光照着它，背面的字若隐若现。','KC\'s pink card is tucked into one of the shelf cubbies. In the purple glow, the words on the back come and go.')]),
        N('（这种天气……还会有人来吗？）','(Weather like this… will anyone even come?)'),
        FX('flash'),
        N('一道闪电。门开了。','Lightning. The door opens.')],
 scenes:[
 {who:'mojie',steps:[
  N('一个盘着低发髻、涂着红唇的女人收起湿透的伞，在门口跺了两下鞋跟，坐得笔直。','A woman with a sleek low bun and red lipstick shakes out her drenched umbrella, taps her heels twice at the door, and sits very straight.'),
  N('（她的手机屏幕亮着一封没写完的邮件。标题是「关于合作终止」。）','(Her phone screen shows an unfinished email. Subject: "Regarding termination of partnership.")'),
  S('mojie','一杯金汤力。……不，等一下。','A gin and tonic. …No, wait.'),
  S('mojie','我今天刚谈崩了一个合作。三个月的心血。','A deal fell through today. Three months of work.'),
  EMO('…'),
  C(['辛苦了。今晚就别想工作了。','Rough day. Leave work at the door tonight.',2,[
      S('mojie','说得轻巧……不过，你说得对。','Easy to say… but you\'re right.')]],
    ['合作对象是谁？','Who was the deal with?',-1,[
      S('mojie','这是商业机密。','That\'s confidential.'),
      S('mojie','……只能说，一个开了很多家店、很难搞的老先生。','…Let\'s just say an old gentleman who owns a lot of venues and is very hard to please.')]],
    ['那您为什么突然改主意了？','Why change your order?',1,[
      S('mojie','因为金汤力是我庆祝的时候才喝的。今天，不配。','Gin and tonic is what I drink to celebrate. Today doesn\'t deserve it.'),
      S('mojie','我要的是它的……【大人版】。更【苦】，更【沉】。','I want its… 【grown-up version】. More 【bitter】. More 【weight】.')]]),
  S('mojie','我做活动策划的。本来想在你们这儿办一场 KTV 歌王比赛，赞助全谈好了。','I\'m an event planner. I wanted to hold a karaoke championship here. Sponsors were all lined up.'),
  S('mojie','结果对方老板说：「我要先看看这家店，配不配。」','Then the owner\'s side said: "I want to see if this place is worthy first."'),
  C(['那就让他来看看。','Then let him come and see.',2,[
      S('mojie','（她第一次笑了）……你倒是有底气。','(For the first time, she smiles.) …You\'ve got nerve.'),
      FLAG('mo_nerve')]],
    ['这家店不就是他的吗？','Isn\'t this place his anyway?',1,[
      S('mojie','这就是我想不通的地方。他好像从来没亲自来过。','That\'s what I don\'t get. He\'s never once set foot here himself.')]],
    ['那位老先生……是不是穿西装、话很少、只喝一杯就走？','That old gentleman… does he wear a suit, barely speak, and leave after one drink?',2,[
      EMO('❗'),
      S('mojie','……你见过他？','…You\'ve met him?'),
      ME('没有。只是听一位常客提起过。','No. A regular mentioned someone like that.'),
      S('mojie','（她盯着你看了几秒）……这家店，比我想的有意思。','(She studies you for a few seconds.) …This place is more interesting than I thought.'),
      FLAG('mo_nerve')],'suit_regular']),
  S('mojie','给我来杯【苦一点】、【经典一点】，能让人清醒的。不要冰块堆成山，【一块大冰】就够。','Give me something 【bitter】 and 【classic】. Something that clears my head. Not a mountain of ice: 【one big cube】.'),
  S('mojie','【不要甜腻的】。我今天不需要被哄。……就当是【金汤力的升级版】吧。','【Nothing cloying】. I don\'t need coddling. …Think of it as 【a gin and tonic, grown up】.'),
  N('（苦、经典、有金酒的影子、一块大冰……三样东西，各不相让。）','(Bitter, classic, a shadow of gin, one big cube… three things, none giving ground.)'),
  MX({accept:['old_fashioned','gin_tonic','mezcal_negroni','last_word','dry_martini','sazerac'],best:'negroni',want:['苦','草本'],avoid:['甜','奶香','果味'],str:'mid'},
   [S('mojie','（喝了一口，眉头慢慢松开）……苦，但是很稳。','(Sips; her brow slowly relaxes) …Bitter, but steady.'),
    S('mojie','尼格罗尼。三样东西，一样一份，谁也不让谁。','A Negroni. Three things, equal parts, none backing down.'),
    S('mojie','就像谈判。','Like a negotiation.'),
    N('她把那封「关于合作终止」的邮件，删了。','She deletes the email titled "Regarding termination of partnership."'),
    S('mojie','谢谢。明天我会再约他们一次——还要带他来这儿，尝尝你的手艺。','Thank you. Tomorrow I\'ll ask for another meeting. And I\'ll bring him here to taste your work.'),
    N('莫姐留下了一笔不小的小费，还有一张写着「谢谢」的便签。','Sister Mo leaves a generous tip and a note that says "Thank you."'),
    IF('mo_nerve',[FLAG('mo_trust')]),TIP(40)],
   [S('mojie','……不是我想的那杯，但方向对了。','…Not the one I had in mind, but the right direction.'),
    S('mojie','（她笑了）好吧，就当提前庆祝下一次成功。','(She smiles.) Fine. To the next deal, then.'),
    S('mojie','下次，我要喝对的那杯。','Next time I want the right one.'),
    N('莫姐把伞留在门口，说明天还会来拿。','Sister Mo leaves her umbrella by the door, saying she\'ll be back for it tomorrow.')],
   [S('mojie','不对。','Wrong.'),
    S('mojie','我说过，今天不需要被哄。','I said I didn\'t need coddling.'),
    IF('mo_nerve',[S('mojie','刚才那句「让他来看看」，说得挺有底气的。……可惜。','That "let him come and see" sounded so sure. …Shame.')]),
    S('mojie','……如果那位老先生来了，你也给他调这个？','…If that old gentleman comes in, is this what you\'d serve him?'),
    N('莫姐放下钱，站起来去拿伞。','Sister Mo puts down the money and stands to fetch her umbrella.'),
    CT(8,[N('莫姐撑起伞，走进了雨里。','Sister Mo opens her umbrella and walks into the rain.')],
      ['「不会。他来的那天，我给他调对的那杯。——您也是。」','"No. The day he comes, I\'ll make him the right one. You too."',2,[
        S('mojie','（她在门口停了很久）……这句话，我替你记着。','(She stands at the door a long time.) …I\'ll hold you to that.'),
        FLAG('mo_trust')]],
      ['「换一杯，我请。」','"Let me make another. On the house."',1,[
        S('mojie','不用了。生意场上，没有"再来一杯"。','No need. In business, there\'s no "one more round."'),
        S('mojie','……不过吧台上，也许有。下次。','…Behind a bar, maybe there is. Next time.')]])],
   [S('mojie','（喝了一口，停住了）……苦的后面，还藏着一层。','(One sip and she stops) …There\'s another layer hiding behind the bitter.'),
    S('mojie','你怎么知道，我每次谈判前都要灌三杯浓缩，再嚼一片薄荷叶？','How did you know I down three espressos and chew a mint leaf before every negotiation?'),
    S('mojie','我从不在人前喝甜的——甜的东西让人觉得你好说话。可苦的、提神的不一样。那是盔甲。','I never drink anything sweet in public. Sweet makes people think you\'re a pushover. Bitter, sharp things are different. They\'re armour.'),
    N('她把那封「关于合作终止」的邮件删了，又新建了一封。标题是：「方案二：吧台」。','She deletes the "termination of partnership" email and opens a new one. Subject: "Plan B: The Bar."'),
    S('mojie','新方案里，我会写上你的名字。老先生不是要看这家店配不配吗？让他先喝你一杯。','I\'m putting your name in the new proposal. The old man wants to know if this place is worthy? Let him drink one of yours first.'),
    FLAG('mo_trust'),FLAG('mo_proposal'),TIP(50)])]},

 {who:'john',steps:[
  CARD('— 23:20 —','— 11:20 PM —'),
  N('雷声里，一个短发、丹凤眼的男生甩着头发冲了进来，卫衣湿得能拧出水。他朝你笑了笑，露出一颗小虎牙。','With the thunder, a guy with sharp phoenix eyes bursts in, shaking out his hair, his hoodie soaked through. He flashes you a grin with one crooked canine.'),
  S('john','Hey bartender! 这雨也太……太……怎么说来着，「倾盆大雨」！对！','Hey bartender! This rain is so… so… what\'s the word, "pouring cats and dogs"! Yes!'),
  S('john','我在国外长大，这是我回国的第一年。今天是感恩节……可这里没人过。','I grew up abroad. First year back. It\'s Thanksgiving today… nobody here celebrates it.'),
  C(['那今晚我陪你过。','Then I\'ll celebrate it with you tonight.',2,[
      S('john','Haha，那你就是我今年第一个要感谢的人。','Haha, then you\'re the first person I\'m thankful for this year.'),
      EMO('✨')]],
    ['想家了？','Missing home?',1,[
      S('john','有一点。我妈每年都会煮一大锅【姜汤】，说是外婆传下来的。【辣辣的，喝完全身都暖】。','A bit. My mom makes a huge pot of 【ginger soup】 every year. Grandma\'s recipe. 【Spicy, warms you right through】.')]],
    ['感恩节就是吃火鸡那个？','Thanksgiving, the turkey thing?',0,[
      S('john','对！可惜你这儿没有火鸡。只有……（他看了看菜单）爆米花。','Yep! Shame you don\'t have turkey. Just… (checks the menu) popcorn.')]]),
  S('john','我回来是想学中文、找工作。结果中文说得像小学生，面试挂了五次。','I came back to learn Chinese and find a job. My Chinese is like a third-grader\'s. Five interviews, five rejections.'),
  S('john','前两天还有人在包厢里叫我「外国人」，我明明长这样。','Someone in a room the other day called me "the foreigner." Look at my face!'),
  EMO('💢'),
  C(['你中文其实说得很好。','Your Chinese is actually really good.',1,[
      S('john','真的？那你听我说个绕口令：四是四，十是十……十四是是……','Really? Then listen to this tongue twister: sì shì sì, shí shì shí… shí sì shì shì…'),
      EMO('💦'),
      S('john','……OK，算了。','…OK, never mind.')]],
    ['在两个地方长大，是你的超能力。','Growing up in two places is a superpower.',2,[
      S('john','……Wow. 没人这么说过。','…Wow. Nobody\'s ever put it like that.'),
      S('john','也许我可以找翻译的工作？我英文和中文……嗯，英文很好。','Maybe I could do translation? My English and Chinese are… well, my English is great.'),
      FLAG('john_translate')]],
    ['那你干嘛回来？','Then why come back?',-1,[
      S('john','……因为我外婆在这儿。她说想在走之前，听我用中文跟她聊天。','…Because my grandma\'s here. She wants to hear me speak Chinese to her before she goes.'),
      N('John 低头看着吧台上的霓虹倒影，没再说话。','John looks down at the neon reflected in the counter and says nothing more.'),
      FLAG('john_grandma')]]),
  S('john','外面好冷。我想要点【辣辣的、暖身的】，【有姜的】那种，最好还【带气泡】。','It\'s freezing. I want something 【spicy and warming】, 【ginger】 maybe, and 【some fizz】.'),
  S('john','我爸以前总用一个【铜杯子】喝……你知道我在说什么吗？','My dad always drank his from 【a copper mug】… you know what I mean?'),
  N('（姜汁啤酒、青柠、铜杯……基酒是伏特加。）','(Ginger beer, lime, a copper mug… with vodka.)'),
  MX({accept:['dark_stormy','gin_tonic','penicillin','apple_highball','spicy_marg'],best:'moscow_mule',want:['辛辣','气泡'],avoid:['苦','奶香'],str:'mid'},
   [S('john','（看到杯子，眼睛一亮）姜！辣辣的，还有泡泡！','(His eyes light up) Ginger! Spicy, and bubbles!'),
    S('john','姜的辣……就像我妈的姜汤一样。','That ginger kick… just like my mom\'s soup.'),
    S('john','Thank you. 突然没那么想家了。','Thank you. I don\'t feel so far from home now.'),
    S('john','明天我去看外婆，跟她说：「我交了一个会调酒的中国朋友。」用中文说。','Tomorrow I\'ll visit Grandma and tell her, in Chinese: "I made a friend who mixes drinks."')],
   [S('john','嗯，有姜味，暖暖的。','Mm, gingery and warm.'),
    S('john','要是用铜杯装就完美了，我爸总说铜杯才是灵魂。','In a copper mug it\'d be perfect. My dad says the mug is the soul of it.'),
    S('john','Next time！','Next time!')],
   [S('john','Hmm……这个好像不太暖。','Hmm… this isn\'t very warming.'),
    S('john','我说的是姜、辣、气泡……还有那个铜杯子。','I meant ginger, spice, bubbles… and that copper mug.'),
    S('john','没事，谢谢你陪我聊天。说中文聊天，我很开心。','It\'s fine. Thanks for the chat. Chatting in Chinese made me happy.')],
   [S('john','（喝了一口，突然不说话了）','(One sip, and he suddenly goes quiet)'),
    S('john','……这个味道。我小时候回来过一次，外婆带我去茶餐厅，点了一杯……咸咸的、酸酸的，有泡泡……','…This taste. I came back once as a kid. Grandma took me to a cha chaan teng and ordered this… salty, sour, fizzy…'),
    S('john','她说那个叫【咸柠七】，感冒了喝一杯就好。那是我唯一一次，听懂她说的每一个字。','She called it 【salted lemon soda】. Said one glass cures a cold. It\'s the only time I understood every word she said.'),
    EMO('💦'),
    S('john','明天我要带外婆去喝。我来点单，用中文。','Tomorrow I\'m taking Grandma for one. I\'ll order. In Chinese.'),
    FLAG('john_grandma'),TIP(20)]),
  IF('john_translate',[S('john','对了！你刚才说的「超能力」——我明天面试就用这个开场。翻译公司。第六次。','Oh! That "superpower" thing, I\'m opening my interview with it tomorrow. Translation firm. Attempt number six.')]),
  N('John 把酒喝完，看了看窗外的雨，没走。他把湿卫衣搭到了暖气片上。','John finishes his drink, eyes the rain outside, and stays put. He drapes his soaked hoodie over the radiator.')]},

 {who:'ya',steps:[
  CARD('— 00:40 —','— 12:40 AM —'),
  N('一个扎着双丸子头的女孩浑身湿透地跑进来，头发上的嫩芽发夹还在滴水。','A girl with two hair buns runs in soaked to the bone, her sprout hair clip still dripping.'),
  S('ya','呜呜……我的手机掉水坑里了，联系不上朋友……','Waaah… my phone fell in a puddle, I can\'t reach my friends…'),
  EMO('💦'),
  S('ya','我能在这儿坐一会儿吗？','Can I sit here for a bit?'),
  C(['当然，先擦擦头发吧。（递上毛巾）','Of course. Here, dry your hair. (Hand her a towel)',2,[
      S('ya','谢、谢谢你……你人真好。','Th-thank you… you\'re so kind.')]],
    ['要不要用店里的电话？','Want to use the bar phone?',1,[
      S('ya','可我不记得她们的号码……只记得我妈的。','But I don\'t remember their numbers… only my mom\'s.'),
      S('ya','打给我妈的话，她会让我立刻回家。','If I call my mom she\'ll make me come home right now.')]],
    ['你成年了吗？','Are you old enough to be here?',0,[
      S('ya','十九岁……我知道，【不能喝酒】啦。','Nineteen… I know, 【no alcohol】.')]]),
  S('ya','我是美院大一的。今天跟室友约好来唱歌庆祝——我的画第一次入选展览了！','I\'m a first-year at art school. My roommates and I were going to celebrate. My painting got into its first exhibition!'),
  S('ya','结果下这么大雨，我们走散了……','Then the storm hit and we got separated…'),
  C(['恭喜！画的是什么？','Congrats! What did you paint?',2,[
      S('ya','一棵从水泥缝里长出来的小芽。','A little sprout growing out of a crack in the concrete.'),
      S('ya','（她指了指发夹）所以大家都叫我「芽」。','(She points at her hair clip.) That\'s why everyone calls me Ya, "sprout".'),
      FLAG('ya_painting')]],
    ['你朋友一定也在找你。','Your friends must be looking for you too.',1,[
      S('ya','嗯……她们说过，找不到人就来 Space 集合。','Yeah… we said if we got lost we\'d meet at Space.'),
      S('ya','所以我就跑来了！','So I ran here!')]],
    ['下雨天就别出门了嘛。','Should\'ve stayed in on a night like this.',-1,[
      S('ya','……可今天是很重要的日子啊。','…But today\'s a really important day.')]]),
  FX('flash'),
  N('窗外一道闪电，紧接着是一声炸雷。头顶的灯闪了一下。','Lightning outside, then a crack of thunder. The lights overhead flicker.'),
  S('ya','呀！','Eek!'),
  EMO('❗'),
  CT(6,[N('（灯稳住了。芽缩在凳子上，过了好一会儿才敢抬头。）','(The lights hold. Ya stays curled on the stool a long while before daring to look up.)')],
    ['「别怕，只是打雷。我在这儿。」','"It\'s okay, just thunder. I\'m right here."',2,[
      S('ya','……嗯。（她慢慢松开了抓着吧台的手）','…Okay. (Slowly, she lets go of the counter.)')]],
    ['（把吧台的小台灯打开，推到她面前）','(Switch on the little counter lamp and push it toward her)',2,[
      N('暖黄色的光落在她手上。她盯着那盏灯，呼吸慢慢平了下来。','Warm yellow light pools on her hands. She stares at the lamp until her breathing steadies.'),
      FLAG('ya_lamp')]],
    ['「哈哈，胆子这么小？」','"Haha, scared of a little thunder?"',-1,[
      S('ya','……我才没有。','…I am not.'),
      EMO('💢')]]),
  N('角落里传来一声咳嗽。John 还没走——他的卫衣搭在暖气片上，正冒着白气。','A cough from the corner. John hasn\'t left. His hoodie is draped over the radiator, steaming.'),
  WHO('john'),
  S('john','Sorry，我听到了……你的朋友们，有没有 Instagram？或者……那个，小红书？','Sorry, I overheard… do your friends have Instagram? Or, um, Xiaohongshu?'),
  WHO('ya'),
  S('ya','有、有的！可我手机坏了……','Th-they do! But my phone\'s dead…'),
  C(['John，借你手机帮她发个定位吧。','John, could you lend her your phone and post the location?',2,[
      WHO('john'),
      S('john','Of course！我打字慢，你自己来——（他把手机递过去）密码是 0000，别笑。','Of course! I type slowly, you do it. (He hands it over.) Passcode is 0000. Don\'t laugh.'),
      WHO('ya'),
      N('芽飞快地发了一条：「我在 Space 吧台！！有个超好的调酒师和一个借我手机的外国……不对，中国人！」','Ya types fast: "I\'m at the Space bar!! There\'s a super nice bartender and a foreign… no wait, Chinese guy who lent me his phone!"'),
      WHO('john'),
      S('john','（看到"中国人"三个字，愣了一下，然后笑得很开心）','(Sees the word "Chinese," blinks, then grins wide.)'),
      AFF(2),
      WHO('ya'),
      FLAG('john_help')]],
    ['先别急，等雨小一点，她们会来的。','No rush. When the rain eases, they\'ll come.',1,[
      S('ya','……嗯。我们说好了的，找不到就来 Space。','…Yeah. We promised: if we get lost, meet at Space.')]],
    ['要不打给你妈妈吧？','Maybe call your mom?',-1,[
      S('ya','……那今天的庆祝就没了。','…Then tonight\'s celebration is over.'),
      EMO('…')]]),
  S('ya','我想喝点【甜甜的】、能让心情好起来的……像【甜点】一样，有一点【奶香】、有一点【水果味】的。','I want something 【sweet】 to cheer me up… like 【a dessert】, a bit 【creamy】, a bit 【fruity】.'),
  S('ya','像……像海边那种【椰子】的味道。但我还【不能喝酒】哦。','Like… like 【coconut】 at the beach. But 【no alcohol】 for me.'),
  N('（甜、奶香、水果、零酒精……照着她说的来，或者——给她一点意想不到的东西。）','(Sweet, creamy, fruity, zero proof… make what she asked for, or give her something she didn\'t see coming.)'),
  MX({accept:['shirley','virgin_mojito','cucumber_cooler'],best:'virgin_colada',want:['甜','奶香','果味','无酒精'],avoid:['烈','苦'],str:'low'},
   [S('ya','（喝了一口，眼睛弯成月牙）……像在海边过暑假！','(Sips, her eyes crinkle into crescents) …Like summer vacation at the beach!'),
    S('ya','心情好多了！我要把这杯画下来！','I feel so much better! I\'m going to paint this!'),
    N('就在这时，门口传来一声：「芽！原来你在这儿！」——她的室友们找来了。','Just then someone calls from the door: "Ya! There you are!" Her roommates have found her.'),
    IF('john_help',[S('ya','（举着 John 的手机）看到我发的了吧！是这位哥哥借我的！','(Waving John\'s phone) You saw my post! This guy lent it to me!')]),
    S('ya','下次画展开幕，我请你来看！','When the exhibition opens, you\'re invited!')],
   [S('ya','好可爱，谢谢你～','So cute, thank you~'),
    S('ya','不过我刚才其实更想要奶奶的、像甜点那种，哈哈。','Though I was kind of craving something creamy, like dessert, haha.'),
    N('没过多久，她的室友们冲了进来，四个人抱成一团。','Before long her roommates burst in, and the four of them collapse into a group hug.')],
   [S('ya','等一下……这里面有酒吗？还是……','Wait… is there alcohol in this? Or…'),
    S('ya','不是我想要的味道……','It\'s not what I wanted…'),
    N('芽把杯子轻轻推开，抱着湿透的外套坐到了角落。','Ya gently pushes the glass away and curls up in a corner with her wet coat.'),
    IF('john_help',[N('John 坐过去，用很烂的中文给她讲了一个更烂的笑话。芽笑出了声。','John sits beside her and tells a terrible joke in terrible Chinese. Ya laughs out loud.')],
      [N('过了一会儿，室友们找来，把她接走了。','Eventually her roommates come to collect her.')])],
   [S('ya','（喝了一口，整个人亮了起来）……哇。哇——！','(One sip and she lights up) …Whoa. Whoa!'),
    S('ya','花香……还有小泡泡在舌头上跳！像春天第一天，我在宿舍楼下看见那棵小芽从水泥缝里钻出来——就是这个感觉！','Flowers… and little bubbles dancing on my tongue! Like the first day of spring, when I saw that sprout pushing out of the concrete under my dorm. Exactly this feeling!'),
    S('ya','我画那幅画的时候，脑子里就是这个味道。我一直不知道怎么跟别人形容……你调出来了！','When I painted it, this was the taste in my head. I never knew how to describe it to anyone… and you mixed it!'),
    N('门口传来一声：「芽！原来你在这儿！」她的室友们冲了进来。芽举着杯子跳起来：「你们快尝！这是我的画的味道！」','"Ya! There you are!" Her roommates burst in. Ya jumps up with the glass: "Taste this! It\'s what my painting tastes like!"'),
    FLAG('ya_wow'),TIP(15)]),
  IF('ya_lamp',[N('走之前，她在杯垫背面画了一盏小台灯，旁边写着：「谢谢你的光。」','Before she goes, she sketches a tiny lamp on the back of a coaster: "Thanks for the light."')]),
  IF(['ya_lamp','ya_painting',{tier:'great'}],[
    N('（那时你还不知道——三个月后，美院的年度展上，有一幅画前面围的人最多。）','(You don\'t know it yet, but three months from now, at the art school\'s annual show, one painting will draw the biggest crowd.)'),
    N('画的是一个暴雨夜的吧台。整幅画都是深紫色，只有正中间一盏小台灯，暖黄色的光落在一只杯子上。杯子里，长出了一棵小芽。','It shows a bar on a stormy night. The whole canvas is deep purple except for one small lamp in the centre, warm yellow light falling on a glass. From the glass, a little sprout is growing.'),
    N('画的名字叫《Space》。作者签名旁边，还有一行小字：「献给那晚给我光的调酒师。」','It\'s titled "Space". Beside the signature, in small letters: "For the bartender who gave me light that night."'),
    END('sprout','芽','Sprout')]),
  CARD('— 02:10 —','— 2:10 AM —'),
  FX('clear'),
  N('暴雨停了。电视上的预警变成了绿色。','The storm passes. The warning on the TV turns green.'),
  N('你拉下卷帘门的时候，看见街对面站着一个人。','As you pull the shutter halfway down, you notice someone across the street.'),
  N('穿西装的老先生，撑着一把黑伞——雨都停了，伞却没收。他远远地看着店的招牌，看了很久。','An old gentleman in a suit under a black umbrella, still open though the rain has stopped. He looks at the sign for a long time.'),
  CT(8,[N('（你还没决定好，他已经转身，消失在了路灯照不到的地方。）','(Before you decide, he turns and vanishes beyond the reach of the streetlights.)')],
    ['（冲他喊一声）「今天已经打烊了——明天请早！」','(Call across to him) "We\'re closed for tonight! Come early tomorrow!"',1,[
      N('他似乎愣了一下。然后，抬起伞沿，冲你微微点了点头，转身走了。','He seems taken aback. Then he tilts up the umbrella, gives you the faintest nod, and walks away.'),
      FLAG('nodded_r')]],
    ['（假装没看见，继续拉门）','(Pretend you didn\'t see, keep pulling the shutter)',0,[
      N('卷帘门「哗啦」落地。再抬头时，街对面已经空了。','The shutter clatters down. When you look up, the street is empty.')]],
    ['（数一数：每周五？今天……是星期五。）','(Count back: every Friday? Today… is a Friday.)',1,[
      N('（酒哥说的那位老客人。每周五，西装，只点那一杯。）','(Brother Jiu\'s old regular. Every Friday, a suit, always that one drink.)'),
      N('你再抬头，他已经走了。只有路灯下，一圈没被雨打湿的干地面。','When you look up again he\'s gone. Only a dry circle of pavement under the streetlight, where the rain never reached.'),
      FLAG('nodded_r')],'suit_regular']),
  FLAG('saw_suit'),
  N('（他是谁？）','(Who is he?)')]}
 ]},

// ===================== NIGHT 4 =====================
{title:['意外的访客','Unexpected Visitor'],
 preview:['下回——歌王之夜。整条街最会唱的人都来了：卫冕三届的老歌王、偷偷报了名的服务生、带着镜头的练习生。理查德坐在评委席。然后——灯，灭了。','Next time: Karaoke King Night. The best voices on the street all show up: a three-time champion, a waiter who secretly signed up, a trainee who brought his own camera crew. Richard sits at the judges\' table. And then the lights go out.'],
 intro:[CARD('— 第四夜 · 20:30 —','— Night Four · 8:30 PM —'),
        N('前台说，今晚有一个神秘的 VIP 预订，名字只写了一个字母：「R」。','The front desk says there\'s a mysterious VIP booking tonight, under a single letter: "R".'),
        N('经理一整晚都在擦已经很干净的吧台。你身后的紫色酒柜，好像也比平时亮。','The manager keeps wiping an already spotless counter. Even the purple shelves behind you seem brighter than usual.'),
        IF('saw_suit',[N('（R……撑黑伞的那个人，会来吗？）','(R… will the man with the black umbrella come?)')]),
        N('奇怪的是，走廊里一点歌声都没有。所有包厢的门，都关着。','Strangely, there\'s no singing in the corridor at all. Every room door is shut.')],
 scenes:[
 {who:'kevin',steps:[
  N('一个戴着细框眼镜、背着双肩包的男生抱着笔记本电脑坐下，屏幕上全是代码。他每隔几秒就推一下眼镜。','A guy in thin-framed glasses and a backpack sits down hugging a laptop full of code. He pushes his glasses up every few seconds.'),
  S('kevin','嗨，麻烦你了……我能在这儿借个插座吗？','Hi, sorry to bother you… could I borrow an outlet?'),
  S('kevin','我是做你们店预订网站的程序员。今晚系统突然崩了，所有包厢都显示「已满」。','I\'m the developer who built your booking site. Tonight it crashed and every room shows as "full."'),
  S('kevin','经理说今晚有大人物来，让我当场修好。','The manager says someone important is coming tonight and I have to fix it on the spot.'),
  EMO('💦'),
  C(['插座在这儿。慢慢来，别慌。','Outlet\'s right here. Take your time, don\'t panic.',2,[
      S('kevin','谢谢……你是今晚第一个跟我说「别慌」的人。','Thanks… you\'re the first person tonight to tell me not to panic.')]],
    ['难怪今晚客人这么少。','So that\'s why it\'s so quiet tonight.',0,[
      S('kevin','……对不起，是我的锅。','…Sorry. That\'s on me.')]],
    ['那你还不快修？','Then shouldn\'t you be fixing it?',-1,[
      S('kevin','我、我在修了……','I-I am fixing it…'),
      N('他的手指在键盘上敲得更快了，额头冒汗。','His fingers fly faster across the keyboard, sweat on his brow.')]]),
  N('键盘声。冰箱的嗡嗡声。走廊里一片死寂。','Keys clicking. The fridge humming. Dead silence from the corridor.'),
  S('kevin','（敲了一会儿，他突然停下）……奇怪。','(He types for a while, then stops.) …That\'s weird.'),
  EMO('❓'),
  S('kevin','不是系统坏了。是有人用管理员账号，把今晚所有包厢都锁了。账号名叫……「R」。','The system isn\'t broken. Someone used an admin account to lock every room tonight. The account is called… "R".'),
  C(['R……就是那个 VIP？','R… the VIP?',2,[
      S('kevin','有可能！可谁会订下整家店，又不来唱歌？','Could be! But who books the whole place and doesn\'t come to sing?'),
      S('kevin','你帮我留意一下，今晚谁坐在吧台却不进包厢。','Keep an eye out for anyone who sits at the bar but never goes into a room.'),
      FLAG('r_hunt')]],
    ['会不会是你自己按错了？','Could you have clicked something by mistake?',-1,[
      S('kevin','……我检查了三遍。不是我。','…I checked three times. It wasn\'t me.')]],
    ['那你能解锁吗？','Can you unlock them?',1,[
      S('kevin','能，但那是管理员权限，我得先问问老板。可我从来没见过老板。','Yes, but that\'s admin-level. I need the owner\'s OK. And I\'ve never met the owner.')]],
    ['……前两天暴雨夜，街对面站着一个撑黑伞的人。','…On the stormy night, someone with a black umbrella stood across the street.',2,[
      S('kevin','（他慢慢转过头）……你是说，有人在盯着这家店？','(He slowly turns his head.) …You mean someone\'s been watching this place?'),
      S('kevin','好，这条线索我记下了。（他新建了一个文件，命名为「R.txt」）','Okay, noted. (He creates a new file named "R.txt".)'),
      FLAG('r_hunt')],'saw_suit']),
  S('kevin','我今晚估计要熬通宵了。给我来一杯能【提神】的，【咖啡】那种。','Looks like an all-nighter. Give me something to 【keep me awake】. 【Coffee】, kind of.'),
  S('kevin','但我酒量不好，【别太冲】……【甜一点、顺一点，冰冰的】，装在【漂亮的杯子】里，我拍给我女朋友看我没偷懒。','But I can\'t drink much, so 【not too harsh】… 【a bit sweet, smooth, ice-cold】, in 【a fancy glass】. I\'ll send her a photo to prove I\'m working.'),
  N('（咖啡、冰、漂亮的杯子……摇出一层细泡沫，放三颗咖啡豆。）','(Coffee, ice-cold, a pretty glass… shake it to a fine foam, three coffee beans on top.)'),
  MX({accept:['cuba_libre','amaretto_sour','white_russian','choc_martini','b52'],best:'espresso_martini',want:['咖啡','优雅'],avoid:['气泡','酸'],str:'mid'},
   [S('kevin','（看着杯子上那层细细的咖啡泡沫）……这也太好看了吧。','(Gazes at the fine coffee foam on top) …This is gorgeous.'),
    S('kevin','浓缩咖啡马天尼。我女朋友说：「你确定你在加班？」哈哈。','An Espresso Martini. My girlfriend says, "Are you sure you\'re working?" Haha.'),
    S('kevin','（喝了一口，他整个人坐直了）……好，我感觉我能把整个系统重写一遍。','(One sip and he sits bolt upright.) …Okay. I feel like I could rewrite the whole system.'),
    CARD('— 二十分钟后 —','— Twenty minutes later —'),
    S('kevin','找到了！R 的账号是从……吧台这台点单机登录的！','Found it! R logged in from… the order terminal right here at the bar!'),
    EMO('❗'),
    S('kevin','我顺手装了个【操作日志】。以后谁登录、从哪台设备登录，都跑不掉。','I also installed an 【activity log】. From now on, nobody logs in without leaving a trail of which device they used.'),
    FLAG('kevin_log'),TIP(15)],
   [S('kevin','嗯，有点提神，谢谢你。','Mm, that perks me up a bit. Thanks.'),
    S('kevin','没那么好看……不过我女朋友说「看起来就很能熬夜」。','Not so pretty… but my girlfriend says it "looks like an all-nighter."'),
    CARD('— 半小时后 —','— Half an hour later —'),
    S('kevin','R 的账号……是从吧台这台点单机登录的。','R\'s account… was logged in from the order terminal at this bar.')],
   [S('kevin','（喝了一口，咳了半天）……这、这对我来说太冲了。','(One sip and a long coughing fit) …Th-that\'s way too strong for me.'),
    S('kevin','我还是喝白开水吧……','I\'ll stick to water…'),
    CARD('— 一小时后 —','— An hour later —'),
    S('kevin','（揉着眼睛）登录地址是……吧台？','(Rubbing his eyes) The login came from… the bar?')],
   [S('kevin','（喝了一口，推眼镜的手停在半空）……奶。','(One sip, and the hand pushing up his glasses freezes mid-air) …Milk.'),
    S('kevin','我女朋友每天早上给我冲一杯加三勺糖的拿铁。我跟所有人说我只喝美式，因为……程序员喝甜拿铁，很丢人。','Every morning my girlfriend makes me a latte with three sugars. I tell everyone I only drink Americanos, because… a programmer drinking sweet lattes is embarrassing.'),
    S('kevin','（他拉开背包的夹层，露出一个小小的丝绒盒子）……下个月，我想跟她求婚。你是第一个知道的。','(He unzips a pocket in his backpack, revealing a small velvet box) …Next month I\'m going to propose. You\'re the first to know.'),
    EMO('✨'),
    S('kevin','好，我感觉我能把整个系统重写一遍。（他的手指飞了起来）','Right. I feel like I could rewrite the whole system. (His fingers take off.)'),
    CARD('— 十分钟后 —','— Ten minutes later —'),
    S('kevin','找到了！R 的账号是从……吧台这台点单机登录的！而且我顺手给系统装了个【操作日志】，以后谁登录、从哪台设备，全都会留下记录。','Found it! R logged in from… the order terminal at this bar! And while I was at it I installed an 【activity log】. From now on, every login and every device gets recorded.'),
    FLAG('kevin_ring'),FLAG('kevin_log'),TIP(20)]),
  N('（吧台的点单机？可今晚，只有你站在这儿啊。）','(The bar terminal? But you\'re the only one who\'s been back here tonight.)'),
  S('kevin','……你、你不会就是 R 吧？','…Y-you\'re not R, are you?'),
  C(['（举起双手）我连管理员密码都不知道。','(Raise both hands) I don\'t even know the admin password.',1,[
      S('kevin','……也对。你看起来不像会锁门的人。','…Fair. You don\'t look like the type to lock doors.')]],
    ['「凶手往往是最不像凶手的那个。」','"The killer is always the one who looks least like one."',0,[
      EMO('💦'),
      S('kevin','别、别吓我！','D-don\'t scare me!')]],
    ['经理下午在这台机器上待了很久。','The manager spent ages at this terminal this afternoon.',2,[
      S('kevin','……经理？可他看起来比我还紧张。','…The manager? But he looks even more nervous than me.'),
      S('kevin','除非……他是在替别人登录。','Unless… he was logging in for someone else.'),
      FLAG('manager_clue')]])]},

 {who:'panda',steps:[
  CARD('— 21:45 —','— 9:45 PM —'),
  N('一个戴着熊猫耳朵发箍、举着手机支架的男生风风火火地冲到吧台前。他每说一句话，耳朵就跟着抖一下。','A guy in a panda-ear headband, holding a phone on a selfie stick, comes barrelling up to the bar. The ears wobble with every word.'),
  S('panda','熊猫来啦！家人们，这就是我说的那家 KTV！看这个紫色酒柜！看这个霓虹吧台！','Panda\'s here! Fam, this is the KTV I told you about! Look at these purple shelves! This neon counter!'),
  S('panda','（把镜头对准你）这位就是传说中的新调酒师！跟大家打个招呼！','(Points the camera at you) And this is the famous new bartender! Say hi to everyone!'),
  EMO('✨'),
  C(['（对着镜头挥手）大家好～','(Wave at the camera) Hi everyone~',2,[
      S('panda','哇，弹幕说你好帅！有人问你有没有对象！','Whoa, chat says you\'re cute! Someone\'s asking if you\'re single!'),
      S('panda','哈哈哈开玩笑的，咱们是正经直播间。','Hahaha, kidding, this is a classy stream.')]],
    ['能不能先别拍我？','Could you not film me?',0,[
      S('panda','好好好，我转过来拍酒柜！家人们，看酒！','Sure sure, I\'ll film the shelves! Fam, look at the bottles!')]],
    ['直播要先问过店里吧？','Shouldn\'t you ask the bar before streaming?',-1,[
      S('panda','我问过了！……问过前台小姐姐了。应该算吧？','I did! …I asked the front desk. That counts, right?'),
      EMO('💦')]]),
  S('panda','跟你说哦，我今晚是来「探店」的，但其实还有一个任务。','So, tonight I\'m doing a venue review, but I\'ve got a secret mission too.'),
  S('panda','我舅舅让我来的。他说：「去 Space 帮我看看，那个新调酒师怎么样。」','My uncle sent me. He said, "Go to Space and tell me what the new bartender\'s like."'),
  C(['你舅舅是谁？','Who\'s your uncle?',1,[
      S('panda','他不让我说！他就是个……很讲究、很老派、只穿西装的老头。','He told me not to say! He\'s just… a very fussy, very old-school guy who only wears suits.'),
      S('panda','他以前天天泡在一家叫「九号」的小酒馆，后来那家店倒了，他就再也不去酒吧了。','He used to live at this little bar called Number Nine. After it closed, he never went to a bar again.'),
      FLAG('panda_secret')]],
    ['所以你是来考察我的？','So you\'re here to inspect me?',2,[
      S('panda','嘘——！别让直播间听到！（他压低声音）对，但我会说你好话的。','Shhh! Not on stream! (He lowers his voice.) Yes, but I\'ll put in a good word.'),
      S('panda','我舅舅特别挑。他说这世上只有一个人调的冬瓜威士忌能喝。','My uncle\'s super picky. He says only one person in the world makes a decent winter melon whisky.'),
      FLAG('panda_secret')]],
    ['你舅舅……是不是每周五都点一杯冬瓜威士忌？','Your uncle… does he order a winter melon whiskey every Friday?',2,[
      EMO('❗'),
      S('panda','你、你怎么知道？！家人们，这个调酒师会读心！','H-how do you know?! Fam, this bartender reads minds!'),
      S('panda','（压低声音）……对。以前每周五，雷打不动。那家店倒了以后，他就再也没喝过。','(Lowering his voice) …Yes. Every Friday, without fail. After that bar closed, he never had it again.'),
      FLAG('panda_secret')],'suit_regular']),
  S('panda','我舅舅说，看一个调酒师，就看他给【不会喝酒的人】调什么。','My uncle says you judge a bartender by what they make for 【someone who can\'t drink】.'),
  S('panda','我自己嘛，【不太能喝酒】，喝一点就脸红。','Me, I 【can\'t really drink】. One sip and I\'m red as a tomato.'),
  S('panda','想要【有茶香】的、【带点花香】的，【淡淡的】、温温柔柔的。','I want something 【with tea】 in it, 【a little floral】, 【light】, gentle.'),
  S('panda','家人们说要「国风」一点！【桂花】那种秋天的感觉！','Chat wants it "Chinese-style"! Something autumnal, like 【sweet osmanthus】!'),
  C(['给你舅舅也带一句话？','Want to pass a message to your uncle?',1,[
      S('panda','带什么？','Like what?'),
      ME('就说：吧台随时欢迎他。不用站在街对面。','Tell him the bar\'s open to him any time. He doesn\'t have to stand across the street.'),
      S('panda','（他张大了嘴）……你知道他站过街对面？他连我都没说！','(His mouth falls open) …You know he stood across the street? He didn\'t even tell me that!'),
      FLAG('panda_msg')],'saw_suit'],
    ['弹幕想要国风？那就让弹幕来点单。','Chat wants Chinese-style? Let chat order.',2,[
      S('panda','家人们！调酒师说让你们点单！快刷！','Fam! The bartender says you can order! Spam it!'),
      N('弹幕疯狂滚动：「桂花！」「乌龙！」「茉莉！！」「加冬瓜茶！」「加辣椒！！」（最后这个被 Panda 屏蔽了）','Chat goes wild: "Osmanthus!" "Oolong!" "JASMINE!!" "Winter melon tea!" "Add chili!!" (Panda bans that last one.)'),
      S('panda','家人们投票结果：【茉莉】和【桂花】打平了！你来决胜负！','Fam\'s vote: 【jasmine】 and 【osmanthus】 tied! You break the tie!'),
      FLAG('panda_chat')]],
    ['你自己想喝什么？别管弹幕。','What do YOU want? Forget the chat.',1,[
      S('panda','（他愣了一下，把手机扣在了吧台上）……我？','(He blinks and lays the phone face-down on the counter) …Me?'),
      S('panda','我其实……想喝点【甜的】。小时候我舅舅带我去「九号」，酒哥会给我一杯加了很多糖的东西，说是"大人的饮料"。','Honestly… something 【sweet】. When I was little my uncle took me to Number Nine, and Brother Jiu gave me something with loads of sugar and called it a "grown-up drink."'),
      FLAG('panda_real')]]),
  MX({accept:['jager_tea','wm_whisky','jasmine_gin','matcha_highball','yuzu_soju'],best:'osmanthus_oolong',want:['茶','花香','温和'],avoid:['烈','苦'],str:'low'},
   [S('panda','（喝了一口，眼睛瞪圆）……桂花！乌龙！家人们，这个是真的好喝！','(One sip and his eyes go wide) …Osmanthus! Oolong! Fam, this is genuinely delicious!'),
    S('panda','弹幕都在刷「国风天花板」！','Chat is spamming "peak Chinese style"!'),
    S('panda','（他偷偷发了条消息，过了一会儿，手机震了一下）……我舅舅回了。','(He sends a quick message; a moment later his phone buzzes.) …My uncle replied.'),
    S('panda','他说：「不错。我这就过来。」……等等，他就在附近？！','He says: "Not bad. I\'m coming over." …Wait, he\'s nearby?!'),
    EMO('❗')],
   [S('panda','嗯～有茶味！淡淡的，挺舒服！','Mm~ tea! Light and comfy!'),
    S('panda','弹幕说「不够国风」，哈哈，别理他们，我喜欢！','Chat says "not Chinese-style enough", haha, ignore them, I like it!'),
    S('panda','（手机震了一下）我舅舅说：「还行。我过来看看。」','(His phone buzzes.) My uncle says: "Acceptable. I\'ll come take a look."')],
   [S('panda','（喝了一口，脸瞬间红透）……家人们，我、我好像有点晕。','(One sip and his face goes beet red) …Fam, I, I think I\'m a bit dizzy.'),
    EMO('💦'),
    S('panda','这个不是我想要的那种淡淡的……','This isn\'t the light gentle thing I wanted…'),
    S('panda','（手机震了一下）我舅舅说：「我亲自来看看。」……完了。','(His phone buzzes.) My uncle says: "I\'ll see for myself." …Uh oh.')],
   [S('panda','（喝了一口，熊猫耳朵都竖起来了）……甜的！','(One sip and his panda ears practically stand up) …It\'s sweet!'),
    S('panda','家人们……我能关一下直播吗？（他真的关了）','Fam… can I end the stream for a sec? (He actually does.)'),
    S('panda','这个味道，跟小时候酒哥给我的那杯"大人的饮料"一模一样。我舅舅坐我旁边喝冬瓜威士忌，酒哥给我倒这个，说："小朋友，等你长大了，叔叔给你调真的。"','This tastes exactly like the "grown-up drink" Brother Jiu gave me when I was little. My uncle sat next to me with his winter melon whiskey, and Brother Jiu poured me this and said, "Kid, when you\'re grown, I\'ll make you the real thing."'),
    S('panda','后来「九号」就没了。我舅舅再也不提那家店，可他手机密码，到现在还是「九号」开业那天——【0909】。','Then Number Nine was gone. My uncle never mentions it, but his phone passcode is still the day it opened: 【0909】.'),
    S('panda','……啊，我是不是说了不该说的。','…Oh. Did I just say something I shouldn\'t have?'),
    N('（他手机震了一下。）','(His phone buzzes.)'),
    S('panda','我舅舅说：「我这就过来。」……他就在附近？！','My uncle says: "I\'m coming over." …He\'s nearby?!'),
    FLAG('panda_pin'),TIP(15)]),
  N('Panda 关掉直播，紧张地整了整熊猫发箍，一直盯着门口。','Panda ends the stream, nervously straightens his panda ears, and keeps his eyes on the door.')]},

 {who:'richard',steps:[
  CARD('— 22:30 —','— 10:30 PM —'),
  FX('dark'),
  N('门开了。店里的灯，好像被谁调暗了一档。','The door opens. The lights seem to dip, as if someone turned them down a notch.'),
  N('一位穿深灰西装、头发微分的男人走了进来，手里拿着一把收好的黑伞。今晚没有下雨。','A man in a charcoal suit with neatly parted hair walks in, holding a furled black umbrella. It isn\'t raining tonight.'),
  IF('saw_suit',[N('（是那天暴雨夜，站在街对面的那个人。）','(It\'s the man who stood across the street on the stormy night.)')]),
  S('panda','舅、舅舅！','Un-Uncle!'),
  S('richard','晚上好。我叫理查德。','Good evening. I\'m Richard.'),
  S('richard','我的外甥打扰你了吧。','I trust my nephew hasn\'t been a nuisance.'),
  IF('nodded_r',[S('richard','……上次你让我「明天请早」。我来得，够早吗？','…Last time you told me to "come early tomorrow". Am I early enough?'),EMO('…')]),
  CT(9,[N('（他没等你回答，自己坐了下来。那双眼睛，从进门起就没离开过你的手。）','(He doesn\'t wait for an answer and takes a seat. Since he walked in, his eyes haven\'t left your hands.)')],
    ['他很可爱，直播间也很热闹。','He\'s great. His stream was lively.',2,[
      S('richard','（嘴角动了一下，几乎算是在笑）……那就好。','(The corner of his mouth twitches, almost a smile.) …Good.')]],
    ['您就是那个「R」吧？','You\'re "R", aren\'t you?',1,[
      S('richard','（他看了你一眼）……眼神不错。','(He studies you.) …Observant.'),
      FLAG('r_guess')]],
    ['是您让经理用吧台的点单机，锁了所有包厢。','You had the manager lock every room from the bar terminal.',3,[
      EMO('❗'),
      S('richard','……（他沉默了两秒，然后轻轻鼓了两下掌）','…(Two seconds of silence. Then he claps, twice, softly.)'),
      S('richard','我原本还准备了一套说辞。看来用不上了。','I had a whole explanation prepared. It seems I won\'t need it.'),
      FLAG('r_guess')],'manager_clue']),
  FX('light'),
  S('richard','我是这家店的投资人。Space 开张那天，我就在街对面看着。','I\'m the investor behind this place. On opening night, I watched from across the street.'),
  S('richard','我把今晚的包厢都锁了，只想安静地坐在吧台，看看我请来的调酒师，到底怎么样。','I locked every room tonight. I just wanted to sit quietly at the bar and see what kind of bartender I\'d hired.'),
  S('richard','用你的点单机登录，是我请经理帮的忙。抱歉，吓到那位程序员了。','I had the manager log in from your terminal. My apologies to the young programmer.'),
  S('kevin','（在角落里长长地松了一口气）……不是我的锅。不是我的锅。','(In the corner, a very long breath) …Not my fault. Not my fault.'),
  S('richard','那么，你看到了什么？或者说……你想问我什么？','So. What have you seen? Or rather… what would you like to ask me?'),
  C(['您看到了什么？','What have you seen?',2,[
      S('richard','我看到你给一个不会喝酒的孩子，调了一杯让他骄傲的饮料。','I\'ve seen you make a kid who can\'t drink feel proud of his glass.'),
      S('richard','我看到你让我的老朋友，想起了他的酒馆。','I\'ve seen you remind an old friend of mine of his bar.')]],
    ['您太神秘了，大家都很紧张。','All this mystery made everyone nervous.',0,[
      S('richard','嗯。这是我的坏习惯。','Yes. A bad habit of mine.')]],
    ['所以那天莫姐谈崩的合作，也是您？','So Sister Mo\'s collapsed deal was with you too?',1,[
      S('richard','（他挑了挑眉）消息很灵通。','(He raises an eyebrow.) Well informed.'),
      S('richard','对。我说「先看看这家店配不配」，今晚就是答案。','Yes. I said I wanted to see if this place was worthy. Tonight is my answer.')]],
    ['KC 的师父……是酒哥吧？您一定认识。','KC\'s mentor… it\'s Brother Jiu, isn\'t it? You must know.',2,[
      S('richard','（他第一次露出了意外的表情）……你连这个都看出来了。','(For the first time, he looks surprised.) …You worked that out too.'),
      S('richard','「九号」关门那年，他把最得意的徒弟赶去了隔壁街。他说：「别跟着我一起沉。」','The year Number Nine closed, he sent his best apprentice to the next street over. He told her, "Don\'t sink with me."'),
      S('richard','那姑娘至今不肯原谅他。','The girl still hasn\'t forgiven him.'),
      FLAG('kc_is_jiu')],['kc_mentor','jiu_story']]),
  S('richard','很多年前，老街有家小酒馆叫「九号」。我每周五都去，只点一杯酒。','Years ago, there was a little bar on the old street called Number Nine. I went every Friday and ordered one drink.'),
  S('richard','但今晚不点那杯。那杯，我要等它的老板亲手调。','But not that one tonight. That one I\'ll wait for its owner to make himself.'),
  S('richard','给我一杯【真正的经典】。【只有酒】，不要果汁，不要汽水。【搅拌，不要摇】。','Give me 【a true classic】. 【Spirits only】, no juice, no soda. 【Stirred, not shaken】.'),
  S('richard','要【干一点】、【清冽一点】，带点【草本】的味道。杯子要冰，【不放冰块】，【放一颗橄榄】。','【Dry】, 【crisp】, a little 【herbal】. A chilled glass, 【no ice】, and 【an olive】.'),
  N('（金酒、干味美思、搅拌、橄榄……这是在考你最基本、也最难的那一杯。）','(Gin, dry vermouth, stirred, an olive… he\'s testing you on the simplest, hardest drink there is.)'),
  C(['您为什么后来再也不去酒吧了？','Why did you stop going to bars?',1,[
      S('richard','（他的手指在伞柄上停了一下）……因为我欠「九号」一样东西。','(His fingers pause on the umbrella handle) …Because I owe Number Nine something.'),
      S('richard','欠的东西没还，就没脸坐在别人的吧台前。……今晚是例外。','When you owe a debt you haven\'t paid, you have no business sitting at anyone\'s bar. …Tonight is an exception.'),
      FLAG('r_debt')]],
    ['今晚您想喝什么，都可以。','Whatever you\'d like tonight, I\'ll make it.',1,[
      S('richard','口气不小。好。','Confident. Good.')]],
    ['莫姐的新方案，您看了吗？','Have you seen Sister Mo\'s new proposal?',2,[
      S('richard','（他从内袋里抽出一份文件，第一页就是你的名字）……看了。所以我才来。','(He draws a document from his inner pocket. Your name is on the first page.) …I have. That\'s why I came.'),
      FLAG('r_proposal')],'mo_proposal']),
  MX({accept:['manhattan','negroni','sake_tini','last_word','sazerac'],best:'dry_martini',want:['草本','烈','优雅'],avoid:['甜','果味','气泡','奶香'],str:'high'},
   [S('richard','（他举起杯子，对着灯光看了一眼，才喝了一小口）','(He raises the glass to the light before taking a small sip.)'),
    S('richard','……清澈，冰冷，一点不多，一点不少。','…Clear, cold, nothing extra, nothing missing.'),
    S('richard','我看人很少看错。','I\'m rarely wrong about people.'),
    S('richard','下个月，Space 会办一场歌王比赛。我会让莫小姐重新谈。那天晚上的吧台，交给你。','Next month Space will hold a karaoke championship. I\'ll have Ms. Mo reopen the talks. The bar that night is yours.'),
    S('richard','另外……替我告诉酒哥，周五我会来。','And… tell Brother Jiu I\'ll be here on Friday.'),
    N('Panda 在旁边激动得把熊猫耳朵都捏扁了。','Beside him, Panda is so excited he squashes his own panda ears.'),TIP(50)],
   [S('richard','（他尝了一口，停顿了很久）……不是我点的那杯，但很稳。','(He sips and pauses for a long time.) …Not the drink I asked for. But steady.'),
    S('richard','调酒和做人一样，先稳，再精。','Bartending is like life. First be steady, then be precise.'),
    S('richard','下个月有一场歌王比赛。到时候，我想再喝一次——要对的那杯。','There\'s a karaoke championship next month. I\'d like to try again then. The right drink.'),
    S('richard','对了，替我跟酒哥说一声：周五见。','And tell Brother Jiu: see you Friday.')],
   [S('richard','（他只闻了一下，就把杯子放下了）','(He only smells it before setting it down.)'),
    S('richard','……你还年轻。','…You\'re still young.'),
    S('richard','我说的是：只有酒、搅拌、要干、要冰、一颗橄榄。','I said: spirits only, stirred, dry, chilled, one olive.'),
    S('richard','歌王比赛那晚，我再给你一次机会。别让我外甥丢脸。','On the night of the championship, I\'ll give you another chance. Don\'t embarrass my nephew.'),
    S('panda','（冲你比了个「加油」的口型）','(Mouths "you got this" at you.)')],
   [S('richard','（他喝了一口，很久没有放下杯子）','(He sips, and doesn\'t set the glass down for a long time.)'),
    S('richard','……苦。','…Bitter.'),
    S('richard','「九号」关门那晚，酒哥请所有人喝酒。轮到我，他倒了一杯全店最苦的，说：「这杯，你自己知道为什么。」','The night Number Nine closed, Brother Jiu poured for everyone. When he got to me, he gave me the bitterest thing in the house and said, "You know why this one\'s yours."'),
    S('richard','我喝完了。一滴没剩。从那以后，我就只喝苦的。','I finished it. Every drop. I\'ve only drunk bitter things since.'),
    N('（他没有解释为什么。可他握杯子的手，指节发白。）','(He doesn\'t explain why. But his knuckles are white around the glass.)'),
    S('richard','……你调的这杯，比他那杯温柔。歌王比赛那晚，吧台交给你。','…Yours is gentler than his was. On championship night, the bar is yours.'),
    S('richard','替我告诉酒哥——周五，我会来。这次，我会把欠的东西还上。','Tell Brother Jiu: Friday, I\'ll come. And this time I\'ll pay what I owe.'),
    FLAG('r_debt'),FLAG('r_bitter'),TIP(60)]),
  FLAG('met_r'),
  N('理查德走后，经理拍着你的肩膀，激动得说不出话来。','After Richard leaves, the manager grabs your shoulder, too excited to speak.'),
  N('Kevin 解锁了所有包厢。走廊里，歌声一间接一间地亮了起来。','Kevin unlocks every room. Down the corridor, songs light up one room after another.'),
  IF('kc_is_jiu',[N('（KC 的师父是酒哥。理查德是「九号」的老常客。这三个人之间，到底发生过什么？）','(KC\'s mentor is Brother Jiu. Richard was Number Nine\'s old regular. What happened between the three of them?)')]),
  CARD('— 一个月后 —','— One month later —'),
  N('歌王之夜，到了。','Karaoke King Night has arrived.')]}
 ]},

// ===================== NIGHT 5 =====================
{title:['歌王之夜','Karaoke King'],
 preview:['下回——停电之后。黑暗里，奖杯不见了，理查德也不见了。应急灯下，每一位客人都有一个说不清的五分钟。凶手，往往是最不像凶手的那个。','Next time: after the blackout. In the dark, the trophy is gone, and so is Richard. Under the emergency lights, every guest has five minutes they can\'t account for. The killer, as they say, is the one who looks least like one.'],
 intro:[CARD('— 第五夜 · 歌王之夜 · 19:30 —','— Night Five · Karaoke King Night · 7:30 PM —'),
        N('大厅的沙发全被挪到了墙边，正中搭了一个小小的舞台。大电视上滚动着一行字：「Space 第一届歌王争霸赛」。','The lounge sofas have been pushed to the walls and a small stage stands in the middle. The big TV scrolls: "Space\'s First Karaoke King Championship."'),
        N('彩带、气球、还有一个镀金的话筒造型奖杯，摆在吧台尽头。经理已经擦了它四十分钟。','Streamers, balloons, and a gold-plated microphone trophy at the end of your counter. The manager has been polishing it for forty minutes.'),
        N('他擦着擦着，底座「咔」地松了一圈——原来是拧上去的，里面是【空心】的。经理吓得赶紧拧回去：「理查德先生亲自送来的，碰坏了我就完了！」','Mid-polish, the base gives a little click and turns. It screws on, and it\'s 【hollow】 inside. The manager hastily screws it back: "Mr. Richard brought this himself! If I break it I\'m finished!"'),
        S('mojie','（一身黑色西装套裙，耳麦，手里一沓流程单）今晚的吧台，靠你了。','(Black suit, headset, a stack of run sheets in hand) The bar is yours tonight.'),
        N('她手腕上一只细细的金手链，跟着她翻流程单的动作一晃一晃。','A fine gold bracelet on her wrist swings as she flips through the run sheets.'),
        IF('mo_trust',[S('mojie','（她压低声音，把流程单翻到最后一页给你看）这一页只有你、我、理查德先生知道。','(Lowering her voice, she flips to the last page for you) Only you, me and Mr. Richard know about this page.'),
          N('最后一行写着：「23:50　【特别环节】（R）——灯光：全暗十秒，追光。」','The last line reads: "23:50 【Special Segment】 (R). Lighting: full blackout ten seconds, then spotlight."'),
          S('mojie','到时候灯会暗一下。别慌，那是安排好的。','The lights will go down for a moment then. Don\'t panic. It\'s planned.'),
          FLAG('saw_runsheet')]),
        IF('mojie_great',[S('mojie','那杯尼格罗尼，我谈判前又自己调了一杯。没你调的好喝。','I made myself a Negroni before the final negotiation. Wasn\'t as good as yours.')],
           [S('mojie','这次，别让我失望。','This time, don\'t let me down.')]),
        N('评委席上，理查德坐在正中间，手边放着那把黑伞。','At the judges\' table, Richard sits in the middle, the black umbrella beside him.'),
        N('然后，门开了。酒哥走了进来——他今天剃了胡子，穿了一件明显很久没穿过的衬衫。','Then the door opens. Brother Jiu walks in. He\'s shaved, and he\'s wearing a shirt he clearly hasn\'t worn in years.'),
        N('他和理查德的目光，在半空中碰了一下。','His eyes meet Richard\'s, halfway across the room.'),
        S('jiuge','……周五。你说你周五会来。我等了三个周五。','…Friday. You said you\'d come on Friday. I waited three Fridays.'),
        S('richard','我来了。只是，没进门。','I came. I just didn\'t come in.'),
        EMO('…'),
        IF('jiuge_great',[S('jiuge','（他转向你）待会儿给这老家伙调一杯冬瓜威士忌。……就说，是「九号」请的。','(He turns to you.) Later, make this old man a winter melon whiskey. …Tell him it\'s on Number Nine.'),FLAG('nine_reunion')],
           [S('jiuge','（他转向你，压低声音）待会儿要是看见我俩吵起来，记得给我上杯水。','(He turns to you, voice low.) If you see us start arguing later, remember to bring me water.')]),
        IF('kc_is_jiu',[N('门口一阵风铃声。KC 抱着手臂站在那儿，看了酒哥一眼，又看向别处。','The door chimes. KC stands there, arms folded, glances at Brother Jiu, then looks away.'),
                        S('kc','我是来看比赛的。别多想。','I\'m here for the contest. Don\'t read into it.')]),
        N('（今晚，好像有很多故事，要在同一个晚上收尾。）','(Tonight, it seems, a lot of stories are trying to end on the same night.)')],
 scenes:[
 {who:'xiaochen',steps:[
  CARD('— 20:10 · 初赛 —','— 8:10 PM · First Round —'),
  N('一个穿黑马甲、别着金色名牌的年轻服务生，端着一托盘空杯子停在吧台边。名牌上写着「小陈」。','A young server in a black vest and a gold name badge stops at the counter with a tray of empties. The badge reads "Xiao Chen".'),
  N('他是 Space 的服务生。这一个月，你们每天打照面，可他几乎没跟你说过话——只是擦杯子的时候，总在小声哼歌。','He\'s one of Space\'s servers. You\'ve crossed paths every day for a month, yet he\'s barely spoken to you. He just hums under his breath while polishing glasses.'),
  S('xiaochen','……那个，帮我个忙。','…Hey. Do me a favour.'),
  S('xiaochen','我报名了。用的是「陈小」这个名字。经理不知道。','I signed up. Under the name "Chen Xiao". The manager doesn\'t know.'),
  EMO('💦'),
  C(['原来你一直哼的那些歌，是在练习？','So all that humming was practice?',2,[
      S('xiaochen','（他愣了一下，耳朵红了）……你听到了？','(He blinks; his ears go red.) …You heard that?'),
      S('xiaochen','以前我在乐队当主唱。有一次选秀，唱到一半破音了。之后，就再也没上过台。','I used to front a band. At an audition once, my voice cracked halfway through. I haven\'t been on a stage since.')]],
    ['服务生参赛，经理会同意吗？','Will the manager let staff compete?',0,[
      S('xiaochen','所以才没告诉他啊……','That\'s why I didn\'t tell him…')]],
    ['用假名？你是怕输吧。','A fake name? You\'re scared of losing.',-1,[
      S('xiaochen','……我是怕赢了，就没有借口了。','…I\'m scared of winning. Then I\'d have no excuses left.'),
      EMO('…')]]),
  S('xiaochen','我在第三个上场。轮到我的时候，经理一定会叫我去送酒……','I\'m third up. When it\'s my turn, the manager\'s bound to send me on a drinks run…'),
  C(['到时候你的托盘，我来送。','When it\'s your turn, I\'ll take your tray.',2,[
      S('xiaochen','……你认真的？','…Are you serious?'),
      S('xiaochen','（他把托盘往你这边推了推，笑了。这是你第一次看见他笑）','(He nudges the tray toward you and smiles. The first smile you\'ve ever seen from him.)'),
      FLAG('cover_chen')]],
    ['我帮你跟经理说一声？','Want me to tell the manager for you?',1,[
      S('xiaochen','别！……算了，要说也是我自己说。','Don\'t! …No. If anyone tells him, it should be me.')]],
    ['我只负责调酒，别的帮不了你。','I just mix drinks. Can\'t help with the rest.',-1,[
      S('xiaochen','……也是。抱歉。','…Right. Sorry.')]]),
  S('xiaochen','上台前，给我来一杯吧。我还在上班，【不能太烈】，【清醒】最重要。','Make me something before I go on. I\'m still on shift, so 【nothing strong】. I need to 【stay clear-headed】.'),
  S('xiaochen','【酸一点】的，【带气泡】，像【柠檬汽水】那样，喝完嗓子是【清爽】的。','Something 【a bit sour】, 【fizzy】, like 【lemonade】, so my throat feels 【clean】 after.'),
  C(['喜欢金酒的味道吗？','Do you like gin?',1,[
      S('xiaochen','乐队那几年，我们只喝得起最便宜的金酒，兑汽水。……挺怀念的。','Back in the band we could only afford the cheapest gin, topped with soda. …I kind of miss it.')]],
    ['要不要加点糖？','Want a little sugar in it?',1,[
      S('xiaochen','一点点。【酸里带一点甜】，就像……第一次上台前那种心情。','A little. 【Sour with a touch of sweet】, like… the feeling before your first time on stage.')]],
    ['（递上一杯温水）先润润嗓子。','(Hand him warm water) Rest your voice first.',2,[
      S('xiaochen','……谢谢。你跟酒哥说的一样，会照顾人。','…Thanks. You really do look after people, like Brother Jiu said.')]]),
  N('（柠檬、糖、金酒、苏打加满……一杯会冒泡的柠檬水，给大人的那种。）','(Lemon, sugar, gin, topped with soda… fizzy lemonade, the grown-up kind.)'),
  MX({accept:['gin_tonic','mojito','jp_highball','cucumber_cooler','yuzu_soju','paloma'],best:'tom_collins',want:['气泡','温和'],avoid:['烈','奶香'],str:'low'},
   [S('xiaochen','（喝了一口，闭上眼睛）……就是这个味道。','(Sips and closes his eyes) …That\'s the taste.'),
    S('xiaochen','乐队解散那天，我们几个人在天台上，喝的就是这种冒泡的、酸酸的东西。','The day the band broke up, we sat on a rooftop drinking something fizzy and sour like this.'),
    S('xiaochen','（他把马甲上的名牌摘下来，放在吧台上）帮我保管一下。现在，我是「陈小」。','(He unpins the name badge and sets it on the counter.) Hold this for me. Right now, I\'m "Chen Xiao".'),
    N('金色的名牌，就放在吧台尽头，离奖杯不到一掌远。','The gold badge sits at the end of the counter, less than a hand\'s width from the trophy.'),
    FLAG('chen_badge'),EMO('✨')],
   [S('xiaochen','嗯，很清爽。嗓子舒服多了。','Mm, refreshing. My throat feels much better.'),
    S('xiaochen','……不过手还是在抖。没关系，抖着唱也是唱。','…My hands are still shaking, though. That\'s fine. You can sing with shaking hands.')],
   [S('xiaochen','（皱了皱眉）……这个有点冲。','(Frowns) …That\'s a bit harsh.'),
    S('xiaochen','我还在上班啊……','I\'m still on shift…'),
    EMO('💦')],
   [S('xiaochen','（喝了一口，整个人僵住）……你在里面放了什么？','(One sip and he goes rigid) …What did you put in this?'),
    S('xiaochen','乐队第一次演出，在海边的草地上。台下就十几个人，海风咸咸的，草被太阳晒得发香。那是我这辈子唱得最好的一次。','Our band\'s first gig was on a lawn by the sea. A dozen people in the audience, the wind salty, the grass smelling warm in the sun. Best I\'ve ever sung.'),
    S('xiaochen','后来的选秀，灯光、评委、镜头……我再也没找回那天的感觉。','The auditions after that, the lights, the judges, the cameras… I never found that feeling again.'),
    S('xiaochen','（他摘下名牌，放在吧台上）帮我保管。今晚，我想当一次海边的那个人。','(He takes off his badge and sets it on the counter) Hold this. Tonight I want to be that guy by the sea again.'),
    N('金色的名牌，就放在吧台尽头，离奖杯不到一掌远。','The gold badge sits at the end of the counter, less than a hand\'s width from the trophy.'),
    FLAG('chen_badge'),FLAG('chen_sea'),TIP(15)]),
  N('台上，主持人念出了下一个名字：「陈——小——！」','On stage, the host calls the next name: "Chen… Xiao!"'),
  N('经理在大厅另一头举起手：「小陈！三号包厢要六杯啤酒！」','At the same moment the manager waves from across the room: "Xiao Chen! Room three wants six beers!"'),
  CT(7,[N('（你还在犹豫，小陈已经下意识地端起了托盘。舞台上的话筒，空了好几秒。）','(While you hesitate, Xiao Chen reflexively picks up the tray. The mic on stage stands empty for several long seconds.)'),
        N('最后，是他自己把托盘放下，咬着牙跑上了台。开头慢了半拍。','In the end he sets the tray down himself, jaw tight, and runs for the stage. He comes in half a beat late.')],
    ['（一把接过托盘）「去！啤酒我送！」','(Grab the tray) "Go! I\'ll take the beers!"',2,[
      N('小陈愣了半秒，转身冲上了台。','Xiao Chen freezes for half a second, then turns and sprints for the stage.'),
      FLAG('chen_sang')],'cover_chen'],
    ['（冲经理喊）「经理！三号的啤酒我来！」','(Call to the manager) "Boss! I\'ve got room three!"',1,[
      N('经理一愣，挥了挥手。小陈趁机溜上了台。','The manager blinks and waves you on. Xiao Chen slips up to the stage.'),
      FLAG('chen_sang')]],
    ['（假装没听见）','(Pretend you didn\'t hear)',-1,[
      N('小陈看了你一眼，把托盘放下，自己跑上了台。','Xiao Chen glances at you, sets the tray down, and runs up on his own.')]],
    ['（假装去拿冰，把经理挡在后面）','(Pretend to fetch ice, blocking the manager\'s view)',1,[
      N('经理被你和冰桶挡了个结实。等他绕过来，台上已经响起了前奏。','You and the ice bucket block the manager completely. By the time he gets around you, the intro is already playing.'),
      FLAG('chen_sang')]]),
  IF('chen_sang',[N('前奏响起。小陈握着话筒，第一句，稳稳地落在了拍子上。','The intro plays. Xiao Chen grips the mic, and his first line lands right on the beat.'),
                  N('副歌的高音，他没有破。全场安静了一秒，然后炸开了。','He hits the high note in the chorus without cracking. The room is silent for a beat, then erupts.'),
                  N('经理张着嘴，手里的啤酒杯忘了放下。','The manager stands open-mouthed, a beer glass forgotten in his hand.')],
     [N('他唱得很认真。只是第一句，晚了半拍。','He sings with everything he has. Only the first line comes in half a beat late.')])]},

 {who:'ace',steps:[
  CARD('— 21:00 · 复赛 —','— 9:00 PM · Second Round —'),
  N('一个银白色头发向上梳起、耳朵上挂着银色耳骨夹的男生，带着一个扛摄像机的跟拍小哥走了过来。','A guy with silver-white hair swept upward and silver ear cuffs strolls over, trailed by a cameraman.'),
  N('他在吧台前站定，侧了一下脸——刚好是灯光最好的角度。','He stops at the counter and turns his face slightly. Exactly the best angle for the light.'),
  S('ace','嗨。我是 Ace。今晚的冠军。','Hi. I\'m Ace. Tonight\'s winner.'),
  S('ace','（对摄像机）这一段剪掉。OK，再来一遍。','(To the camera) Cut that. OK, again.'),
  S('ace','嗨～我是 Ace！今晚，请多指教！（笑容灿烂）','Hiii~ I\'m Ace! Please look after me tonight! (A dazzling smile)'),
  EMO('✨'),
  C(['（配合地笑）欢迎，Ace。','(Play along with a smile) Welcome, Ace.',1,[
      S('ace','你很上镜嘛。……这段留着。','You\'re camera-friendly. …Keep this take.')]],
    ['两个版本，哪个是真的你？','Two versions. Which one\'s the real you?',2,[
      S('ace','（笑容停了一秒）……你问这个干嘛。','(The smile stalls for a second.) …Why would you ask that.'),
      S('ace','（他挥手让摄像小哥先去别处拍）','(He waves the cameraman off to film something else.)'),
      FLAG('ace_real')]],
    ['能不能别对着吧台拍？','Could you not film behind the bar?',-1,[
      S('ace','放心，你又不是主角。','Relax. You\'re not the main character.'),
      EMO('💢')]]),
  S('panda','（举着自拍杆从旁边挤过来）家人们！这就是那个练习生 Ace！他直播间人数还没我多！','(Squeezing in with his selfie stick) Fam! It\'s Ace, the trainee! His stream has fewer viewers than mine!'),
  S('ace','……熊猫耳朵，你挡到我的光了。','…Panda ears, you\'re in my light.'),
  S('panda','略略略。','Nyeh nyeh nyeh.'),
  N('Panda 被摄像小哥「请」走了。Ace 叹了口气，第一次在吧台凳上坐了下来。','The cameraman "escorts" Panda away. Ace sighs and, for the first time, actually sits on a stool.'),
  S('ace','公司说，今晚要是拿不到冠军，我的出道企划就取消了。','My agency says if I don\'t win tonight, my debut plan gets cancelled.'),
  S('ace','所以镜头必须一直开着。镜头开着的时候，我就不会……（他停住了）','So the camera has to stay on. As long as it\'s on, I don\'t… (He stops.)'),
  C(['……就不会紧张？','…Get nervous?',2,[
      S('ace','（他看着你，很久）……镜头关掉的话，我连话筒都握不住。','(He looks at you for a long time.) …With the camera off, I can\'t even hold a mic.'),
      S('ace','很可笑吧。一个怕舞台的练习生。','Ridiculous, right? A trainee who\'s scared of the stage.'),
      FLAG('ace_fear')],'ace_real'],
    ['冠军不是只有一个吗？天哥卫冕三届了。','There\'s only one champion. Brother Tian\'s won three years running.',0,[
      S('ace','我知道。所以我才必须比他更好看。','I know. That\'s why I have to look better than him.')]],
    ['那就让镜头一直开着。','Then keep the camera rolling.',1,[
      S('ace','……嗯。对。一直开着就好。','…Yeah. Right. Just keep it on.')]]),
  S('ace','给我一杯上镜的。【粉红色】的，装在【马天尼杯】里，杯子要【又高又细】那种好看。','Make me something photogenic. 【Pink】, in 【a martini glass】, 【tall and elegant】.'),
  S('ace','味道要【酸酸甜甜】，像【蔓越莓】。别太甜，我在控糖。……【有点酒】就行，我要壮胆。','【Sweet and sour】, like 【cranberry】. Not too sweet, I\'m watching sugar. …【A little alcohol】 is fine. I need the courage.'),
  N('（粉色、马天尼杯、蔓越莓、酸甜……那部老美剧里，四个女主角最爱的那一杯。——当然，粉色的酒不止一种。）','(Pink, martini glass, cranberry, sweet-sour… the drink four women made famous in that old TV show. Of course, it\'s not the only pink drink in the world.)'),
  MX({accept:['lychee_martini','aperol_spritz','clover_club','kir_royale','watermelon_marg','rose_lychee'],best:'cosmopolitan',want:['酸','果味','好看','优雅'],avoid:['苦','奶香'],str:'low'},
   [S('ace','（对着灯光转了一下杯子）……完美的粉色。','(Turns the glass in the light) …The perfect pink.'),
    S('ace','连颜色都这么上镜。','Even the colour is photogenic.'),
    IF('ace_fear',[S('ace','（他小声说）……镜头关着。我好像，也能喝完这一杯了。','(Quietly) …The camera\'s off. And I think I can still finish this drink.'),EMO('✨')],
       [S('ace','（对摄像小哥）这个镜头，给个特写。','(To the cameraman) Get a close-up of this.')])],
   [S('ace','颜色差一点……不过味道可以。','The colour\'s a little off… but it tastes fine.'),
    S('ace','（对摄像小哥）滤镜调粉一点，后期补。','(To the cameraman) Pink it up in post.')],
   [S('ace','……这个颜色，上不了镜。','…This colour can\'t go on camera.'),
    EMO('💢'),
    S('ace','算了。冠军不靠一杯酒。','Forget it. Winners don\'t need a drink.')],
   [S('ace','（喝了一口，脸上的营业笑容一下子掉了）……花。','(One sip and his professional smile drops) …Flowers.'),
    S('ace','我家楼下是我妈的花店。小时候我每天放学就坐在玫瑰桶旁边写作业，满身都是这个味道。同学叫我"花店小子"。','My mom runs a flower shop under our flat. As a kid I did homework next to the rose buckets every day and came out smelling like this. Classmates called me "flower boy."'),
    S('ace','公司说这个人设"不够酷"，让我别提。……我已经两年没回家了。','The agency said that image "isn\'t cool enough" and told me never to mention it. …I haven\'t been home in two years.'),
    N('他把杯子转向摄像机。「……这段，不用剪。」','He turns the glass toward the camera. "…Don\'t cut this one."'),
    FLAG('ace_real'),FLAG('ace_flower'),TIP(20)]),
  N('Ace 上台了。摄像小哥举着机器，站在台下正中间。','Ace goes on stage. The cameraman plants himself front and centre.'),
  N('前奏走到一半——摄像机的红灯，灭了。没电了。','Halfway through the intro, the camera\'s red light goes out. Dead battery.'),
  N('Ace 握着话筒的手，肉眼可见地抖了起来。','The hand holding Ace\'s mic visibly starts to shake.'),
  FX('shake'),
  CT(8,[N('（没人动。前奏又空转了一个小节。）','(Nobody moves. The intro loops another empty bar.)'),
        N('Ace 最后还是开口了。声音很小，但每一个字都唱完了。','Ace sings in the end. Quietly, but he finishes every word.')],
    ['（举起手机，打开闪光灯，对准他）','(Raise your phone, flashlight on, and point it at him)',2,[
      N('一束白光照在台上。Ace 眯了一下眼睛，然后——看着那束光，开口了。','A beam of white light hits the stage. Ace squints, then, looking straight into it, starts to sing.'),
      N('台下，一个、两个、十个……所有人都举起了手机的闪光灯。','In the crowd, one, two, ten… everyone raises a phone light.'),
      FLAG('ace_light')]],
    ['（冲 Panda 喊）「Panda！你的直播借他用！」','(Shout to Panda) "Panda! Lend him your stream!"',2,[
      S('panda','……啧！家人们，今天破例给对手打光！','…Tch! Fam, just this once, we\'re lighting up a rival!'),
      N('Panda 的自拍杆高高举起。手机屏幕的光，照着 Ace 的脸。','Panda\'s selfie stick goes up high. The phone screen\'s glow lights Ace\'s face.'),
      FLAG('ace_light')]],
    ['（什么都不做，相信他）','(Do nothing. Trust him)',0,[
      N('Ace 闭上眼睛，深吸了一口气。','Ace closes his eyes and takes a deep breath.')]]),
  IF(['ace_fear','ace_light'],[
    CARD('— 21:20 · 后台 —','— 9:20 PM · Backstage —'),
    N('唱完下台，Ace 没有回化妆间。他走到吧台，当着摄像小哥的面，把耳骨夹一个一个摘了下来。','Off stage, Ace doesn\'t go back to the dressing room. He walks to the bar and, in front of the cameraman, takes out his ear cuffs one by one.'),
    S('ace','刚才那首，是我这两年唱得最好的一次。可那不是因为镜头。是因为台下那些光。','That song was the best I\'ve sung in two years. Not because of a camera. Because of those lights out there.'),
    IF('ace_flower',[S('ace','我想回家一趟。去花店。给我妈唱一首——不开镜头。','I want to go home. To the flower shop. Sing my mom a song. No camera.')]),
    S('ace','（他冲你伸出手）冠军不冠军的……以后，我想站在没有镜头的地方唱歌。比如，这儿。','(He holds out a hand) Champion or not… from now on I want to sing somewhere without cameras. Like here.'),
    END('off_camera','镜头之外','Off Camera')])]},

 {who:'tiange',steps:[
  CARD('— 22:20 · 决赛前 —','— 10:20 PM · Before the Final —'),
  N('一个中分卷发、戴着细金链子的男人慢悠悠地走到吧台，黑色真丝衬衫开着两颗扣子。全场好几个人冲他喊：「天哥！」','A man with centre-parted curls and a thin gold chain strolls to the bar, black silk shirt open two buttons. Half the room calls out: "Brother Tian!"'),
  S('tiange','兄弟，来一杯。','Pour me one, brother.'),
  S('tiange','卫冕三届，今晚第四届。……兄弟，你说我是不是该见好就收？','Three titles running, going for four tonight. …Brother, you think I should quit while I\'m ahead?'),
  N('他说话的声音，比他在台上唱歌时，哑了不止一点。','His speaking voice is a lot huskier than his singing voice on stage.'),
  EMO('…'),
  C(['您嗓子……还好吗？','Is your voice… okay?',2,[
      S('tiange','（他笑了一下，没回答。过了一会儿）……声带小结。医生说，再唱下去，以后就只能说话了。','(He smiles and doesn\'t answer. Then:) …Vocal nodules. The doctor says if I keep singing, someday all I\'ll be able to do is talk.'),
      S('tiange','所以今晚，是最后一次。','So tonight\'s the last time.'),
      FLAG('tian_secret')]],
    ['您这么厉害，当然要拿四连冠。','You\'re the best. Of course you go for four.',0,[
      S('tiange','哈哈，兄弟会说话。','Haha, you know what to say, brother.')]],
    ['见好就收，也是一种赢。','Quitting while you\'re ahead is a kind of winning.',1,[
      S('tiange','……（他看了你一眼）你这话，跟我妈说得一模一样。','…(He looks at you.) That\'s exactly what my mom says.')]]),
  S('tiange','兄弟，你知道我第一次拿冠军，是在哪儿吗？','Brother, know where I won my first title?'),
  S('tiange','老街，一家叫「九号」的小酒馆。周五晚上的卡拉 OK 比赛，奖品是一杯冬瓜威士忌。','On the old street. A little bar called Number Nine. Friday night karaoke, and the prize was a winter melon whiskey.'),
  EMO('❗'),
  C(['您也是「九号」的老客人？','You were a Number Nine regular too?',1,[
      S('tiange','那时候我才十九。酒哥说我嗓子好，非要我上台。','I was nineteen. Brother Jiu said I had a voice and made me get up there.'),
      S('tiange','评委就一个——一个总穿西装、话很少的大叔。','There was only one judge: a guy in a suit who barely said a word.')]],
    ['原来您的歌，是从那儿开始的。','So that\'s where your singing began.',1,[
      S('tiange','是啊。从一杯冬瓜威士忌开始，到一个镀金话筒结束。挺圆满。','Yeah. Started with a winter melon whiskey, ends with a gold-plated mic. Neat, huh.')]],
    ['那位评委……是理查德先生吧？','That judge… was Mr. Richard, wasn\'t it?',2,[
      S('tiange','（他眯起眼睛）……兄弟，你知道的挺多啊。','(He narrows his eyes.) …Brother, you know a lot.'),
      S('tiange','对。他当年说：「这孩子能唱很多年。」……他说错了。','Yeah. Back then he said, "This kid will sing for years." …He was wrong.'),
      FLAG('tian_richard')],'met_r'],
    ['所以您今晚，是想在他面前唱最后一次。','So tonight you want to sing the last one in front of them.',2,[
      S('tiange','……兄弟，你看人太准了。','…Brother, you read people too well.'),
      FLAG('tian_richard')],'tian_secret']),
  S('tiange','给我来一杯。【要烈】，【要经典】，【用威士忌】。','Pour me one. 【Strong】, 【classic】, 【whiskey】.'),
  S('tiange','【不要冰块】，【搅拌】，装在【高脚杯】里。最后放一颗【樱桃】——红的，像舞台的灯。','【No ice】, 【stirred】, in 【a stemmed glass】. Finish it with 【a cherry】, red, like stage lights.'),
  C(['味道要偏甜还是偏苦？','Sweeter or more bitter?',1,[
      S('tiange','【带一点红色的甜】，就是那种【加了药草的红酒味】……还有几滴苦，留给自己。','【A red kind of sweetness】, that 【herby red-wine taste】… and a few drops of bitter, for myself.')]],
    ['喝烈的，对嗓子不好吧？','Isn\'t strong liquor bad for your voice?',2,[
      S('tiange','（他摆摆手）最后一晚了，兄弟。让我当一回不听话的病人。','(Waves it off) It\'s the last night, brother. Let me be a bad patient, just once.')]],
    ['「最后一首，您想用破了的嗓子唱，还是用您自己的嗓子唱？」','"Your last song. Do you want to sing it with a wrecked voice, or with your own?"',2,[
      N('天哥沉默了很久。他摸了摸脖子上的金链子。','Brother Tian is silent for a long time. He touches the gold chain at his throat.'),
      S('tiange','……兄弟，你狠。','…Brother, that\'s brutal.'),
      S('tiange','行。今晚不喝烈的。给我来点【护嗓子】的——【温和】一点，带点【蜂蜜】、带点【姜】……还是要有一点点酒，不然我上不去台。','Fine. Nothing strong tonight. Give me something 【for the throat】: 【mellow】, some 【honey】, some 【ginger】… and just a little alcohol, or I won\'t make it up there.'),
      FLAG('tian_soft')],'tian_secret'],
    ['要不要换成温水？','How about warm water instead?',-1,[
      S('tiange','兄弟。今晚，别劝我。','Brother. Not tonight.')]]),
  IF('tian_soft',[
    N('（蜂蜜、姜、温和……一杯护嗓子的酒。）','(Honey, ginger, gentle… a drink that looks after the voice.)'),
    MX({accept:['brown_sugar_milk','apple_highball','osmanthus_oolong','jp_highball'],best:'penicillin',want:['酸','烈'],avoid:['气泡','奶香'],str:'mid'},
     [S('tiange','（喝了一口，清了清嗓子）……嗯。暖的。','(Sips and clears his throat) …Mm. Warm.'),
      S('tiange','兄弟，我刚才试了一下高音——还在。今晚，够用了。','Brother, I just tried the high note. It\'s still there. Enough for tonight.'),
      S('tiange','（他把樱桃梗放在吧台上）走了。去唱最后一首。用我自己的嗓子。','(Sets a cherry stem on the counter) I\'m off. Last song. In my own voice.'),
      FLAG('tian_voice')],
     [S('tiange','还行，嗓子松了点。','Not bad. Throat\'s a bit looser.'),
      S('tiange','行，兄弟，就它了。','Alright, brother. This\'ll do.')],
     [S('tiange','……（咳了两声）兄弟，这个有点呛。','…(Coughs twice) Brother, that one scratches.'),
      EMO('…')],
     [S('tiange','（喝了一口，愣住了）……茶？还有一点……咸？','(One sip and he stops) …Tea? And a little… salt?'),
      S('tiange','我妈每次在我上台前，都给我泡一杯淡盐茶，说护嗓子。十九岁第一次在「九号」比赛那晚，她就坐在台下，手里捧着保温杯。','Before every show my mom brews me weak salted tea for my voice. The night I first competed at Number Nine, at nineteen, she sat in the front row holding the thermos.'),
      S('tiange','……她今晚也在台下。（他朝人群里一个白发阿姨挥了挥手）','…She\'s in the crowd tonight too. (He waves to a white-haired woman in the crowd.)'),
      S('tiange','兄弟，谢了。最后一首，我唱给她。','Thanks, brother. The last song is for her.'),
      FLAG('tian_voice'),TIP(30)])],
   [N('（威士忌、甜味美思、苦精、搅拌、樱桃……「鸡尾酒之王」，配今晚的歌王。）','(Whiskey, sweet vermouth, bitters, stirred, a cherry… the "king of cocktails", for tonight\'s king of karaoke.)'),
    MX({accept:['old_fashioned','whiskey_sour','sazerac','penicillin'],best:'manhattan',want:['烈','优雅'],avoid:['气泡','果味','奶香'],str:'high'},
     [S('tiange','（举起杯子，对着舞台的灯）……「鸡尾酒之王」的路子。','(Holds the glass up to the stage lights) …The "king of cocktails" style.'),
      S('tiange','兄弟，你这是在跟我说——今晚，我还是王。','Brother, you\'re telling me that tonight, I\'m still king.'),
      S('tiange','（一口喝干，把樱桃梗放在吧台上）走了。去唱最后一首。','(Downs it, sets the cherry stem on the counter) I\'m off. Last song.'),
      EMO('✨')],
     [S('tiange','够烈。不是我想的那杯，但够烈。','Strong enough. Not the one I pictured, but strong enough.'),
      S('tiange','行，兄弟，就它了。','Alright, brother. This\'ll do.')],
     [S('tiange','……（他只喝了一口）','…(He takes just one sip.)'),
      S('tiange','兄弟，最后一晚，我想喝点像样的。','Brother, on my last night, I wanted something proper.'),
      EMO('…')],
     [S('tiange','（喝了一口，愣住了）……这里面，有茶？还有一点咸？','(One sip and he stops) …Is there tea in this? And a little salt?'),
      S('tiange','我妈每次在我上台前，都给我泡一杯淡盐茶。十九岁那年在「九号」，她就坐在台下，捧着保温杯。','Before every show my mom brews me weak salted tea. At Number Nine when I was nineteen, she sat right up front holding the thermos.'),
      S('tiange','……她今晚也在。（他朝人群里一个白发阿姨挥了挥手）最后一首，我唱给她。','…She\'s here tonight too. (He waves to a white-haired woman in the crowd.) The last song is for her.'),
      TIP(30)])]),
  CARD('— 23:40 · 决赛 —','— 11:40 PM · The Final —'),
  N('决赛名单亮在大屏上：天哥、Ace、「陈小」。','The finalists light up the big screen: Brother Tian, Ace, and "Chen Xiao".'),
  IF('chen_sang',[N('经理盯着屏幕上「陈小」两个字，又看看台上的小陈，挠了挠头，最后……鼓起了掌。','The manager stares at "Chen Xiao" on the screen, then at Xiao Chen on stage, scratches his head, and finally… starts clapping.')]),
  IF('ace_light',[N('Ace 没让摄像小哥换电池。他说：「今晚，用你们的光就够了。」','Ace didn\'t let the cameraman swap the battery. He said, "Tonight, your lights are enough."')]),
  N('天哥最后一个上场。他唱的是一首老歌——你听酒哥在包厢里唱过很多遍的那首。','Brother Tian goes last. He sings an old song, the one you\'ve heard Brother Jiu sing in the rooms so many times.'),
  IF('tian_voice',[N('副歌的高音，他稳稳地送了上去。干净，完整，像十九岁。','He sends the chorus\'s high note up clean and whole, like he\'s nineteen again.')],
    [N('副歌的时候，他的声音裂开了一道缝。可他没停。','At the chorus, his voice cracks. He doesn\'t stop.')]),
  N('酒哥在台下，跟着唱了起来。然后是莫姐、Panda、经理……最后，整个大厅都在唱。','Down in the crowd, Brother Jiu starts singing along. Then Sister Mo, Panda, the manager… and finally the whole lounge.'),
  IF('tian_secret',[N('（你知道，这是他最后一次站在台上。台下的大多数人，不知道。）','(You know this is the last time he\'ll stand on a stage. Most of the crowd doesn\'t.)')]),
  N('理查德站了起来，走向吧台尽头的奖杯。所有人都安静了。','Richard rises and walks toward the trophy at the end of your counter. The room falls silent.'),
  S('richard','今晚的歌王是——','Tonight\'s Karaoke King is—'),
  FX('flash'),
  FX('dark'),
  N('啪。','Click.'),
  N('灯，全灭了。','Every light goes out.'),
  N('音乐断了。大电视黑了。连吧台前那一圈粉色霓虹，也灭了。','The music cuts. The big TV goes black. Even the pink neon rings along the counter die.'),
  N('黑暗里有人尖叫，有人撞翻了椅子，有杯子摔碎在地上。','Someone screams in the dark. A chair crashes over. A glass shatters.'),
  CT(8,[N('（你僵在原地。黑暗里，有一只冰凉的手，从你面前的吧台上，轻轻拿走了什么。）','(You freeze. In the dark, a cold hand lifts something off the counter right in front of you.)')],
    ['（摸到手机，打开手电筒）','(Fumble for your phone and turn on the flashlight)',1,[
      N('手电筒的光一扫——你只来得及看见一截深灰色西装的袖口，被另一只手死死攥着。','Your beam sweeps the room. All you catch is the cuff of a charcoal suit sleeve, gripped hard by another hand.'),
      N('那只手的手腕上，系着一根褪了色的【红绳】。两个人影一起，消失在走廊尽头。','Around that wrist is a faded 【red string】. Both figures vanish together down the corridor.'),
      N('（走廊尽头……是员工通道，再往外，是【后门】。）','(The end of that corridor… is the staff passage. And beyond that, 【the back door】.)'),
      FLAG('saw_cuff')]],
    ['（护住吧台上的酒瓶）','(Shield the bottles on the counter)',1,[
      N('你张开双臂护住酒瓶。黑暗里，有人贴着吧台，在你耳边很轻地说了一句：','You throw your arms over the bottles. In the dark, someone leans against the counter and whispers right by your ear:'),
      N('「第三格抽屉。替我看好它。」','"Third drawer. Keep it safe for me."'),
      N('声音很哑。那人身上，有一股淡淡的【冬瓜茶味】。','The voice is hoarse. Whoever it is smells faintly of 【winter melon tea】.'),
      FLAG('heard_whisper')]],
    ['「大家别动！原地别动！」','"Everyone stay where you are! Don\'t move!"',2,[
      N('你的声音在黑暗里炸开。尖叫声停了。所有人都安静下来。','Your voice cuts through the dark. The screaming stops. Everyone goes still.'),
      N('安静里，你听见了——吧台尽头，有什么金属的东西被轻轻拿起来。里面还「叮当」响了一声，像是装着一把小小的【钥匙】。','And in the silence you hear it: at the end of the counter, something metal being gently lifted. Something inside it gives a tiny "clink", like a small 【key】.'),
      N('然后是理查德压得很低的声音：「……老九，你放手。」','Then Richard\'s voice, very low: "…Lao Jiu. Let go."'),
      FLAG('heard_trophy')]]),
  CARD('— 23:52 —','— 11:52 PM —'),
  N('应急灯亮了。惨白的光，照着一屋子人僵硬的脸。','The emergency lights flicker on. Their pale glare falls on a roomful of frozen faces.'),
  N('吧台尽头，那个镀金的话筒奖杯，不见了。','At the end of your counter, the gold microphone trophy is gone.'),
  N('评委席上，那把黑伞还靠在椅子边。','At the judges\' table, the black umbrella still leans against the chair.'),
  N('理查德，也不见了。','And Richard is gone too.'),
  N('（你在人群里找了一圈。好像还少了谁——可应急灯太暗，你数不清。）','(You scan the crowd. It feels like someone else is missing too, but the emergency lights are too dim to count.)'),
  S('kevin','（举着笔记本电脑，脸被屏幕照得发白）……整栋楼的电闸，是被人从系统里手动关掉的。','(Holding up his laptop, face white in the screen\'s glow) …The building\'s power was switched off manually, through the system.'),
  S('kevin','登录账号，还是「R」。','The login account… was "R" again.'),
  EMO('❗'),
  N('（凶手，往往是最不像凶手的那个。）','(The killer is always the one who looks least like one.)'),
  N('（——今晚，还没结束。）','(Tonight isn\'t over yet.)')]}
 ]},
// ===================== NIGHT 6 =====================
{title:['停电之后','After the Blackout'],
 preview:['下回——最后一杯。经理认定了"内鬼"，莫姐的期限是午夜十二点。眼线、画家、刚拿到执照的律师，各自带来一块拼图。所有人都在等你开口：那天晚上，到底发生了什么？','Next time: Last Call. The manager has picked his "inside man," and Sister Mo\'s deadline is midnight. A lookout, a painter and a freshly licensed lawyer each bring a piece of the puzzle. Everyone is waiting for you to say it: what really happened that night?'],
 intro:[CARD('— 第六夜 · 23:53 · 停电后一分钟 —','— Night Six · 11:53 PM · One minute after the blackout —'),
        FX('dark'),
        N('应急灯嗡嗡作响。白光从天花板四个角落斜斜地打下来，每个人的影子都被拉得很长。','The emergency lights buzz. Pale light slants from the four corners of the ceiling, stretching everyone\'s shadow long.'),
        N('有人在哭，有人在打电话，有人已经往门口挤。舞台上的话筒倒在地上，发出一阵刺耳的啸叫。','Someone is crying, someone is on the phone, someone is already pushing for the door. On stage the fallen mic lets out a piercing squeal.'),
        N('经理老周站在吧台尽头，盯着奖杯原来的位置，脸白得跟应急灯一个颜色。','The manager, Old Zhou, stands at the end of the counter staring at the spot where the trophy was, his face as white as the emergency lights.'),
        IF('saw_cuff',[N('（深灰西装的袖口。一根褪色的红绳。【后门】。……你闭上眼，把那一秒钟又过了一遍。）','(A charcoal suit cuff. A faded red string. The back door. …You close your eyes and replay that one second.)')]),
        IF('heard_whisper',[N('（「第三格抽屉。替我看好它。」……那股冬瓜茶的味道，还在鼻子里。）','("Third drawer. Keep it safe for me." …That smell of winter melon tea is still in your nose.)')]),
        IF('heard_trophy',[N('（「叮当」一声。还有那句：「老九，你放手。」）','(That little "clink". And: "Lao Jiu. Let go.")')]),
        N('人群开始往门口涌。再过一分钟，所有见过那十秒黑暗的人，就都散了。','The crowd surges toward the door. In another minute, everyone who saw those ten seconds of darkness will be gone.'),
        CT(7,[N('（你还没开口，门已经被推开了。冷风灌进来，一半的人散进了夜色里。）','(Before you can speak, the door swings open. Cold air pours in, and half the crowd scatters into the night.)'),FLAG('crowd_left')],
          ['（跳上吧台）「各位！今晚所有人的酒，我请！——但请先别走！」','(Jump onto the counter) "Everyone! Drinks are on me tonight! But please don\'t leave yet!"',0,[
            N('人群愣了一秒，然后爆发出一阵哄笑和欢呼。没人走了。','The crowd freezes for a second, then bursts into laughter and cheers. Nobody leaves.'),
            N('（……这笔账，明天再算。）','(…You\'ll worry about the bill tomorrow.)'),
            TIP(-30),FLAG('crowd_stayed')]],
          ['「门口那位，麻烦把门关上。——在场每个人，都是证人。」','"You by the door, please shut it. Everyone here is a witness."',0,[
            N('你的声音不大，却让整个大厅安静了下来。门，「咔哒」一声关上了。','Your voice isn\'t loud, but the whole room goes quiet. The door clicks shut.'),
            FLAG('crowd_stayed'),FLAG('doors_shut')]],
          ['（不管人群，先去看吧台第三格抽屉）','(Ignore the crowd. Check the third drawer under the counter first)',0,[
            N('你蹲下去，拉开第三格抽屉——里面是一本用牛皮纸包着的旧本子。你还没来得及打开，身后的人群已经散了一半。','You crouch and pull open the third drawer: an old notebook wrapped in kraft paper. Before you can open it, half the crowd behind you has gone.'),
            FLAG('crowd_left'),FLAG('drawer_early')],'heard_whisper'])],
 scenes:[
 {who:'mojie',steps:[
  N('莫姐摘下耳麦，攥在手里。她的指甲，在耳麦的塑料壳上掐出了一道白印。','Sister Mo pulls off her headset and grips it. Her nails press a white line into the plastic.'),
  S('mojie','……十秒。说好的，只有十秒。','…Ten seconds. It was supposed to be ten seconds.'),
  EMO('…'),
  S('mojie','（她看见你在看她，立刻挺直了背）没什么。设备故障。我会处理。','(She sees you watching and straightens up at once.) It\'s nothing. Equipment failure. I\'ll handle it.'),
  C(['「十秒？——灯是你们安排暗下去的。」','"Ten seconds? So the lights going out was planned."',2,[
      S('mojie','（她盯着你看了很久，最后叹了口气）……流程单你也看过了。瞒你没意义。','(She stares at you a long time, then sighs.) …You\'ve seen the run sheet. No point hiding it.'),
      FLAG('mo_admit')],'clue:特别环节'],
    ['「莫姐，先坐下。你的手在抖。」','"Sister Mo, sit down first. Your hands are shaking."',2,[
      N('她低头看了看自己的手，像是第一次发现它们在抖。然后，坐了下来。','She looks down at her hands as if noticing for the first time, then sits.'),
      S('mojie','……谢谢。今晚还没人让我坐下过。','…Thank you. No one\'s told me to sit all night.')]],
    ['「奖杯丢了，主办方是不是要负责？」','"The trophy\'s gone. Isn\'t the organiser liable?"',-1,[
      S('mojie','（她冷冷地看了你一眼）你是在关心我，还是在关心责任在谁？','(She gives you a cold look.) Are you worried about me, or about who\'s to blame?')]]),
  S('mojie','赞助商已经打了三个电话。理查德先生联系不上。……奖杯是赞助商出的钱，镀金的，值不了几个钱——可那是他们的面子。','The sponsors have called three times. Mr. Richard can\'t be reached. …The sponsors paid for that trophy. Gold-plated, not worth much. But it\'s their face.'),
  S('mojie','我给自己一天。明晚十二点之前，奖杯和人都不回来，我就报警，然后跟赞助商解释。','I\'m giving myself one day. If the trophy and the man aren\'t back by midnight tomorrow, I call the police and face the sponsors.'),
  S('mojie','先给我一杯。我得把脑子理清楚。','Pour me something first. I need to clear my head.'),
  S('mojie','【苦一点】，【别甜】。……今晚我不要盔甲了，我要能让我【冷静】下来的东西。','【A little bitter】. 【Not sweet】. …Tonight I don\'t need armour. I need something that 【calms me down】.'),
  MX({accept:['negroni','dry_martini','sake_tini','jasmine_gin','mezcal_negroni','penicillin'],best:'negroni',want:['苦','草本'],avoid:['甜','奶香','气泡'],str:'mid'},
   [S('mojie','（喝了一口，闭上眼睛，呼吸慢慢平了）……好。我能想事情了。','(Sips, closes her eyes, her breathing slowing) …Good. I can think now.'),
    FLAG('mo_calm')],
   [S('mojie','……还行。至少是热的心意。','…It\'ll do. At least the thought is warm.')],
   [S('mojie','（喝了一口就放下了）……算了。今晚什么都不对。','(One sip and she puts it down) …Forget it. Nothing\'s right tonight.'),
    EMO('💢')],
   [S('mojie','（喝了一口，停了很久）……你又找到了。苦后面的那一层。','(Sips and pauses a long time) …You found it again. That layer behind the bitter.'),
    S('mojie','我跟你说实话吧。你配得上实话。','I\'ll tell you the truth. You\'ve earned it.'),
    FLAG('mo_calm'),FLAG('mo_admit')]),
  IF('mo_admit',[
    S('mojie','23 点 50 分，【特别环节】。灯全暗十秒，然后追光。灯是理查德先生自己用手机关的——他坚持要亲手按。','11:50 PM, the 【Special Segment】. Ten seconds of total darkness, then a spotlight. Mr. Richard switched the lights off himself, from his phone. He insisted on pressing it himself.'),
    S('mojie','追光要打在谁身上，他没告诉我。他只说：「今晚，我要还一样东西。」','He never told me who the spotlight was for. He only said, "Tonight, I\'m returning something."'),
    IF(['mo_trust','clue:空心'],[
      S('mojie','……还有一件事。奖杯底座，是空心的。比赛前，我亲眼看着他往里面放了一把【钥匙】。旧的，铜的，挂着一个写着「9」的木牌。','…One more thing. The trophy\'s base is hollow. Before the contest I watched him put a 【key】 inside it. Old, brass, on a wooden tag marked "9".'),
      FLAG('mo_key')])],
    [S('mojie','……今晚的流程，有些细节我答应过别人不说。别逼我。','…There are details about tonight I promised not to share. Don\'t push me.')]),
  N('（安排好的十秒黑暗。可灯为什么没有回来？）','(Ten seconds of planned darkness. So why didn\'t the lights come back?)')]},

 {who:'kevin',steps:[
  CARD('— 00:20 —','— 12:20 AM —'),
  N('Kevin 盘腿坐在配电箱旁边的地上，笔记本电脑放在膝盖上。Panda 蹲在他旁边，熊猫耳朵发箍歪到了一边，手机一遍一遍地拨着同一个号码。','Kevin sits cross-legged on the floor by the breaker box, laptop on his knees. Panda crouches beside him, his panda ears askew, redialling the same number over and over.'),
  WHO('panda'),
  S('panda','舅舅不接……他从来不会不接我电话的……','Uncle\'s not picking up… he never ignores my calls…'),
  EMO('💦'),
  WHO('kevin'),
  IF('kevin_log',[
    S('kevin','我查到了。上次我装的【操作日志】全记下来了。','I\'ve got it. The 【activity log】 I installed last time recorded everything.'),
    S('kevin','23:50:02，R 账号关闭全楼电源，登录设备——「R 的手机」。同一时间，系统里还有一个定时脚本：十秒后自动恢复供电。','11:50:02 PM, the R account cut power to the whole building. Device: "R\'s phone". At the same moment there was a scheduled script: restore power after ten seconds.'),
    S('kevin','可是……（他的声音越来越小）那个脚本，被我上次加的安全规则拦下来了。我把它当成了"未授权的自动操作"。','But… (his voice gets smaller and smaller) that script got blocked by the security rule I added last time. It flagged it as an "unauthorised automated action."'),
    S('kevin','灯没回来……是我的锅。','The lights didn\'t come back… that\'s on me.'),
    FLAG('kevin_guilt'),
    C(['「你装那个日志，是为了保护这家店。这不是你的错。」','"You installed that log to protect this place. This isn\'t your fault."',2,[
        S('kevin','……（他推了推眼镜，推了好几下）谢谢。','…(He pushes up his glasses, several times.) Thanks.')]],
      ['「确实是你的锅。」','"Yeah, that\'s on you."',-2,[
        S('kevin','……我知道。','…I know.'),
        N('他把脸埋进了膝盖里。','He buries his face in his knees.')]],
      ['「所以灯是理查德自己关的。那他的手机现在在哪？」','"So Richard cut the lights himself. Where\'s his phone now?"',1,[
        S('kevin','（他一下子抬起头）……对啊。手机还在登录状态。它离这儿不远。','(His head snaps up) …Right. The phone\'s still logged in. It\'s not far from here.')]])],
   [S('kevin','没有日志，我只能看到 R 账号在 23:50 关了电。从哪台设备、为什么灯没回来……我都看不到。','Without a log, all I can see is the R account cut power at 11:50. Which device, why the lights didn\'t come back… I can\'t see any of it.'),
    S('kevin','（他狠狠抓了抓头发）上次要是装了日志就好了。','(He rakes his hair hard) If only I\'d installed a log last time.')]),
  WHO('panda'),
  S('panda','我再打一次……','I\'ll try once more…'),
  N('Panda 按下了拨号键。','Panda hits dial.'),
  CT(6,[N('大厅里太吵了。电话那头，依旧没人接。','The lounge is too loud. Still no answer.'),
        N('（后来，是经理在评委席收拾的时候，在伞里摸到了一部手机，顺手锁进了办公室。你没看清是谁的。）','(Later, while clearing the judges\' table, the manager finds a phone in an umbrella and locks it in his office without a word. You never see whose it was.)')],
    ['「所有人，安静！——听！」','"Everyone, quiet! Listen!"',2,[
      N('大厅一下子安静了。','The lounge falls silent.'),
      N('嗡——嗡——','Bzzz. Bzzz.'),
      N('震动声，来自评委席。来自那把收着的黑伞里。','The buzzing is coming from the judges\' table. From inside the furled black umbrella.'),
      N('你拨开伞面——一部手机卡在伞骨中间，屏幕亮着：「外甥 来电」。','You open the canopy: a phone is wedged between the ribs, screen glowing: "Nephew calling."'),
      N('（【雨伞里的手机】。他关灯之后，把手机丢进了伞里？还是……在黑暗里，被人拽走的时候掉进去的？）','(【A phone in the umbrella】. Did he drop it in after cutting the lights? Or did it fall in when someone dragged him off in the dark?)'),
      FLAG('found_phone')]],
    ['（顺着 Panda 的手机屏幕看过去，是谁的号码）','(Glance at Panda\'s screen to see whose number it is)',0,[
      N('「舅舅」。头像是一张老照片：一家小酒馆的门头，招牌上写着「九号」。','"Uncle." The contact photo is an old picture: a little bar\'s shopfront, the sign reading "Number Nine."'),
      N('（……可电话那头，依旧没人接。）','(…Still no one answers.)')]]),
  IF('found_phone',[
    WHO('panda'),
    S('panda','舅舅……把手机都丢了？他不会出什么事吧……','Uncle… left his phone behind? What if something\'s happened to him…'),
    C(['（输入 0909 解锁）','(Unlock it with 0909)',1,[
        N('屏幕解锁了。最后一个打开的页面，是备忘录。标题叫「致辞稿」。','The screen unlocks. The last open app is Notes. The title: "Speech draft".'),
        N('「老九：六年前，你那栋楼的【业主】，是我的公司。房租是我签字涨的。我在国外，连合同都没细看……」','"Lao Jiu: six years ago, the 【landlord】 of your building was my company. I signed the rent increase. I was abroad. I didn\'t even read the contract properly…"'),
        N('下面的字被删了又写，写了又删。最后一行是：「今晚，我把「九号」还给你。」','The rest has been written, deleted and rewritten. The last line: "Tonight, I\'m giving Number Nine back to you."'),
        WHO('panda'),
        S('panda','……（他捂住了嘴）舅舅他……一直在说"欠"的，就是这个？','…(He covers his mouth) Is that what Uncle meant all this time by "owing"?'),
        FLAG('read_speech')],'clue:0909'],
      ['「别乱翻别人的手机。先交给莫姐保管。」','"Don\'t go through someone\'s phone. Give it to Sister Mo to keep."',1,[
        S('panda','……嗯。你说得对。','…Yeah. You\'re right.'),
        FLAG('phone_kept')]],
      ['「Panda，你舅舅的密码，你知道吗？」','"Panda, do you know your uncle\'s passcode?"',0,[
        S('panda','（他犹豫了很久）……我、我不能说。他会生气的。','(A long hesitation) …I c-can\'t. He\'d be angry.')]])]),
  WHO('panda'),
  S('panda','（瘫坐在地上）……能给我来一杯吗？我腿软了。','(Slumps onto the floor) …Can I get a drink? My legs have gone to jelly.'),
  S('panda','【别太冲】……【甜一点】，【暖一点】的。我现在只想抱着点什么。','【Nothing harsh】… 【something sweet】, 【something warm】. Right now I just want something to hold on to.'),
  MX({accept:['brown_sugar_milk','osmanthus_oolong','white_russian','apple_highball','yuzu_soju'],best:'brown_sugar_milk',want:['奶香','温和'],avoid:['烈','苦','酸'],str:'low'},
   [S('panda','（双手捧着杯子，小口小口地喝）……好多了。','(Cradling the glass in both hands, small sips) …Much better.'),
    S('panda','舅舅以前说，Space 的调酒师，是他见过最会照顾人的。我现在信了。','Uncle said Space\'s bartender was the most caring he\'d ever met. I believe him now.')],
   [S('panda','嗯……谢谢。','Mm… thanks.')],
   [S('panda','（呛了一下）……咳咳，有点冲……','(Chokes a little) …Cough, that\'s strong…'),
    EMO('💦')],
   [S('panda','（喝了一口，眼睛红了）……咖啡味。','(One sip and his eyes go red) …Coffee.'),
    S('panda','舅舅每天早上都要喝一杯加奶加糖的咖啡。他跟所有人说他只喝黑的——跟 Kevin 一样嘴硬。','Every morning Uncle has a coffee with milk and sugar. He tells everyone he drinks it black. Stubborn, just like Kevin.'),
    S('panda','（他吸了吸鼻子）你知道吗……上个月，他让我陪他去老街，在一家关着门的旧店门口站了一个小时。门牌上写着：老街 9 号。','(He sniffs) You know… last month he had me go with him to the old street. We stood outside a closed-up old shop for an hour. The door plate said: 9 Old Street.'),
    FLAG('panda_oldstreet')]),
  WHO('kevin'),
  S('kevin','（盯着屏幕）还有一件事。R 账号关电之前十分钟，有人在后厨的点单屏上，查过今晚的【流程单】。登录用的是员工通用账号——谁都能用。','(Staring at the screen) One more thing. Ten minutes before R cut the power, someone at the kitchen order screen looked up tonight\'s 【run sheet】. Using the shared staff account. Anyone could have.'),
  N('（有人提前知道灯会暗。而且……那个人，不是理查德。）','(Someone knew the lights would go down. And… it wasn\'t Richard.)')]},

 {who:'ace',steps:[
  CARD('— 01:00 —','— 1:00 AM —'),
  N('走廊里传来争吵声。你端着冰桶走过去，看见 Ace 堵在洗手间门口，天哥靠着墙，手里捏着一块纸巾，咳个不停。','Raised voices from the corridor. You head over with an ice bucket and find Ace blocking the restroom door, Brother Tian leaning on the wall, a tissue in his fist, coughing nonstop.'),
  N('小陈站在中间，手里还端着一杯没送出去的温水。','Xiao Chen stands between them, still holding a glass of warm water he never got to deliver.'),
  S('ace','我看见了。灯灭的那一下，吧台那边有金色的东西闪了一下。','I saw it. When the lights died, something gold flashed over by the bar.'),
  S('ace','整个大厅戴金链子的，就他一个。','He\'s the only one in the whole room wearing a gold chain.'),
  WHO('tiange'),
  S('tiange','（咳了两声，笑了）……兄弟，你看见金光，就说是我？那你看见月亮，是不是还要说是我偷的？','(Coughs twice, then laughs) …Kid, you see a gold flash and it\'s me? See the moon, will you say I stole that too?'),
  WHO('ace'),
  S('ace','奖杯没了，最大的受益人是谁？今晚的冠军本来是他，第四届。拿走奖杯，是怕理查德宣布的不是他吧？','Who gains most from the trophy vanishing? Tonight\'s champion was going to be him, fourth title. Took the trophy because he was scared Richard wouldn\'t announce his name, right?'),
  S('ace','（他攥紧了手机）公司刚打电话给我。他们说，比赛没有结果，我的出道企划……就算作废。','(He grips his phone) My agency just called. They say with no result, my debut plan… is void.'),
  EMO('💢'),
  N('（三个人同时看向你。）','(All three of them turn to you.)'),
  C(['「Ace，你看到的金光，可能就是奖杯本身。」','"Ace, the gold flash you saw might have been the trophy itself."',1,[
      S('ace','……（他愣了一下）奖杯……','…(He blinks) The trophy…'),
      S('ace','……也对。镀金的。手电一扫，当然会闪。','…Fair. It\'s gold-plated. Any flashlight would make it flash.'),
      FLAG('tian_doubt_lifted')]],
    ['「我看到的那只手腕上，不是金链，是一根红绳。」','"The wrist I saw had no gold chain. It had a red string."',3,[
      N('走廊安静了。','The corridor goes quiet.'),
      WHO('tiange'),
      S('tiange','（他慢慢站直了）……红绳？','(He slowly straightens) …A red string?'),
      S('tiange','兄弟。这整条街上，手腕上系红绳、系了二十年都没摘的人，我只认识一个。','Brother. On this whole street, I know exactly one man who\'s worn a red string on his wrist for twenty years without taking it off.'),
      N('他没说下去。可他的眼神，往「九号」所在的方向看了一眼。','He doesn\'t finish. But his eyes flick in the direction of the old street.'),
      FLAG('tian_cleared'),FLAG('tian_knows')],'clue:红绳'],
    ['「小陈，停电的时候，天哥在哪？」','"Xiao Chen, where was Brother Tian when the power went?"',2,[
      WHO('xiaochen'),
      S('xiaochen','……在洗手间。我给他送水，敲了门，他在里面咳。灯灭的时候，我们俩都在这条走廊里。','…In the restroom. I was bringing him water. I knocked, he was coughing inside. When the lights died, we were both in this corridor.'),
      S('xiaochen','黑暗里，有两个人从我身边挤过去，往员工通道那边跑。一个人走路很重，另一个……身上有一股【冬瓜茶味】。','In the dark, two people pushed past me toward the staff passage. One walked heavy. The other… smelled of 【winter melon tea】.'),
      FLAG('tian_cleared'),FLAG('chen_witness')]],
    ['「Ace 说得有道理。天哥，你确实有动机。」','"Ace has a point. Brother Tian, you do have a motive."',-2,[
      WHO('tiange'),
      S('tiange','（他看了你很久，然后把纸巾扔进垃圾桶）……兄弟。我拿了三届冠军，从来没碰过那个奖杯一下。','(He looks at you a long time, then tosses the tissue in the bin) …Brother. I\'ve won three titles and never once touched that trophy.'),
      S('tiange','因为我的第一个冠军，奖品是一杯冬瓜威士忌。那才是我认的奖杯。','Because my first title\'s prize was a winter melon whiskey. That\'s the only trophy I recognise.'),
      N('他从你身边走过去，没再回头。','He walks past you and doesn\'t look back.'),
      FLAG('side_ace6'),AFF(-1)]]),
  WHO('ace'),
  IF(['tian_cleared'],[
    S('ace','（他低下头，攥着手机的手松开了）……对不起，天哥。我……我太怕了。','(He looks down; his grip on the phone loosens) …Sorry, Brother Tian. I… I was just so scared.'),
    WHO('tiange'),
    S('tiange','（拍了拍他的肩）小子，你今晚唱得不错。比我十九岁的时候好。','(Pats his shoulder) Kid, you sang well tonight. Better than me at nineteen.'),
    WHO('ace')]),
  S('ace','……能给我一杯吗？要【清醒】的。【别甜】。我得想想，明天怎么跟公司说。','…Can I get a drink? Something 【clear-headed】. 【Not sweet】. I need to figure out what to tell the agency tomorrow.'),
  IF('ace_flower',[S('ace','……或者，想想要不要回家。','…Or whether to go home.')]),
  MX({accept:['gin_tonic','tom_collins','dry_martini','cucumber_cooler','jasmine_gin','hugo'],best:'cucumber_cooler',want:['草本','气泡'],avoid:['甜','奶香','烈'],str:'low'},
   [S('ace','（喝了一口，长长地呼出一口气）……清醒了。','(Sips and lets out a long breath) …Clear-headed.'),
    S('ace','明天，我跟公司说：比赛没结果，可我唱了一首我自己满意的歌。他们要作废，就作废吧。','Tomorrow I\'ll tell the agency: there was no result, but I sang a song I\'m proud of. If they want to void me, let them.')],
   [S('ace','嗯。够清醒。','Mm. Clear enough.')],
   [S('ace','……太甜了。我说了别甜。','…Too sweet. I said not sweet.'),
    EMO('💢')],
   [S('ace','（闻了一下，笑了——不是营业的那种笑）……花香。','(He smells it and smiles, not his camera smile) …Flowers.'),
    S('ace','你上次就知道了吧。我妈的花店。','You knew last time, didn\'t you. My mom\'s flower shop.'),
    S('ace','我刚刚给她打了电话。两年来第一次。她第一句话是：「冠军拿了吗？」第二句是：「拿不拿都回来吃饭。」','I just called her. First time in two years. Her first words were "Did you win?" Her second: "Come home for dinner either way."'),
    FLAG('ace_home'),TIP(15)]),
  IF('side_ace6',[N('（天哥走的时候，一直在咳。你想追上去，可走廊尽头，已经没有人了。）','(Brother Tian was coughing as he left. You want to go after him, but the end of the corridor is already empty.)')])]},

 {who:'kc',steps:[
  CARD('— 01:40 —','— 1:40 AM —'),
  IF('doors_shut',[N('KC 站在门口，手已经搭在门把手上了。门是你让人关的。她没推。','KC stands by the door, hand already on the handle. You were the one who had it shut. She hasn\'t pushed it open.')],
    [N('KC 站在门口抽烟——不对，她手里只是一根没点的烟。她已经在那儿站了很久。','KC is standing in the doorway smoking. No: it\'s just an unlit cigarette in her fingers. She\'s been standing there a long time.')]),
  S('kc','别看我。我没拿那个破奖杯。','Don\'t look at me. I didn\'t take that stupid trophy.'),
  C(['「我知道不是你。黑暗里那股冬瓜茶味，不是你身上的。」','"I know it wasn\'t you. That winter melon tea smell in the dark wasn\'t yours."',2,[
      N('KC 夹着烟的手，停住了。','KC\'s hand, holding the cigarette, goes still.'),
      S('kc','……冬瓜茶？','…Winter melon tea?'),
      S('kc','他今晚来之前，在你们后厨熬了一锅冬瓜茶。熬了三个小时，跟以前在「九号」一模一样。我闻着那个味，在门口站了半个钟头才敢进来。','Before he came tonight, he spent three hours boiling a pot of winter melon tea in your kitchen. Exactly like he used to at Number Nine. I stood outside smelling it for half an hour before I dared come in.'),
      S('kc','……你说的，是我师父。','…You\'re talking about my mentor.'),
      FLAG('kc_confirms')],'clue:冬瓜茶味'],
    ['「你跟理查德，是不是有过节？」','"Do you and Richard have history?"',1,[
      S('kc','（她笑了一下，很冷）有过节？我恨他。','(A cold little laugh) History? I hate him.'),
      FLAG('kc_hate')]],
    ['（递给她打火机）','(Hand her a lighter)',-1,[
      S('kc','我戒了。三年前就戒了。……师父说，调酒师的舌头，比命重要。','I quit. Three years ago. …My mentor said a bartender\'s tongue matters more than their life.')]]),
  S('kc','你知道「九号」是怎么倒的吗？','Do you know how Number Nine went under?'),
  S('kc','房租一年涨三倍。我那时候十九岁，跑去房东公司门口堵人，堵了一个星期，连个能说话的人都没见着。','Rent tripled in a year. I was nineteen. I went and staked out the landlord\'s office for a week. Never met a single person who could talk to me.'),
  IF([{aff:'kc',min:5}],[
    S('kc','后来我在一份文件上，看见了那家公司老板的签名。一个字母：R。','Later I saw that company owner\'s signature on a document. A single letter: R.'),
    S('kc','那栋楼的【业主】，就是理查德。他每周五坐在我师父的吧台前喝冬瓜威士忌，然后签字把他赶走了。','The 【landlord】 of that building was Richard. Every Friday he sat at my mentor\'s bar drinking winter melon whiskey, and then he signed the papers that threw him out.'),
    FLAG('kc_told')],
   [S('kc','……算了。跟你说这些干什么。','…Forget it. Why am I telling you this.')]),
  N('（第三格抽屉。）','(The third drawer.)'),
  C(['（冬瓜茶味……他在吧台待过。拉开吧台下的抽屉）','(Winter melon tea… he was at the bar. Open the drawers under the counter)',1,[
      N('抽屉里，是一本牛皮纸包着的旧本子。封面用毛笔写着两个字：「九号」。','Inside is an old notebook wrapped in kraft paper. On the cover, in brush calligraphy: "Number Nine".'),
      N('翻开第一页，是一行字迹很重的钢笔字：「给新来的。别学我，别关门。——九」','On the first page, in heavy fountain-pen strokes: "For the new one. Don\'t be like me. Don\'t close the doors. — Nine"'),
      N('本子里夹着一片干掉的桂花。整本都是一股淡淡的冬瓜茶味。这是「九号」的【配方本】。','A dried osmanthus blossom is pressed between the pages. The whole book smells faintly of winter melon tea. It\'s Number Nine\'s 【recipe book】.'),
      FLAG('found_book'),
      WHO('kc'),
      N('KC 看见那个封面，整个人僵住了。','KC sees the cover and goes rigid.'),
      S('kc','……他把这个，给你了？','…He gave you this?'),
      S('kc','我跟了他四年。他说这本子要传给"能把店开下去的人"。……他给了你。','I worked under him for four years. He said this book would go to "whoever can keep a bar open." …He gave it to you.'),
      EMO('…'),
      C(['（把本子递给她）「这本子该是你的。」','(Hold the book out to her) "This should be yours."',3,[
          S('kc','（她没有接，只是看着）……他写的是"给新来的"。不是给我。','(She doesn\'t take it, only looks) …He wrote "for the new one." Not for me.'),
          ME('那我们一起看。他写的东西，你看得懂的比我多。','Then we\'ll read it together. You understand his handwriting better than I do.'),
          S('kc','……（她终于伸手，翻开了一页。翻到一半，她笑出了声）这一页，是我十八岁时候调砸的那杯。他记下来了。他连这个都记下来了。','…(She finally reaches out and turns a page. Halfway down, she laughs) This page is the drink I botched when I was eighteen. He wrote it down. He even wrote that down.'),
          FLAG('kc_book')]],
        ['「他给我，是有他的理由。」','"He gave it to me for a reason."',0,[
          S('kc','……是。他做什么都有理由。就是从来不说。','…Sure. He always has his reasons. He just never says them.'),
          FLAG('keep_book')]])],'clue:冬瓜茶味'],
    ['（问她：「你师父今晚去哪了？」）','(Ask her: "Where did your mentor go tonight?")',0,[
      S('kc','……我也在找他。他手机关机，家里没人。','…I\'m looking for him too. Phone\'s off, no one at his place.'),
      S('kc','以前他心里有事，就会去老街，在「九号」那扇卷帘门前面坐着。可那家店，早就不是他的了。','He used to go to the old street when something was on his mind. Sit in front of Number Nine\'s shutter. But that shop hasn\'t been his for years.')]]),
  S('kc','给我调一杯。','Make me a drink.'),
  S('kc','照「九号」的规矩：客人不点单，调酒师【看着办】。……你调什么，我都喝。','Number Nine rules: the guest doesn\'t order, the bartender 【reads them】. …Whatever you make, I\'ll drink.'),
  N('（她今晚想要的，不是酸也不是咸。是一口能咽下去的东西。……她最爱的，是那种要慢慢喝、后面才回甘的味道。）','(Tonight she doesn\'t want sour or salt. She wants something she can actually swallow. …What she loves most is the kind you sip slowly until the sweetness comes at the end.)'),
  MX({accept:['negroni','last_word','mezcal_negroni','sazerac','old_fashioned','penicillin'],best:'last_word',want:['烈','优雅'],avoid:['甜','奶香','气泡'],str:'mid'},
   [S('kc','（喝了一口，很久没说话）……「临别一语」的路子。','(Sips, silent a long while) …"Last Word" territory.'),
    S('kc','你知道这杯为什么叫这个名字吗？说的是，最后一句话，要留给值得的人。','You know why it\'s called that? The last word should be saved for someone who deserves it.'),
    S('kc','……我想听他亲口说一句。不管是什么。','…I want to hear him say something himself. Anything.'),AFF(1)],
   [S('kc','……能喝。','…Drinkable.')],
   [S('kc','（皱眉）……你没在看我。你在看我的点单。','(Frowns) …You weren\'t reading me. You were reading my order.')],
   [S('kc','（一口下去，她闭上了眼睛）……药草，苦，最后才甜。','(One sip and she closes her eyes) …Herbal, bitter, and only sweet at the very end.'),
    S('kc','你调出了我师父的味道。……不对，是他教给我、我又忘了的味道。','You made my mentor\'s taste. …No. The taste he taught me, that I forgot.'),
    S('kc','（她把那根没点的烟折断了，扔进垃圾桶）明天我陪你找他。不管他在哪。','(She snaps the unlit cigarette and drops it in the bin) Tomorrow I\'ll help you find him. Wherever he is.'),
    FLAG('kc_ally'),AFF(2)])]},

 {who:'xiaochen',steps:[
  CARD('— 02:30 · 打烊 —','— 2:30 AM · Closing —'),
  N('大厅空了。地上全是彩带、气球皮和碎玻璃。小陈拿着扫帚，一下一下扫着舞台。','The lounge is empty. The floor is all streamers, balloon scraps and broken glass. Xiao Chen sweeps the stage, stroke after stroke.'),
  IF('chen_badge',[N('他的马甲上，没有名牌。名牌还在你这儿——你下午替他保管的那个。它一直放在吧台尽头，奖杯旁边。','There\'s no badge on his vest. It\'s still with you, the one you minded for him this afternoon. It sat at the end of the counter, right beside the trophy.'),
    N('经理老周临走前，盯着那块名牌看了很久。','Before leaving, Old Zhou the manager stared at that badge for a long time.')]),
  S('xiaochen','……经理让我明天先别来了。他说，停电的时候，离奖杯最近的员工，是我。','…The manager told me not to come in tomorrow. He says the staff member closest to the trophy during the blackout was me.'),
  S('xiaochen','我在台上。我是决赛选手。我怎么可能……','I was on stage. I was a finalist. How could I…'),
  EMO('…'),
  C(['「我会找出真相。明天这个时候，你还会站在这儿。」','"I\'ll find the truth. This time tomorrow, you\'ll be standing right here."',2,[
      S('xiaochen','（他停下扫帚，看着你）……你这个人，答应别人的事，都会做到吗？','(He stops sweeping and looks at you) …Do you always keep promises to people?'),
      ME('答应你的，会。','The ones I make to you, yes.'),
      FLAG('promise_chen')]],
    ['「要不……你先承认个"保管不当"，把事情压下去？」','"Maybe… just admit to "careless handling" and let it blow over?"',-2,[
      S('xiaochen','……（他把扫帚靠在墙上）你也觉得是我。','…(He leans the broom against the wall) You think it was me too.'),
      FLAG('chen_hurt')]],
    ['（什么都不说，拿起另一把扫帚，跟他一起扫）','(Say nothing. Pick up another broom and sweep beside him)',2,[
      N('你们一起扫了十分钟，谁都没说话。扫到舞台边上的时候，他忽然笑了一下。','You sweep together for ten minutes without a word. When you reach the edge of the stage, he suddenly smiles.'),
      S('xiaochen','……谢谢。','…Thanks.')]]),
  S('xiaochen','最后一杯，我请你。……不对，是你调，我请。','Last drink\'s on me. …Well, you mix, I pay.'),
  S('xiaochen','【不要酒】了，我明天……可能要去找工作。来点【酸的】，【有气泡】的，能让人【醒】过来的。','【No alcohol】. Tomorrow I… might be job hunting. Something 【sour】, 【fizzy】, something that 【wakes you up】.'),
  MX({accept:['virgin_mojito','shirley','cucumber_cooler'],best:'cucumber_cooler',want:['草本','气泡','无酒精'],avoid:['烈','甜','奶香'],str:'low'},
   [S('xiaochen','（喝了一口）……醒了。','(Sips) …Awake.'),
    S('xiaochen','（他把那杯举起来，对着空荡荡的大厅）敬今晚。至少我唱完了。','(He raises it to the empty lounge) To tonight. At least I finished my song.')],
   [S('xiaochen','嗯。谢谢。','Mm. Thanks.')],
   [S('xiaochen','……（他喝了一口就放下了）明天再说吧。','…(One sip and he sets it down) Let\'s talk tomorrow.')],
   [S('xiaochen','（喝了一口，愣住了）……咸的？还有……罗勒？','(One sip, and he freezes) …Salty? And… basil?'),
    S('xiaochen','海风，还有被太阳晒过的草。……你又给我调出那片草地了。','Sea wind, and grass warmed in the sun. …You\'ve mixed me that lawn again.'),
    S('xiaochen','（他从口袋里掏出手机，翻出一个很久没打的号码）……我想给乐队的鼓手打个电话。','(He pulls out his phone and scrolls to a number he hasn\'t called in ages) …I think I\'ll call our old drummer.'),
    FLAG('chen_band'),TIP(10)]),
  CARD('— 04:12 —','— 4:12 AM —'),
  N('你锁上门，正要走，手机震了一下。','You lock up and are about to leave when your phone buzzes.'),
  IF('bolo_bread',[N('是菠萝包。他每天四点起床烤第一炉面包——你知道的，他跟你说过。','It\'s Pineapple Bun. He gets up at four for the first batch. You know; he told you.')],
    [N('是菠萝包。他说面包店四点就要开工。','It\'s Pineapple Bun. He says the bakery starts at four.')]),
  N('「你们店的大叔是不是住老街？我送面包路过老街 9 号，那家关了好多年的店，里面亮着灯！还有两个人在吵架！」','"Do any of your regulars live on the old street? Delivering bread past 9 Old Street, that shop that\'s been shut for years: the lights are on inside! And two people are arguing!"'),
  N('下面附了一张照片。模糊的卷帘门半开着，门缝里透出暖黄色的光。门头上，一块褪了色的木招牌——「九号」。','Below it, a blurry photo. A shutter half-raised, warm yellow light leaking through the gap. Above it, a faded wooden sign: "Number Nine."'),
  N('（【九号亮灯】。）','(【Number Nine\'s lights are on】.)'),
  N('（你忽然想起来了——停电之后，你在人群里找了一圈，少了的那个人。）','(Suddenly you remember who you couldn\'t find in the crowd after the blackout.)'),
  N('（今晚，酒哥一次都没有出现过。）','(All night, Brother Jiu never showed his face again.)'),
  CT(8,[N('（你犹豫了太久。手机屏幕暗了下去。……明天，还有一整个晚上。）','(You hesitate too long. The screen goes dark. …There\'s still all of tomorrow night.)')],
    ['（回菠萝包）「帮我盯一下，看他们什么时候走。」','(Reply to Pineapple Bun) "Keep an eye on them for me. See when they leave."',1,[
      N('「收到！！我烤完第二炉再去看！」后面跟了三个面包表情。','"Roger!! I\'ll check again after the second batch!" Followed by three bread emojis.'),
      FLAG('bolo_watch')]],
    ['（现在就去老街）','(Go to the old street right now)',0,[
      N('你跑到老街的时候，天已经快亮了。「九号」的卷帘门关着，灯也灭了。','By the time you reach the old street, it\'s nearly dawn. Number Nine\'s shutter is down and the lights are off.'),
      N('门口的台阶上，放着两只空杯子。一只杯底残着冬瓜茶的颜色，另一只，是空的马天尼杯。','On the step out front sit two empty glasses. One has a trace of winter melon tea at the bottom. The other is an empty martini glass.'),
      FLAG('saw_glasses')]],
    ['（把照片转发给 KC）','(Forward the photo to KC)',1,[
      N('三秒后，KC 回了一个字：「靠。」又过了三秒：「明天你别一个人去。」','Three seconds later KC replies with a single curse. Three seconds after that: "Don\'t go alone tomorrow."'),
      FLAG('kc_ally')],'kc_card'])]}
 ]},
// ===================== NIGHT 7 =====================
{title:['最后一杯','Last Call'],
 preview:['——「九号」的故事，到这里先告一段落。番外：一周后，门口贴出了一张悬赏通告。画上的女人，涂着红唇……','Number Nine\'s story pauses here. Side story: a week later, a reward notice goes up by the door. The woman in the picture wears red lipstick…'],
 intro:[CARD('— 第七夜 · 19:30 · 距离莫姐的期限，还有四个半小时 —','— Night Seven · 7:30 PM · Four and a half hours until Sister Mo\'s deadline —'),
        N('Space 今晚没有营业。门口贴着一张手写的纸：「设备检修，暂停营业一天」。','Space isn\'t open tonight. A handwritten sign on the door reads: "Closed one day for equipment maintenance."'),
        N('可大厅里的人，一个都不少。','But the lounge isn\'t empty. Not one person is missing.'),
        N('莫姐坐在评委席，面前摆着手机，屏幕上是一个已经输好的号码，只差按下拨号键。理查德的黑伞，还靠在她旁边的椅子上。','Sister Mo sits at the judges\' table, her phone in front of her, a number already typed in, one tap from dialling. Richard\'s black umbrella still leans on the chair beside her.'),
        N('酒哥和理查德，一整天都没有消息。','There\'s been no word from Brother Jiu or Richard all day.'),
        IF('kc_ally',[N('KC 坐在吧台最边上的位子。她今天没穿马甲，只穿了一件旧旧的白衬衫——领口绣着一个小小的「9」。','KC sits on the last stool at the bar. No vest today, just an old white shirt with a tiny "9" stitched on the collar.')]),
        IF('found_book',[N('那本「九号」的配方本，就放在你的工具箱最上层。你昨晚把它从头到尾翻了一遍。最后一页是空白的，只写着一个标题：「最后一杯」。','Number Nine\'s recipe book sits at the top of your toolbox. You read it cover to cover last night. The last page is blank except for a title: "Last Call."')]),
        N('（今晚，要把那十秒钟的黑暗，一点一点拼回来。）','(Tonight, you have to piece those ten seconds of darkness back together, one fragment at a time.)')],
 scenes:[
 {who:'xiaochen',steps:[
  N('员工休息室的门开着。小陈蹲在柜子前，正把自己的东西一件一件装进纸箱。','The staff room door is open. Xiao Chen crouches by his locker, packing his things into a cardboard box one by one.'),
  N('经理老周站在门口，手里捏着那块金色的名牌。','Old Zhou the manager stands in the doorway, the gold name badge in his hand.'),
  IF('chen_badge',[N('「名牌在奖杯旁边，人在台上不在台下——十秒钟，够一个服务生做很多事了。」老周说。他看都没看你一眼。','"His badge was right by the trophy. He was on stage, not off it. Ten seconds is plenty for a server," Old Zhou says, without so much as a glance at you.')],
    [N('「停电的时候，所有员工都在岗，只有他跑上了台——十秒钟，够一个服务生做很多事了。」老周说。','"When the power went, every staffer was at their post except him. He ran off to the stage. Ten seconds is plenty for a server," Old Zhou says.')]),
  IF('chen_hurt',[S('xiaochen','（他头也没抬）……你也来看我收拾东西？','(Without looking up) …Come to watch me pack too?')],
    [S('xiaochen','（他抬起头，勉强笑了一下）……来送我？','(He looks up and forces a smile) …Here to see me off?')]),
  C(['（挡在老周和纸箱中间）「经理，名牌是我替他保管的。要怪，先怪我。」','(Step between Old Zhou and the box) "Boss, I was minding that badge for him. If you want to blame someone, start with me."',3,[
      N('老周张了张嘴，没说出话来。','Old Zhou opens his mouth, then shuts it.'),
      N('「……给你到十二点。」他把名牌拍在柜子上，走了。','"…You have until midnight." He slaps the badge onto the locker and walks off.'),
      S('xiaochen','（他看着你，眼圈一点一点红了）……你疯了。你会被一起开除的。','(He stares at you, his eyes slowly reddening) …You\'re crazy. You\'ll get fired with me.'),
      FLAG('defend_chen')],'chen_badge'],
    ['「经理，给我到十二点。我会把真相带回来。」','"Boss, give me until midnight. I\'ll bring back the truth."',2,[
      N('老周盯着你看了很久。「……十二点。」','Old Zhou studies you a long time. "…Midnight."'),
      FLAG('defend_chen')]],
    ['（不插手。员工的事，经理说了算）','(Stay out of it. Staff matters are the manager\'s call)',-2,[
      N('老周点点头，走了。小陈低下头，继续往箱子里装东西。一件，又一件。','Old Zhou nods and leaves. Xiao Chen bows his head and keeps packing. One thing, then another.')]]),
  IF('promise_chen',[S('xiaochen','你昨晚说，"答应你的，会"。……我还记着。','Last night you said, "The ones I make to you, yes." …I remember.')]),
  S('xiaochen','……我想喝一杯。最后一杯，在这儿。','…I want a drink. One last one, here.'),
  S('xiaochen','我今天不上班了，可以【有点酒】。要【清清爽爽】的，带一点【草的味道】——像我们乐队第一次演出那天。','I\'m off the clock, so 【a little alcohol】 is fine. Something 【crisp and clean】, with a hint of 【grass】. Like the day of our band\'s first gig.'),
  IF('chen_sea',[S('xiaochen','……你知道的。海边的那天。','…You know the one. That day by the sea.')]),
  MX({accept:['gin_tonic','jp_highball','hugo','mojito','jasmine_gin'],best:'cucumber_cooler',want:['草本','气泡'],avoid:['甜','奶香','烈'],str:'low'},
   [S('xiaochen','（喝了一口）……草地。阳光。','(Sips) …Grass. Sunshine.'),
    S('xiaochen','好。不管今晚结果怎么样，我都不后悔昨天上了台。','Okay. Whatever happens tonight, I don\'t regret getting on that stage.'),
    AFF(1)],
   [S('xiaochen','嗯……谢谢。','Mm… thanks.')],
   [S('xiaochen','……（他把杯子推开）算了。','…(He pushes the glass away) Never mind.')],
   [S('xiaochen','（喝了一口，眼睛亮了）海风……你连海风都放进去了。','(One sip and his eyes light up) Sea wind… you even put the sea wind in.'),
    S('xiaochen','（他把纸箱里的东西，一件一件拿出来，放回了柜子里）我等到十二点。','(He takes his things out of the box one by one and puts them back in the locker) I\'ll wait until midnight.'),
    FLAG('chen_waits')]),
  S('xiaochen','对了……停电那会儿，有件事我没跟经理说。','Oh… there\'s something about the blackout I didn\'t tell the manager.'),
  IF('chen_witness',[S('xiaochen','我昨天跟你说过的——那两个人，一个走路很重，一个身上有【冬瓜茶味】。我后来想起来了：走路重的那个，一边走一边在说"慢点、慢点，我膝盖不好"。','What I told you yesterday: of those two people, one walked heavy and one smelled of 【winter melon tea】. I\'ve remembered since: the heavy one kept saying "slow down, slow down, my knees."')],
    [S('xiaochen','黑暗里，有两个人从我身边挤过去。其中一个，身上有一股【冬瓜茶味】。','In the dark, two people pushed past me. One of them smelled of 【winter melon tea】.')]),
  N('（膝盖不好、穿西装的人……还有一股冬瓜茶味。）','(Someone with bad knees, in a suit… and the smell of winter melon tea.)')]},

 {who:'luoyu',steps:[
  CARD('— 20:15 —','— 8:15 PM —'),
  N('后门「砰」地被推开，一个娃娃脸的男孩气喘吁吁地冲了进来，后面跟着一个抱着面包筐的金色卷毛。','The back door bangs open. A baby-faced boy charges in, panting, followed by a golden-curled baker hugging a bread basket.'),
  IF('luoyu_friend',[FLAG('luoyu_helps')]),
  IF('luoyu_forgive',[FLAG('luoyu_helps')]),
  IF('luoyu_party',[FLAG('luoyu_helps')]),
  IF('luoyu_helps',[
    S('luoyu','眼线报告！！','Lookout reporting!!'),
    S('luoyu','（举起小拇指）说好的，这条街上发生什么，我第一个告诉你！','(Holds up his pinky) A promise is a promise: anything happens on this street, you hear it from me first!')],
   [S('luoyu','那、那个……我有件事……可是我哥说，小孩子别多管闲事……','Um… there\'s something… but my brother says kids should mind their own business…'),
    CT(8,[S('luoyu','……算了。（他转身要走）','…Never mind. (He turns to go)'),
          WHO('boluobao'),
          S('boluobao','哎哎哎！小朋友，你刚才在路上跟我说的那个，快说啊！','Hey hey hey! Little guy, what you told me on the way here, say it!'),
          WHO('luoyu'),
          S('luoyu','……好吧。','…Fine.'),
          FLAG('luoyu_helps')],
      ['（蹲下来，跟他平视）「你说的话，我当大人的话听。」','(Crouch to his eye level) "I\'ll listen to you like I\'d listen to any adult."',2,[
        S('luoyu','（他的眼睛一下子亮了）……真的？','(His eyes light up) …Really?'),
        FLAG('luoyu_helps')]],
      ['「小朋友，大人在忙。」','"Kid, the grown-ups are busy."',-2,[
        S('luoyu','……你跟我哥一样。','…You\'re just like my brother.'),
        N('他抿着嘴，转身跑了。','He presses his lips together and runs off.'),
        WHO('boluobao'),
        S('boluobao','哎！他刚才说他看见……唉，算了，我也说不清。','Hey! He said he saw… ugh, never mind, I can\'t explain it right.'),
        WHO('luoyu')]])]),
  IF('luoyu_helps',[
    S('luoyu','前天晚上停电的时候，我在你们店后面的巷子里。我哥的朋友在那儿抽烟，我在帮他们放风……','The night of the blackout, I was in the alley behind your place. My brother\'s friends were smoking there and I was keeping lookout…'),
    S('luoyu','然后你们店的【后门】突然开了！两个大叔冲出来！一个穿西装，被另一个拽着走，一直喊「老九你慢点，我膝盖」！','Then your 【back door】 suddenly flew open! Two old guys came out! One in a suit, being dragged by the other, yelling "Lao Jiu, slow down, my knees"!'),
    S('luoyu','拽人的那个，怀里抱着一个金色的东西，用一条旧围裙包着。他们往老街那边去了！','The one doing the dragging had something gold in his arms, wrapped in an old apron. They went toward the old street!'),
    FLAG('luoyu_told')]),
  WHO('boluobao'),
  S('boluobao','我也有报告！','I have a report too!'),
  IF('bolo_watch',[
    S('boluobao','你让我盯着，我就盯着了！烤完第二炉，我又去了一趟老街。早上六点，那两个人从「九号」里出来，坐在门口台阶上——','You told me to keep watch, so I did! After the second batch I went back to the old street. At six in the morning those two came out of Number Nine and sat on the front step…'),
    S('boluobao','我把刚出炉的菠萝包分给他们，一人一个。穿西装的那个说"谢谢"，另一个……另一个哭了。','I gave them fresh pineapple buns, one each. The suit guy said "thank you." The other one… the other one cried.'),
    FLAG('bolo_saw_them')],
   [S('boluobao','昨天凌晨那张照片，你看了吧？老街 9 号，【九号亮灯】了！我今天早上再路过，灯又灭了，门口台阶上，放着两只空杯子。','You saw the photo I sent? 9 Old Street, 【Number Nine\'s lights were on】! This morning when I went by again the lights were off, and there were two empty glasses on the front step.')]),
  S('boluobao','……那家店，到底是谁的啊？','…Whose shop is that, anyway?'),
  WHO('luoyu'),
  S('luoyu','我跑了一路，渴死了！要【甜甜的】，【冒泡泡】的！（他看了一眼菠萝包）……还要【香香的】那种。','I ran all the way here, I\'m dying of thirst! Something 【sweet】 and 【bubbly】! (He glances at Pineapple Bun) …And 【nice-smelling】.'),
  S('luoyu','当然——【不能有酒】！','And of course: 【no alcohol】!'),
  MX({accept:['shirley','virgin_mojito','virgin_colada','cucumber_cooler'],best:'shirley',want:['甜','气泡','无酒精'],avoid:['烈','苦'],str:'low'},
   [S('luoyu','（咕嘟咕嘟喝了半杯）……活过来了！','(Gulps down half) …I live again!'),
    S('luoyu','眼线的报酬，就是这个！','This is a lookout\'s pay!')],
   [S('luoyu','嗯！解渴！','Mm! Thirst quenched!')],
   [S('luoyu','（闻了一下）……又有酒？！','(Sniffs) …Alcohol AGAIN?!'),
    EMO('💢')],
   [S('luoyu','（喝了一口，眼睛弯成两道缝）……奶奶的味道。','(One sip and his eyes become two happy slits) …Grandma\'s taste.'),
    S('luoyu','你又调出来了。……眼线永远是你的眼线。','You did it again. …I\'ll be your lookout forever.'),
    AFF(1)]),
  N('（后门。老街。一条旧围裙。……那天晚上，他们去了「九号」。）','(The back door. The old street. An old apron. …That night, they went to Number Nine.)')]},

 {who:'xiangge',steps:[
  CARD('— 21:10 —','— 9:10 PM —'),
  N('橙色皮夹克的男人推门进来，胳膊底下夹着一个厚厚的文件袋。他这次没有摔手机，而是把一张卡片「啪」地拍在了吧台上。','The man in the orange leather jacket walks in, a thick folder under his arm. This time he doesn\'t slam his phone. He slaps a card on the counter.'),
  IF(['xiang_promise'],[S('xiangge','律师执照。第三次。过了。','Bar licence. Third attempt. Passed.'),EMO('✨'),FLAG('xiang_passed')],
    [S('xiangge','实习律师证。……考是考过了，分数不好看，别问。','Trainee lawyer\'s card. …Passed, barely. Don\'t ask about the score.')]),
  IF('xiang_promise',[FLAG('xiang_helps')]),
  IF('side_xiang',[FLAG('xiang_helps')]),
  IF({aff:'xiangge',min:5},[FLAG('xiang_helps')]),
  IF('xiang_helps',[
    S('xiangge','听说你们这儿出了个"谜案"。我当了一整天律师，晚上再当一回侦探——你欠我的那杯，今天算利息。','Heard you\'ve got a "mystery" here. I\'ve been a lawyer all day; tonight I\'ll play detective again. That drink you owe me? Today it comes with interest.'),
    IF('side_xiang',[S('xiangge','上次你在酒哥面前替我说话。这回，换我替你跑腿。','Last time you backed me up in front of Jiu. This time I run errands for you.')]),
    S('xiangge','我查了老街 9 号的产权记录。','I pulled the property records for 9 Old Street.'),
    S('xiangge','六年前，那栋楼的【业主】是一家叫「R 控股」的公司。就是那一年，租金涨了三倍。法人代表：理查德。','Six years ago, the 【landlord】 of that building was a company called "R Holdings." That\'s the year the rent tripled. Legal representative: Richard.'),
    S('xiangge','上个月，理查德用个人名义，把那间铺面买了回来。然后——（他抽出一张复印件）他起草了一份【赠与合同】。受赠人一栏，写的是酒哥的本名。','Last month, Richard bought the shopfront back in his own name. And then (he slides out a photocopy) he drafted a 【deed of gift】. The recipient\'s name is Brother Jiu\'s real name.'),
    S('xiangge','合同还没签。受赠人那一栏的签名，是空的。','It hasn\'t been signed. The recipient\'s signature line is blank.'),
    FLAG('xiang_told')],
   [S('xiangge','我听说你们这儿出了事。不过我今天刚上岗，所里一堆卷宗，帮不上什么忙。','I heard something happened here. But it\'s my first day on the job and I\'m buried in files. Can\'t help much.'),
    S('xiangge','……只能说，老街那一片的楼，六年前全被一家公司收了。名字我记不清了，好像是一个字母开头。','…All I can say is that six years ago, one company bought up every building on that stretch of the old street. Can\'t remember the name. Started with a letter, I think.')]),
  N('门口的风铃又响了。一个扎着双丸子头的女孩抱着一本速写本跑了进来，发夹上的嫩芽一晃一晃。','The door chimes again. A girl with two hair buns runs in hugging a sketchbook, the sprout clip in her hair bobbing.'),
  WHO('ya'),
  IF('ya_lamp',[FLAG('ya_helps')]),
  IF('john_help',[FLAG('ya_helps')]),
  IF({aff:'ya',min:5},[FLAG('ya_helps')]),
  S('ya','我、我那天也在！歌王比赛，我和室友来看的！','I-I was there that night too! The karaoke contest, I came with my roommates!'),
  S('ya','我有个习惯，看到好看的画面就画下来。决赛最后，灯灭之前，那一下闪光——我画了。','I have a habit of sketching anything beautiful. At the end of the final, right before the lights went out, that flash: I drew it.'),
  IF('ya_helps',[
    N('她翻开速写本。铅笔线条很快，却很准：舞台的边，吧台的尽头，奖杯——还有奖杯旁边，一只伸过去的手。','She opens the sketchbook. Quick pencil lines, but precise: the edge of the stage, the end of the bar, the trophy, and beside it, a hand reaching out.'),
    N('那只手的手腕上，她用唯一的一点红色铅笔，画了一根细细的【红绳】。','Around that wrist, in the only touch of red pencil on the page, she\'s drawn a thin 【red string】.'),
    S('ya','整幅画只有这一点红，所以我记得特别清楚。……这个对你有用吗？','It\'s the only red in the whole sketch, so I remember it really clearly. …Does this help?'),
    FLAG('ya_told')],
   [S('ya','……可是我画得太乱了，自己都看不懂。（她把本子抱得更紧了）对不起。','…But it\'s too messy, I can\'t even read it myself. (She hugs the book tighter) Sorry.'),
    C(['「芽，那天晚上的台灯，还记得吗？」','"Ya, remember the counter lamp that night?"',2,[
        S('ya','（她愣了一下，慢慢翻开了本子）……记得。那，给你看。','(She pauses, then slowly opens the book) …I remember. Okay. Here.'),
        N('那只伸向奖杯的手腕上，有一根细细的【红绳】。整幅画里，只有这一点红色。','On the wrist reaching for the trophy is a thin 【red string】. The only red in the whole sketch.'),
        FLAG('ya_told')],'ya_lamp'],
      ['「没关系。谢谢你跑过来。」','"That\'s okay. Thanks for coming."',1,[
        S('ya','……嗯。','…Okay.')]]),
    ]),
  WHO('xiangge'),
  S('xiangge','好了，侦探的报酬。给我来一杯。','Right. The detective\'s fee. Pour me one.'),
  IF('xiang_passed',[S('xiangge','今天是庆功。要【烈】，要【够劲】……然后，嗯，你知道我那个秘密。','It\'s a celebration. 【Strong】, 【with a kick】… and, well, you know my secret.')],
    [S('xiangge','要【烈】，要【够劲】。今天累死了。','【Strong】, 【with a kick】. Today wore me out.')]),
  MX({accept:['old_fashioned','manhattan','penicillin','spicy_marg','mezcal_negroni','sazerac'],best:'old_fashioned',want:['烈','苦'],avoid:['甜','奶香','气泡'],str:'high'},
   [S('xiangge','（大冰块碰着杯壁）……这才叫酒。','(The big cube knocks the glass) …Now that\'s a drink.'),
    S('xiangge','去吧，侦探。我在这儿给你压阵。','Go on, detective. I\'ll hold the line here.')],
   [S('xiangge','够劲。行。','Strong enough. Fine.')],
   [S('xiangge','……今天就不跟你计较了。','…I\'ll let it slide today.')],
   [S('xiangge','（一口下去，眼睛都辣红了）……哈！就是这个！','(One sip and his eyes go red from the heat) …Ha! That\'s the one!'),
    S('xiangge','当律师的第一天，用一杯辣到天灵盖的酒收尾。……完美。','First day as a lawyer, ending with a drink that burns to the skull. …Perfect.'),
    AFF(1)])]},

 {who:'mojie',steps:[
  CARD('— 23:00 · 距离期限，还有一个小时 —','— 11:00 PM · One hour until the deadline —'),
  N('大厅里坐满了人。','The lounge is full.'),
  N('评委席上是莫姐。旁边，经理老周抱着胳膊。Kevin 和 Panda 挤在一张沙发上。天哥靠着墙，Ace 站在离他两步远的地方。KC 坐在吧台最边上。小陈站在员工通道口，没换衣服。','Sister Mo at the judges\' table. Beside her, Old Zhou with his arms folded. Kevin and Panda squeezed onto one sofa. Brother Tian leaning on the wall, Ace two steps away from him. KC on the last bar stool. Xiao Chen at the mouth of the staff passage, still in street clothes.'),
  S('mojie','（她把手机屏幕朝上，放在桌子正中间）一个小时。','(She places her phone face-up in the middle of the table) One hour.'),
  S('mojie','十二点一到，我就报警，然后告诉赞助商：奖杯丢了，投资人失踪了，Space 的第一届歌王比赛——是一场笑话。','At midnight I call the police and tell the sponsors: the trophy\'s gone, the investor\'s missing, and Space\'s first Karaoke King contest was a joke.'),
  S('mojie','在那之前……（她看向你）你说你有话要说。我先要一杯。','Before that… (she looks at you) you said you had something to say. I\'ll have a drink first.'),
  S('mojie','今晚我什么都不挑。【能让我听得进去】的就行。','Tonight I\'m not picky. Something that 【lets me listen】.'),
  MX({accept:['negroni','espresso_martini','dry_martini','jasmine_gin','sake_tini','penicillin'],best:'negroni',want:['苦','草本'],avoid:['甜','奶香'],str:'mid'},
   [S('mojie','（喝了一口，把手机往旁边推了推）……好。我听。','(Sips and nudges her phone aside) …Alright. I\'m listening.'),
    FLAG('mo_listens')],
   [S('mojie','……说吧。','…Go ahead.')],
   [S('mojie','（放下杯子，看了一眼手机上的时间）……你最好说得比调得好。','(Sets the glass down and glances at the time) …You\'d better talk better than you mix.')],
   [S('mojie','（她闭上眼睛，喝完了一整杯）……你从第一天起，就没让我失望过。','(She closes her eyes and drains the glass) …You haven\'t disappointed me once since the first day.'),
    S('mojie','（她把手机屏幕扣了过去）说吧。不管说什么，我都信你一半。','(She turns her phone face-down) Go on. Whatever you say, I\'ll believe half of it on credit.'),
    FLAG('mo_listens')]),
  N('所有人都在看你。','Everyone is looking at you.'),
  N('（第一件事：灯，是谁关的？）','(First: who turned off the lights?)'),
  C(['「是 Kevin。整个系统是他写的，只有他能做到。」','"Kevin. He wrote the whole system. Only he could do it."',-2,[
      WHO('kevin'),
      S('kevin','……（他的脸一下子白了）我……我没有……','…(His face goes white) I… I didn\'t…'),
      WHO('panda'),
      S('panda','喂！Kevin 昨晚在地上坐了一整夜帮忙查日志！','Hey! Kevin sat on the floor all night going through the logs to help!'),
      WHO('mojie'),
      S('mojie','（摇了摇头）……不对。','(Shakes her head) …No.'),
      FLAG('d_power_wrong')]],
    ['「是经理。上次就是他用吧台的点单机替 R 登录的。」','"The manager. Last time, he was the one who logged in as R from the bar terminal."',-1,[
      N('老周差点从椅子上跳起来：「那次是理查德先生让我做的！这次我根本不知道！」','Old Zhou nearly leaps out of his chair: "Mr. Richard asked me to that time! This time I knew nothing!"'),
      S('mojie','……他说的是真的。','…He\'s telling the truth.'),
      FLAG('d_power_wrong')]],
    ['「是理查德先生自己。他的手机，就卡在这把伞里——关完灯，还没来得及收。」','"Mr. Richard himself. His phone was wedged in this umbrella. He cut the lights and never got the chance to put it away."',2,[
      N('你拿起评委席旁边的黑伞，撑开。伞骨之间，空着一个手机大小的位置。','You pick up the black umbrella by the judges\' table and open it. Between the ribs is an empty, phone-sized gap.'),
      WHO('kevin'),
      IF('kevin_log',[S('kevin','操作日志也对得上：23:50:02，登录设备，「R 的手机」。','The activity log matches: 11:50:02 PM, device: "R\'s phone."')]),
      WHO('mojie'),
      S('mojie','……对。灯是他关的。这是计划好的。','…Yes. He turned off the lights. It was planned.'),
      FLAG('d_power')],'clue:雨伞里的手机'],
    ['「是理查德先生自己。流程单上写着——23:50，【特别环节】，全暗十秒。」','"Mr. Richard himself. The run sheet says it: 11:50 PM, Special Segment, ten seconds of darkness."',2,[
      S('mojie','（她沉默了几秒，然后把流程单的最后一页，摊在了桌子上）……对。灯是计划好的。是他亲手关的。','(After a few seconds\' silence she lays the run sheet\'s last page on the table) …Yes. The darkness was planned. He switched it off himself.'),
      IF('kevin_guilt',[WHO('kevin'),S('kevin','……灯没回来，是因为我的安全规则拦掉了恢复脚本。对不起。','…The lights didn\'t come back because my security rule blocked the restore script. I\'m sorry.'),WHO('mojie')]),
      FLAG('d_power')],'clue:特别环节'],
    ['「……我还不确定。」','"…I\'m not sure yet."',0,[
      S('mojie','（她看了一眼手机）继续。','(She glances at her phone) Keep going.')]]),
  N('（第二件事——也是最重要的一件：奖杯，在谁手里？）','(Second, and most important: who has the trophy?)'),
  IF('defend_chen',[N('小陈站在通道口，攥紧了拳头。你说过，你会把真相带回来。','Xiao Chen stands at the passage entrance, fists clenched. You said you\'d bring back the truth.')]),
  CT(25,[N('（你张了张嘴，却没能说出一个名字。）','(You open your mouth, but no name comes out.)'),S('mojie','（她的手指，按在了手机上）……那就只剩四十分钟了。','(Her finger rests on her phone) …Then there are forty minutes left.'),FLAG('abstain')],
    ['「是小陈。名牌就在奖杯旁边，他离得最近。」','"Xiao Chen. His badge was right beside the trophy. He was closest."',-5,[
      FLAG('accused_wrong'),FLAG('accused_chen')]],
    ['「是天哥。灯灭的时候，有人看见金光。」','"Brother Tian. Someone saw a gold flash when the lights died."',-3,[
      FLAG('accused_wrong'),FLAG('accused_tian')]],
    ['「是 KC。她恨理查德，所有人都知道。」','"KC. She hates Richard. Everyone knows it."',-3,[
      FLAG('accused_wrong'),FLAG('accused_kc')]],
    ['「是酒哥。黑暗里拿走奖杯的那只手，系着一根褪色的红绳。」','"Brother Jiu. The hand that took the trophy in the dark wore a faded red string."',3,[
      N('大厅里一下子安静了。','The lounge goes dead silent.'),
      IF('ya_told',[N('芽把速写本举了起来。整页灰色的铅笔线里，只有那一点红。','Ya holds up her sketchbook. In a page of grey pencil, that one touch of red.')]),
      FLAG('d_who')],'clue:红绳'],
    ['「是酒哥。在黑暗里经过吧台的那个人，身上有一股冬瓜茶味。那天晚上，只有他熬了冬瓜茶。」','"Brother Jiu. Whoever passed the bar in the dark smelled of winter melon tea. Only he brewed winter melon tea that night."',3,[
      N('KC 在吧台尽头，轻轻地「嗯」了一声。','At the end of the bar, KC gives a soft "mm."'),
      FLAG('d_who')],'clue:冬瓜茶味'],
    ['「是酒哥。他拽着理查德从后门出去，去了老街——那天凌晨，「九号」亮灯了。」','"Brother Jiu. He dragged Richard out the back door to the old street. That night, Number Nine\'s lights came on."',3,[
      IF('luoyu_told',[S('luoyu','（从沙发后面探出头）我作证！我亲眼看见的！','(Popping up from behind a sofa) I\'m a witness! I saw it with my own eyes!')]),
      FLAG('d_who')],['clue:后门','clue:九号亮灯']],
    ['「……现在，我还不能指认任何人。」','"…I can\'t name anyone yet."',0,[
      S('mojie','（她的手指，按在了手机上）……那就只剩四十分钟了。','(Her finger rests on her phone) …Then there are forty minutes left.'),
      FLAG('abstain')]]),
  IF('accused_wrong',[
    IF('accused_chen',[
      WHO('xiaochen'),
      N('小陈没有说话。他走回员工休息室，把柜子里的东西，一件一件，重新装进了纸箱。','Xiao Chen says nothing. He walks back to the staff room and packs his things into the box again, one by one.'),
      IF('defend_chen',[S('xiaochen','……三个小时前，你站在我和经理中间。','…Three hours ago you stood between me and the manager.'),S('xiaochen','我还以为，你是信我的。','I thought you believed in me.')]),
      N('他抱着纸箱，从后门走了。门关上的声音很轻。','He carries the box out the back door. It closes very quietly.')]),
    IF('accused_tian',[
      WHO('tiange'),
      S('tiange','（他从墙边站直，咳了两声）……兄弟。我还以为，你是这条街上最会看人的那个。','(He straightens off the wall and coughs twice) …Brother. I thought you were the best judge of people on this street.'),
      N('他把脖子上的金链子摘下来，放在吧台上，转身走了。Ace 想追，被他挥手拦住了。','He takes off the gold chain, lays it on the bar and walks out. Ace starts after him; he waves him back.')]),
    IF('accused_kc',[
      WHO('kc'),
      S('kc','（她看着你，很久。然后，笑了一下）……行。','(She looks at you for a long time. Then gives a small laugh) …Fine.'),
      S('kc','我恨他，所以就是我。你跟当年那些人，没什么两样。','I hate him, so it must be me. You\'re no different from the people back then.'),
      N('她把那张写着「你是对手」的名片，从酒柜的格子里抽出来，撕成两半，放在吧台上。','She pulls her card, the one that says "Consider yourself a rival," out of the shelf cubby, tears it in two, and lays it on the bar.')]),
    WHO('mojie'),
    S('mojie','（她看着空掉的门口，什么都没说，只是把手机拿了起来）','(She looks at the empty doorway, says nothing, and picks up her phone.)')]),
  IF('d_who',[
    N('（最后一件事：他为什么要这么做？）','(Last question: why did he do it?)'),
    C(['「为了奖杯。……镀金的，说不定能卖钱。」','"For the trophy. …It\'s gold-plated. Maybe he could sell it."',-3,[
        S('mojie','……你见过酒哥为钱做过什么事吗？','…Have you ever seen Brother Jiu do anything for money?'),
        FLAG('d_why_wrong')]],
      ['「为了报复。六年前，理查德是「九号」那栋楼的业主，是他签字涨的房租。」','"Revenge. Six years ago Richard was the landlord of Number Nine\'s building. He signed the rent increase."',1,[
        N('人群一阵骚动。KC 在吧台尽头，攥紧了杯子。','A murmur goes through the crowd. At the end of the bar, KC tightens her grip on her glass.'),
        S('mojie','……这是一半。可如果是报复，他为什么要带着理查德一起走？','…That\'s half of it. But if it was revenge, why take Richard with him?'),
        FLAG('d_why_half')],'clue:业主'],
      ['「理查德想在今晚的特别环节，当着所有人的面道歉，把奖杯里那把「九号」的钥匙还给他。酒哥不要施舍——更不要当着所有人的面被"还"。所以他在黑暗里，把奖杯和人一起带走了：要说什么，回「九号」门口说。」','"Richard planned to use tonight\'s special segment to apologise in front of everyone and hand back the key to Number Nine hidden in the trophy. Brother Jiu didn\'t want charity, least of all being "repaid" in front of a crowd. So in the dark he took the trophy and the man together: whatever needed saying, it would be said at Number Nine\'s door."',4,[
        FLAG('d_why')],['clue:业主','clue:钥匙']],
      ['「理查德把「九号」买了回来，还拟了一份赠与合同，就差酒哥签字。他想在台上把店还给他。可酒哥那个人，最受不了的就是当着所有人的面被同情。」','"Richard bought Number Nine back and drafted a deed of gift, waiting only for Brother Jiu\'s signature. He wanted to return the shop on stage. But what Brother Jiu can stand least is being pitied in front of everyone."',4,[
        FLAG('d_why')],'clue:赠与合同'],
      ['「……我不知道。」','"…I don\'t know."',0,[
        S('mojie','……至少你知道是谁。','…At least you know who.')]]),
    IF('d_why',[
      N('大厅里很久没有人说话。','For a long time, no one in the lounge speaks.'),
      WHO('panda'),
      S('panda','（他攥着他舅舅的手机，声音很小）……舅舅的致辞稿里，就是这么写的。「今晚，我把「九号」还给你。」','(Clutching his uncle\'s phone, voice small) …That\'s exactly what Uncle wrote in his speech. "Tonight, I\'m giving Number Nine back to you."'),
      WHO('kc'),
      S('kc','（她低着头，很久，才开口）……那个倔老头。','(Head bowed, she speaks only after a long time) …That stubborn old man.'),
      WHO('mojie')]),
    S('mojie','（她看了一眼手机。23:57）……可他们人呢？','(She glances at her phone. 11:57.) …So where are they?')]),
  IF('abstain',[
    N('23:57。没有人再说话。只有大电视上的时钟，一秒一秒地跳。','11:57 PM. No one says another word. Only the clock on the big TV, ticking second by second.')])]},

 {who:'jiuge',steps:[
  CARD('— 23:59 —','— 11:59 PM —'),
  IF('accused_wrong',[
    N('莫姐的手指，按在了拨号键上。','Sister Mo\'s finger presses the dial button.'),
    N('就在这时，后门开了。','And just then, the back door opens.')],
   [IF('abstain',[
      N('莫姐看了你一眼，按下了拨号键。「喂，你好，我要报案——」','Sister Mo gives you one look and presses dial. "Hello, I\'d like to report—"'),
      N('后门开了。','The back door opens.')],
     [N('莫姐的手指，停在拨号键上方。','Sister Mo\'s finger hovers over the dial button.'),
      IF('luoyu_helps',[N('后门「吱呀」一声——洛羽不知道什么时候溜了出去，这会儿正拽着一个人的袖子，倒退着走进来：「找到了！我就说他们在老街！」','The back door creaks. At some point Luo Yu slipped out, and now he\'s walking in backwards, tugging someone by the sleeve: "Found them! I told you they were on the old street!"')],
        [N('后门开了。','The back door opens.')])])]),
  N('酒哥走了进来。他还穿着那件很久没穿过的衬衫，皱得不成样子。怀里抱着一个用旧围裙包着的东西。','Brother Jiu walks in. He\'s still in that long-unworn shirt, now hopelessly creased. In his arms is something wrapped in an old apron.'),
  N('理查德跟在他后面，西装的袖口撕了一道口子，走路有点瘸。','Richard follows, his suit cuff torn, walking with a slight limp.'),
  S('jiuge','（他看了一圈满屋子的人，挠了挠头）……这么热闹？','(He looks around at the packed room and scratches his head) …Quite the crowd.'),
  N('他把围裙解开。镀金的话筒奖杯，完好无损。','He unwraps the apron. The gold microphone trophy, completely intact.'),
  S('jiuge','借走两天。连本带利，还给你们。','Borrowed for two days. Returned with interest.'),
  IF('accused_wrong',[
    S('jiuge','（他的目光扫过大厅，停在空出来的那个位置上）……怎么少了一个人？','(His eyes sweep the room and stop at the empty spot) …Why is someone missing?'),
    N('没有人回答。','No one answers.'),
    S('jiuge','……（他看向你，很久）孩子。凶手往往是最不像凶手的那个——可最像凶手的那个，也不一定就是凶手。','…(He looks at you for a long time) Kid. The killer\'s usually the one who looks least like one. But the one who looks most like one isn\'t always the killer either.')]),
  IF('d_who',[
    S('jiuge','（他看着你，笑了）我在后门外面听了一会儿。……推理得不错。','(He looks at you and smiles) I listened outside the back door for a bit. …Not bad, detective.'),
    IF('d_why',[S('jiuge','连我为什么这么干，你都猜到了。……行，你比我自己还懂我。','You even figured out why I did it. …Huh. You understand me better than I do.')]),
    IF('side_jiu',[S('jiuge','上次谜案游戏，你替我说过话。这次，你没替我说话——你说的是实话。这更好。','Last murder game, you stood up for me. This time you didn\'t stand up for me. You told the truth. That\'s better.')])]),
  WHO('richard'),
  S('richard','（他走到评委席，对着莫姐和所有人，深深鞠了一躬）给各位添麻烦了。','(He walks to the judges\' table and bows deeply to Sister Mo and to everyone) My apologies for the trouble.'),
  S('richard','我本来准备了一篇致辞。在台上，当着所有人的面，向这个人道歉，把一间铺子还给他。','I\'d prepared a speech. On stage, in front of everyone, to apologise to this man and give him back a shop.'),
  S('richard','他在黑暗里抓住我的胳膊，说：「你要是敢在台上念，我这辈子都不跟你说话。」','In the dark, he grabbed my arm and said, "If you dare read that on stage, I\'ll never speak to you again as long as I live."'),
  S('richard','然后我们在「九号」的门口，坐了一整夜。……我说了六年没说出口的话。他骂了我六年没骂出口的话。','Then we sat outside Number Nine all night. …I said what I hadn\'t managed to say for six years. He cursed me with everything he\'d held back for six years.'),
  WHO('jiuge'),
  S('jiuge','（他走到吧台前，像第一天那样，用指节敲了两下台面）','(He comes to the bar and, just like the first night, raps the counter twice with his knuckles.)'),
  S('jiuge','孩子。给我们俩，调最后一杯。','Kid. Make the two of us one last drink.'),
  IF('found_book',[S('jiuge','本子你看过了吧。最后一页，我一直没写。……你来写。','You\'ve read the book, right? I never wrote the last page. …You write it.')]),
  S('jiuge','【甜一点】，有【茶】。……别太烈。老家伙膝盖不好，我酒量也差。','【A bit sweet】, with 【tea】. …Nothing strong. The old man\'s knees are bad, and I can\'t hold my drink.'),
  N('（第一天，他也是这么点的。可今晚，你不用猜他的老配方了。——你知道他真正爱的是什么。）','(On the first night he ordered the same way. But tonight you don\'t need to guess his old recipe. You know what he really loves.)'),
  MX({accept:['osmanthus_oolong','jasmine_gin','matcha_highball','jager_tea','apple_highball'],best:'wm_whisky',want:['茶','甜','温和'],avoid:['烈','苦','酸'],str:'low'},
   [S('jiuge','（喝了一口，把杯子推给理查德）……你尝尝。','(Sips, then slides the glass to Richard) …Try it.'),
    WHO('richard'),
    S('richard','（他喝了一口，很久没有说话）……跟六年前，一模一样。','(He drinks and is silent a long while) …Exactly like six years ago.'),
    WHO('jiuge'),
    S('jiuge','不。比六年前好。','No. Better than six years ago.')],
   [S('jiuge','（喝了一口）嗯。还行。……差一点。','(Sips) Mm. Not bad. …Almost.'),
    S('jiuge','没事。差的那一点，以后慢慢补。','That\'s fine. The bit that\'s missing, you\'ll make up in time.')],
   [S('jiuge','（喝了一口，笑出了声）……跟你第一天一样烂。','(Sips and laughs out loud) …Just as bad as your first day.'),
    S('jiuge','也好。有些东西，得留着下次。','That\'s alright. Some things should be saved for next time.')],
   [S('jiuge','（一口下去，他整个人停住了）……桂花。','(One sip and he goes completely still) …Osmanthus.'),
    S('jiuge','「九号」门口那棵桂花。我妈种的。关店那年秋天，被房东……（他看了理查德一眼）……被砍了。','The osmanthus outside Number Nine. My mom planted it. The autumn the bar closed, the landlord… (he glances at Richard) …had it cut down.'),
    WHO('richard'),
    S('richard','（低声）……上个月，我在原来的位置，重新种了一棵。','(Quietly) …Last month I planted a new one in the same spot.'),
    WHO('jiuge'),
    N('酒哥没说话。他把袖子捋起来，看着手腕上那根褪色的红绳，看了很久。','Brother Jiu says nothing. He pushes up his sleeve and looks at the faded red string on his wrist for a long, long time.')]),
  IF('accused_wrong',[
    N('那天晚上，奖杯回来了，理查德回来了，歌王比赛有了结果。','That night, the trophy came back, Richard came back, and the contest got its result.'),
    IF('accused_chen',[N('只有小陈，没有回来。第二天，他的柜子空了。只在柜门内侧，留着一张贴纸：一支话筒，旁边写着「陈小」。','Only Xiao Chen didn\'t come back. The next day his locker was empty, except for a sticker inside the door: a microphone, and beside it, "Chen Xiao."')]),
    IF('accused_tian',[N('只有天哥，再也没有来过 Space。那条金链子，至今还挂在酒柜的格子里。','Only Brother Tian never set foot in Space again. That gold chain still hangs in one of the shelf cubbies.')]),
    IF('accused_kc',[N('只有 KC，再也没有推开过这扇门。隔壁「Pink Hour」的吧台后面，换了一个陌生的调酒师。','Only KC never pushed open this door again. Behind the bar at Pink Hour next door, there\'s a stranger now.')]),
    N('你后来常常想：凶手往往是最不像凶手的那个。可你那天晚上，指着的是最像的那个。','You often think about it afterwards: the killer is usually the one who looks least like one. That night, you pointed at the one who looked most like one.'),
    END('wrong_man','冤案','The Wrong Man')],
   [IF('!d_who',[
      N('可是电话已经打出去了。','But the call has already been made.'),
      N('那天晚上，来了两辆警车。赞助商连夜发了声明，撤回了全部赞助。第二天，Space 门口贴出了一张新的告示：「停业整顿」。','Two police cars came that night. The sponsors issued a statement overnight and pulled every cent. The next day, a new notice went up on Space\'s door: "Closed pending review."'),
      N('理查德把奖杯交给了警察，把所有责任都揽了过去。酒哥一句话都没说，只是在你的吧台上，放下了一把系着「9」字木牌的铜钥匙。','Richard handed the trophy to the police and took all the blame. Brother Jiu didn\'t say a word. He just set a brass key with a wooden "9" tag on your counter.'),
      S('jiuge','……等这边能开门了，去那边开吧。','…When this place can open again, go open that one.'),
      N('你关掉霓虹。黑色吧台上，倒映着最后一点紫光——跟第一天一样。只是这一次，不知道下一次亮起来，是什么时候。','You switch off the neon. The black counter holds the last of the purple glow, just like the first night. Only this time, you don\'t know when it will light up again.'),
      END('closing_time','打烊','Closing Time')],
     [IF(['d_why','kc_card',{aff:'kc',min:8}],[
        WHO('kc'),
        N('KC 从吧台尽头站了起来，走到酒哥面前。','KC rises from the end of the bar and walks up to Brother Jiu.'),
        S('kc','……你把配方本给了新来的，把我赶去了隔壁。','…You gave the recipe book to the new one, and you sent me next door.'),
        WHO('jiuge'),
        S('jiuge','（他挠了挠头）……我是怕你跟着我一起沉。','(Scratching his head) …I didn\'t want you to sink with me.'),
        WHO('kc'),
        S('kc','我没沉。我在隔壁站了六年，就等着有一天，能跟你打擂台。','I didn\'t sink. I stood next door for six years, waiting for the day I could take you on.'),
        S('kc','（她转向你）「九号」重开那天，吧台后面得有两个人。一个是你，一个是我。……别误会，我是来盯着你的。','(She turns to you) The day Number Nine reopens, there\'ll need to be two people behind the bar. You, and me. …Don\'t get the wrong idea. I\'m there to keep an eye on you.'),
        N('她说"别误会"的时候，耳朵是红的。','When she says "don\'t get the wrong idea," her ears are red.'),
        CARD('— 三个月后 · 老街 9 号 —','— Three months later · 9 Old Street —'),
        N('门口的桂花树还很小，可已经开了第一茬花。','The osmanthus tree out front is still small, but it has already bloomed for the first time.'),
        N('吧台后面站着两个人。一个摇壶用腰，一个总被另一个说"手腕太紧"。酒哥坐在客人那一侧，敲了两下台面。','Two people stand behind the bar. One shakes from the hips; the other keeps being told "your wrist is too stiff." Brother Jiu sits on the guest side and raps the counter twice.'),
        N('每周五，有一位穿西装的老先生准时推门进来，只点一杯冬瓜威士忌。','Every Friday, an old gentleman in a suit walks in right on time and orders one winter melon whiskey.'),
        END('rival','隔壁的对手','The Rival Next Door')],
       [IF(['d_why','d_power',{tier:'great'}],[
          WHO('jiuge'),
          S('jiuge','（他从围裙口袋里，摸出一把系着「9」字木牌的铜钥匙，放在吧台上）','(From the apron pocket he takes a brass key on a wooden "9" tag and lays it on the bar.)'),
          S('jiuge','合同我签了。……但我有个条件。','I signed the deed. …On one condition.'),
          S('jiuge','「九号」重开，周一到周四我站吧台。周五、周六——（他把钥匙推到你面前）归你。','When Number Nine reopens, I tend bar Monday to Thursday. Fridays and Saturdays (he pushes the key toward you) are yours.'),
          WHO('richard'),
          S('richard','（他从莫姐手里接过奖杯，走到台上）那么——迟到了两天的结果。','(He takes the trophy from Sister Mo and walks onto the stage) And now, two days late: the result.'),
          IF('chen_sang',[S('richard','今晚的歌王是——陈小。','Tonight\'s Karaoke King is: Chen Xiao.'),N('小陈站在员工通道口，愣住了。经理老周第一个鼓起了掌。','Xiao Chen freezes at the passage entrance. Old Zhou is the first to start clapping.')],
            [S('richard','今晚的歌王是——天哥。第四届。……也是最后一届。','Tonight\'s Karaoke King is Brother Tian. Fourth title. …And his last.'),N('天哥没有去接奖杯。他把它塞给了 Ace：「小子，明年你来拿。」','Brother Tian doesn\'t take the trophy. He shoves it at Ace: "Kid, next year you win it."')]),
          CARD('— 三个月后 · 老街 9 号 —','— Three months later · 9 Old Street —'),
          N('「九号」重新开张那天，整条老街都是桂花香。','The day Number Nine reopened, the whole old street smelled of osmanthus.'),
          N('菠萝包送来了一个菠萝形状的蛋糕。洛羽在门口发传单。Panda 开了直播，Kevin 修好了点单系统，向哥在墙上挂了一张律师执照的复印件，说是"镇店之宝"。','Pineapple Bun brought a pineapple-shaped cake. Luo Yu handed out flyers at the door. Panda went live, Kevin fixed the order system, and Xiang hung a photocopy of his law licence on the wall as "the house treasure."'),
          N('第一位客人，是一位穿西装的老先生。他用指节敲了两下吧台，说：「一杯冬瓜威士忌。」','The first guest was an old gentleman in a suit. He rapped the counter twice and said, "One winter melon whiskey."'),
          N('你接过酒哥递来的冰勺。','You take the ice scoop Brother Jiu hands you.'),
          N('（冰先下，酒后下，茶最后——别搅太狠。）','(Ice first, spirit next, tea last. Don\'t stir too hard.)'),
          END('nine_reopens','九号重开','Number Nine Reopens')],
         [WHO('jiuge'),
          S('jiuge','（他从围裙口袋里，摸出一把系着「9」字木牌的铜钥匙，放在吧台上，看了很久）','(He takes a brass key on a wooden "9" tag from the apron pocket, lays it on the bar and looks at it for a long time.)'),
          S('jiuge','合同，我没签。','I didn\'t sign the deed.'),
          S('jiuge','不是不原谅他。是我老了，站不动吧台了。「九号」该有新的主人——等你哪天觉得自己配得上，再来拿这把钥匙。','It\'s not that I don\'t forgive him. I\'m old. I can\'t stand behind a bar anymore. Number Nine needs a new owner. The day you think you\'re worthy, come take this key.'),
          IF('found_book',[S('jiuge','本子的最后一页，留给你写。写好了，再来找我。','The last page of the book is yours to write. When it\'s done, come find me.')]),
          N('第二天，酒哥坐上了回老家的火车。他说要回去看看那棵桂花的老根。','The next day Brother Jiu took the train back to his hometown. He said he wanted to see the old roots of that osmanthus tree.'),
          N('每周五，理查德依旧准时坐在你的吧台前，点一杯冬瓜威士忌。他总是留着旁边那张凳子，谁都不让坐。','Every Friday, Richard still sits at your bar right on time and orders a winter melon whiskey. He always keeps the stool beside him free, and lets no one take it.'),
          N('那把钥匙，挂在你的酒柜正中间的格子里。紫光照着它。你还在等，觉得自己配得上的那一天。','The key hangs in the centre cubby of your shelves, in the purple light. You\'re still waiting for the day you feel worthy of it.'),
          END('last_call','最后一杯','Last Call')])])])])]}
 ]},
// ===================== NIGHT 8 (side story) =====================
{title:['红唇通缉令','The Red-Lip Warrant'],
 preview:['——番外到此结束。她说过：欠你的那一杯，总有一天会回来还。','The side story ends here. She said the drink she owes you, she\'ll come back to repay one day.'],
 intro:[CARD('— 番外 · 第八夜 · 一周后 · 23:30 —','— Side Story · Night Eight · One week later · 11:30 PM —'),
        N('奖杯风波过去一周了。镀金话筒奖杯回到了酒柜正中间的格子里，底座下压着一张手写卡片：「借走两天，连本带利。」','A week has passed since the trophy affair. The gold microphone trophy is back in the centre cubby, a handwritten card tucked under its base: "Borrowed two days. Returned with interest."'),
        FX('rain'),
        N('今晚下着小雨。翔哥推门进来，一手拎着胶带，一手捏着一张 A4 纸。','A light rain tonight. Brother Xiang shoulders the door open, a roll of tape in one hand and a sheet of A4 in the other.'),
        S('xiangge','律师执照还没捂热，就被莫姐抓来兼保安队长。……喏，派出所门口有人在发，说沿街商户都贴一张。','My law licence isn\'t even warm and Sister Mo has me moonlighting as head of security. …Here. Someone was handing these out by the police station. Every shop on the street is meant to put one up.'),
        FX('flash'),
        CARD('悬赏通告 ·「红唇」','REWARD NOTICE · "Red Lips"'),
        N('纸上是几张监控截图拼出来的画像：齐肩黑发，【红唇】，黑色皮夹克，左耳一只金色大圈耳环——右耳空着。','The sheet shows a portrait pieced together from CCTV stills: shoulder-length black hair, 【red lips】, a black leather jacket, one big gold hoop in her left ear. The right ear is bare.'),
        N('「本月 14 日夜，鸿运拍卖行预展失窃红宝石一枚，名『【鸽血红】』。提供线索者，悬赏二十万元。」','"On the night of the 14th, one ruby, the 【Pigeon\'s Blood】, was stolen from the Hongyun Auction House preview. Reward for information: 200,000 yuan."'),
        N('（14 号……不就是歌王比赛、停电的那天晚上？）','(The 14th… wasn\'t that the night of the contest? The night of the blackout?)'),
        C(['「二十万？够开半家「九号」了。」','"Two hundred grand? That\'s half a Number Nine."',0,[
            S('xiangge','（他瞪了你一眼）别打歪主意。……不过说真的，比警方悬赏还大方，有点怪。','(He glares at you) Don\'t get ideas. …Honestly, though, that\'s more generous than any police reward. Bit odd.')]],
          ['「贴门口吧。别贴吧台，影响客人喝酒。」','"Put it by the door. Not on the bar, it\'ll put people off their drinks."',1,[
            S('xiangge','讲究。行。','Fussy. Fine.')]],
          ['（盯着画像上那只空着的右耳）','(Stare at the bare right ear in the portrait)',0,[
            N('（左耳戴着，右耳没有。……是掉了，还是故意只戴一只？）','(Left ear, yes. Right ear, nothing. Lost it, or does she wear just one on purpose?)'),
            FLAG('saw_ear')]]),
        N('翔哥把通告贴在门边，用掌根把四个角一个个压平。','Brother Xiang tapes the notice beside the door and presses each corner flat with the heel of his hand.'),
        N('雨越下越大。快打烊的时候，门上的风铃响了。','The rain gets heavier. Just before closing, the bell over the door chimes.')],
 scenes:[
 {who:'ella',steps:[
  CARD('— 23:58 · 打烊前两分钟 —','— 11:58 PM · Two minutes to closing —'),
  N('一个女人站在门口，甩了甩黑色皮夹克上的雨水。里面是一件红色吊带，嘴唇的颜色和它一模一样。','A woman stands in the doorway, shaking rain off a black leather jacket. Underneath is a red top, and her lips are exactly the same shade.'),
  N('她在门边那张通告前停了一秒。然后，笑了。','She pauses for one second in front of the notice by the door. Then she smiles.'),
  S('ella','画得不太像。本人好看多了，对吧？','Bad likeness. I\'m much better looking in person, wouldn\'t you say?'),
  N('她坐上吧台正中间那张凳子——正对着酒柜中间那格的奖杯。左耳的金圈晃了晃，右耳空着。','She takes the stool dead centre, right in front of the trophy in the middle cubby. The gold hoop in her left ear swings. Her right ear is bare.'),
  EMO('❗'),
  C(['（指了指门口）「你就是……」','(Nod toward the door) "You\'re the…"',0,[
      S('ella','（她竖起一根手指，按在你嘴唇前面）嘘——说出来，就不好玩了。','(She lifts one finger and holds it just in front of your lips) Shh. Say it out loud and it stops being fun.'),
      EMO('♪')]],
    ['「打烊前最后一位客人。想喝点什么？」','"Last guest before closing. What can I get you?"',2,[
      S('ella','我喜欢不多问的人。……也喜欢眼睛不乱飘的人。','I like people who don\'t ask questions. …And people whose eyes don\'t wander.')]],
    ['「通告上说，你偷了一颗红宝石。」','"The notice says you stole a ruby."',-1,[
      S('ella','偷？（她托着下巴）我管这叫「物归原主」。','Stole? (Chin on her hand) I call it "returning to the rightful owner."'),
      FLAG('ella_claim')]],
    ['「你的另一只耳环……是丢在这儿了吧？」','"Your other earring… you lost it here, didn\'t you?"',2,[
      S('ella','（她下意识摸了摸右耳，愣了一下，然后笑出了声）……眼睛挺尖嘛，调酒师。','(Her hand goes to her right ear before she can stop it. A beat, then she laughs) …Sharp eyes, bartender.'),
      FLAG('ella_ear')],'saw_ear']),
  S('ella','叫我艾辣。辣椒的辣。','Call me Ella. Like the chilli.'),
  S('ella','放心，我只偷东西，不碰人命。……也不赖酒钱。','Relax. I steal things. I don\'t touch lives. …And I don\'t skip out on a tab.'),
  S('ella','Dirty martini。（她托着下巴，慢悠悠地补了一句）……【Extra dirty】。','Dirty martini. (Chin in her hand, she adds slowly) …【Extra dirty】.'),
  S('ella','（看你愣住，她笑出了声）我说的是【橄榄盐水】多放点，调酒师。你脑子里在想什么？','(You freeze, and she laughs out loud) I mean 【extra olive brine】, bartender. What were you thinking?'),
  N('（烈，咸，不要甜，不要气泡。她说话的样子，像在挑一把刀。）','(Strong, salty, no sugar, no fizz. She orders the way someone picks out a knife.)'),
  MX({accept:['dirty_martini','dry_martini','michelada','margarita','caipirinha','baijiu_sour','whiskey_sour','penicillin'],best:'extra_dirty',want:['烈','咸'],avoid:['甜','奶香','气泡'],str:'high'},
   [S('ella','（她咬下签子上的橄榄，眯起眼睛）……够咸，够脏，够劲。','(She bites the olive off the pick and narrows her eyes) …Salty enough, dirty enough, strong enough.'),
    S('ella','跟我一样。','Just like me.'),
    AFF(1),FLAG('ella_trust1'),TIP(15)],
   [S('ella','凑合。……下次再脏一点，别害羞。','It\'ll do. …Dirtier next time. Don\'t be shy.')],
   [EMO('💢'),
    S('ella','……你往里面兑了什么？我说了，要够劲。','…What did you water this down with? I said strong.'),
    S('ella','（她把杯子推回来）算了。今晚本来就不是来喝酒的。','(She slides it back) Forget it. I didn\'t really come here to drink.')],
   [S('ella','（她喝了一口，整个人停住了）……苦的。','(She takes a sip and goes completely still) …Bitter.'),
    S('ella','我外婆以前在码头摆咖啡摊。煤炉子，铁皮壶，煮得又黑又苦，搬运工一口闷完，再去扛一百斤的麻袋。','My grandma used to run a coffee stall on the docks. Coal stove, tin pot, brewed black and bitter. The porters downed it in one and went back to hauling hundred-pound sacks.'),
    S('ella','（她转着杯子，没看你）……你怎么知道的？','(She turns the glass, not looking at you) …How did you know?'),
    AFF(2),FLAG('ella_trust1'),FLAG('ella_grandma')]),
  FX('flash'),
  N('车灯扫过玻璃门。一辆黑色轿车停在门口，没熄火。两个穿黑西装的男人下了车，其中一个，手里捏着同一张悬赏通告。','Headlights sweep across the glass door. A black sedan pulls up outside, engine running. Two men in black suits get out. One of them holds a copy of the same reward notice.'),
  S('ella','（她没回头，只是从酒柜的镜子里瞥了一眼）……冯涛。宋鸿养的狗。鼻子倒是灵。','(She doesn\'t turn, just glances at them in the mirror behind the shelves) …Feng Tao. Song Hong\'s guard dog. Good nose, I\'ll give him that.'),
  CT(6,[N('你还没反应过来，她已经撑着吧台翻了进来，像一只猫一样缩进了水槽下面的柜子里。','Before you can react she\'s vaulted the counter and folded herself into the cabinet under the sink, quick as a cat.'),
        S('ella','（柜门里传来很小的声音）……你反应太慢了，调酒师。','(A tiny voice from behind the cabinet door) …You\'re too slow, bartender.'),
        AFF(-1),FLAG('ella_hidden')],
    ['「蹲下。吧台底下。」','"Get down. Under the bar."',2,[
      N('她一秒都没犹豫，翻进吧台，贴着你的脚边蹲了下去。皮夹克上的雨水，蹭湿了你的裤腿。','She doesn\'t hesitate for a second: over the counter and crouched at your feet. The rain on her jacket soaks into your trouser leg.'),
      S('ella','（压低声音）……你这个人，挺有意思。','(Under her breath) …You\'re an interesting one.'),
      FLAG('ella_hidden'),FLAG('covered')]],
    ['（翻过门口那张通告，挂上「打烊」牌）','(Flip the notice face-down and hang up the "Closed" sign)',1,[
      N('你走过去，「咔哒」一声锁上门，把「打烊」的牌子挂在了玻璃上。冯涛隔着玻璃看了你一眼，没敲门——但也没走。','You cross over, lock the door with a click and hang the "Closed" sign on the glass. Feng Tao looks at you through it. He doesn\'t knock. He doesn\'t leave, either.'),
      FLAG('closed_sign'),FLAG('covered')]],
    ['（抬手，朝门口那两个人招了招）','(Raise a hand and wave the two men over)',-2,[
      N('你的手刚抬起来，手腕就被一只冰凉的手按住了。','Your hand is barely up when a cold hand pins your wrist.'),
      S('ella','你要把我交出去，随时都可以。但先听我说一句——那颗石头，本来就不是他的。','You can hand me over any time you like. But hear one thing first: that stone was never his.'),
      N('说完，她松开手，闪进了女洗手间。','Then she lets go and slips into the ladies\' room.'),
      FLAG('ella_doubt')]]),
  S('ella','（声音很轻）我不是来躲的。我是来拿东西的。','(Very quietly) I didn\'t come here to hide. I came to collect something.'),
  S('ella','14 号那天晚上，冯涛的人追了我三条街。我一头扎进你们店，正好赶上停电。','On the night of the 14th, Feng Tao\'s men chased me three streets. I ducked into your bar just as the lights went out.'),
  IF('heard_trophy',[
    S('ella','黑暗里，你是不是听见「叮当」一声？……那是我。','In the dark, did you hear a little "clink"? …That was me.'),
    N('（那一声「叮当」。你一直以为，是奖杯被人拿走时碰到了什么。）','(That little clink. You always thought it was the trophy knocking something as it was taken.)')]),
  S('ella','（她的视线，越过你的肩膀，落在酒柜正中间那格）我把它藏进了那个奖杯的底座。','(Her eyes go past your shoulder to the centre cubby) I hid it in the base of that trophy.'),
  N('（镀金话筒奖杯在紫光里，安安静静地立着。底座是空心的。所有人都知道。）','(The gold microphone trophy stands quietly in the purple light. Its base is hollow. Everyone knows that by now.)')]},

 {who:'kevin',steps:[
  CARD('— 00:20 —','— 12:20 AM —'),
  N('Kevin 抱着笔记本电脑，从办公室一路小跑出来，眼镜都跑歪了。','Kevin jogs out of the office clutching his laptop, glasses knocked crooked.'),
  S('kevin','门口那辆黑车，在监控里停了二十分钟了。还有……（他看见吧台后面的艾辣，整个人僵住）……啊。','That black car has been on the door camera for twenty minutes. And also… (he spots Ella behind the bar and freezes) …oh.'),
  WHO('ella'),
  S('ella','（朝他晃了晃手指）嗨，小眼镜。','(Wiggling her fingers at him) Hi there, Specs.'),
  WHO('kevin'),
  S('kevin','……（他推了推眼镜，推了三下）我、我上次停电以后，给吧台加了一个【红外录像】。黑着灯也能拍。','…(He pushes his glasses up. Three times.) A-after the blackout, I added an 【infrared camera】 over the bar. It records even with the lights off.'),
  S('kevin','14 号 23:50:04，有个人趴在吧台上，手伸进了奖杯底座。只戴一只耳环。……23:50:07，另一只手，把整个奖杯拿走了。手腕上，系着红绳。','The 14th, 11:50:04 PM, someone leaning over the bar with a hand inside the trophy base. One earring. …At 11:50:07, another hand takes the whole trophy. There\'s a red string on that wrist.'),
  N('（三秒。她刚把东西塞进去，酒哥就把奖杯抱走了。那颗石头，跟着「九号」的故事，在外面过了两天。）','(Three seconds. She\'d barely slipped it in when Brother Jiu carried the trophy off. That stone spent two days out there, riding along with Number Nine\'s story.)'),
  C(['「Kevin，帮我查查门口那张通告。」','"Kevin, look into that notice by the door for me."',1,[
      N('Kevin 用手机扫了通告角落的二维码，眉头越皱越紧。','Kevin scans the QR code in the notice\'s corner with his phone, and his frown deepens.'),
      S('kevin','……不对。二维码跳的不是警方的页面，是鸿运拍卖行的私人网页。我刚问了在派出所实习的同学——这个案子，根本没有立案。','…That\'s wrong. The QR code doesn\'t go to a police page. It goes to a private Hongyun Auction House site. I just asked a classmate interning at the station: there\'s no case filed at all.'),
      S('kevin','这是一张【私人悬赏】。','It\'s a 【private bounty】.'),
      FLAG('knows_bounty')]],
    ['「门口那辆车，能拍到车牌吗？」','"Can you get the plate on that car?"',1,[
      S('kevin','（他敲了几下键盘）拍到了。……这辆车上个月在我们后巷停过三次，每次都是凌晨。','(A few keystrokes) Got it. …That car parked in our back alley three times last month. Always after midnight.'),
      FLAG('plate')]],
    ['「录像里那只红绳的手，别给任何人看。」','"The hand with the red string: don\'t show that to anyone."',2,[
      S('kevin','（他愣了一下，然后用力点头）……明白。酒哥那份，我已经剪掉了。','(A pause, then a firm nod) …Got it. I\'ve already cut Brother Jiu\'s part.'),
      FLAG('jiu_protected')]]),
  WHO('ella'),
  IF('knows_bounty',[
    S('ella','（她冷笑了一声）他当然不敢报警。那颗石头是走私进来的。报了警，第一个要查的，就是他自己的保险柜。','(A cold laugh) Of course he won\'t call the police. That stone was smuggled in. Report it, and the first thing they\'d search is his own safe.')],
   [S('ella','（她看着门口那辆车）二十万买一个女人的下落。……宋鸿什么时候这么大方了。','(Watching the car outside) Two hundred grand for one woman\'s whereabouts. …Since when is Song Hong that generous.')]),
  WHO('kevin'),
  S('kevin','那……这段红外录像，怎么办？','So… what do we do with this infrared footage?'),
  C(['「删了。」','"Delete it."',-1,[
      S('kevin','……删监控是违法的。（他的手停在删除键上，停了很久，最后按了下去）……就这一次。','…Deleting security footage is illegal. (His finger hovers over delete for a long time, then presses) …Just this once.'),
      WHO('ella'),AFF(1),WHO('kevin'),
      FLAG('footage_deleted')]],
    ['「留着。谁都别给，先听她说完。」','"Keep it. Don\'t give it to anyone. Let\'s hear her out first."',1,[
      S('kevin','好。加密，放我自己硬盘里。','Okay. Encrypted, on my own drive.'),
      FLAG('footage_kept')]],
    ['「拷一份给翔哥。他是律师，他知道怎么用。」','"Copy it for Brother Xiang. He\'s a lawyer. He\'ll know what to do with it."',1,[
      S('kevin','……对哦。连门口那辆车，一起打包。','…Right. I\'ll bundle the car footage in too.'),
      FLAG('footage_xiang')]]),
  S('kevin','今晚我守着监控不睡了。能给我来一杯【提神】的吗？【咖啡】的，【别酸】。','I\'m staying up on the cameras tonight. Can I get something to 【keep me awake】? 【Coffee】, 【nothing sour】.'),
  MX({accept:['white_russian','b52','choc_martini'],best:'espresso_martini',want:['咖啡'],avoid:['酸','气泡'],str:'mid'},
   [S('kevin','（喝了一口，眼睛一下子亮了）……醒了。门口那辆车掉个头，我都看得见。','(One sip and his eyes light up) …Wide awake. If that car so much as turns around, I\'ll see it.'),
    IF('!knows_bounty',[
      S('kevin','对了，我顺手扫了一下门口通告上的二维码……那不是警方的，是拍卖行自己发的【私人悬赏】。派出所根本没立案。','Oh, and I scanned the QR code on the door notice while I was at it… It\'s not the police. It\'s a 【private bounty】 the auction house put out themselves. There\'s no case filed.'),
      FLAG('knows_bounty')]),
    FLAG('kevin_watch')],
   [S('kevin','嗯，够用。谢谢。','Mm, that\'ll do. Thanks.')],
   [S('kevin','（喝了一口，打了个哈欠）……好像更困了。','(Sips, then yawns) …I think I\'m sleepier now.'),
    EMO('💤')],
   [S('kevin','（喝了一口，小声说）……甜的，还有奶。Panda 每次给我泡咖啡，都偷偷这么放。','(Sips, quietly) …Sweet, and milky. That\'s how Panda always sneaks it into my coffee.'),
    S('kevin','我跟他说过一百遍我只喝黑的。……其实我一直知道。','I\'ve told him a hundred times I only drink it black. …I always knew.'),
    FLAG('kevin_watch'),TIP(10)])]},

 {who:'xiangge',steps:[
  CARD('— 00:50 —','— 12:50 AM —'),
  FX('shake'),
  N('「砰、砰、砰。」玻璃门被拍得直晃。','Bang. Bang. Bang. The glass door rattles in its frame.'),
  N('冯涛站在门外，举着那张悬赏通告，另一只手里，是一沓扎好的现金。','Feng Tao stands outside holding the reward notice up, and in his other hand, a banded stack of cash.'),
  N('翔哥把门拉开一条缝，用肩膀顶着。','Brother Xiang opens the door a crack and braces it with his shoulder.'),
  N('「兄弟，有人看见她进了这条街。让我们进去看一眼，这些，算线索费。」','"Pal, someone saw her come down this street. Let us take a look inside, and this is yours. Call it a tip-off fee."'),
  S('xiangge','（他没回头，声音压得很低）……老板，你说了算。','(Without turning, voice low) …Your call, boss.'),
  CT(8,[N('你还在犹豫，冯涛已经把门推开了。翔哥拦了一下，没拦住。','While you hesitate, Feng Tao shoves the door open. Brother Xiang tries to block him and fails.'),
        FLAG('men_inside')],
    ['「这张悬赏是私人发的，派出所没立案。他们没有任何权利搜一家店。」','"That bounty is private. No police case exists. They have no right to search any shop."',3,[
      S('xiangge','（他眼睛一亮，转回去，整个人好像高了五公分）听见了？私人悬赏，没有搜查权。','(His eyes light up. He turns back, suddenly about two inches taller) Hear that? A private bounty carries no right of search.'),
      S('xiangge','你再往前一步，就是非法侵入。要我现在报警吗？顺便请警察问问——那颗石头，是怎么进的海关？','One more step and it\'s trespass. Want me to call the police right now? They could ask, while they\'re here, how that stone got through customs.'),
      N('冯涛盯着翔哥看了三秒，把钱收回了口袋。黑车开走了。','Feng Tao stares at Brother Xiang for three seconds, then pockets the cash. The black car pulls away.'),
      FLAG('door_held')],'clue:私人悬赏'],
    ['「打烊了。明天请早。」','"We\'re closed. Come back tomorrow."',1,[
      N('冯涛往前挤了半步，翔哥一步不让，用胸口把他顶了回去。','Feng Tao pushes half a step forward. Brother Xiang doesn\'t give an inch and chest-bumps him back out.'),
      N('门关上了。可黑车只是挪到了街对面，车灯一直亮着。','The door shuts. But the black car only moves across the street, headlights still on.'),
      FLAG('door_half')]],
    ['「让他们进来看吧。我们没什么好藏的。」','"Let them look. We\'ve got nothing to hide."',-2,[
      FLAG('men_inside')]]),
  IF('men_inside',[
    N('两个人在大厅里转了一圈，翻了沙发，推开了每一间包厢的门。','The two men circle the lounge, flip sofa cushions, push open every karaoke room.'),
    IF('ella_hidden',[
      N('冯涛走到吧台前，皮鞋尖停在离水槽柜门不到一拳的地方。你听见柜子里，有人屏住了呼吸。','Feng Tao comes to the bar, the toe of his shoe stopping less than a fist from the cabinet door. Inside, you hear someone hold their breath.')],
     [N('冯涛敲了敲女洗手间的门。里面传来水声，还有一句不耐烦的「有人！」——声音粗得像个大叔。','Feng Tao knocks on the ladies\' room door. Running water, then an irritated "Occupied!" in a voice as gruff as an old man\'s.')]),
    N('他什么都没找到。走之前，他抬头看了一眼酒柜正中间的奖杯，掏出手机，拍了一张照。','He finds nothing. On his way out, he looks up at the trophy in the centre cubby, takes out his phone and snaps a picture.'),
    FLAG('trophy_seen'),
    N('（……他也知道。）','(…He knows too.)')]),
  S('xiangge','（他锁好门，转过身，抱着胳膊看着你）……我不瞎。','(He locks the door, turns around and folds his arms) …I\'m not blind.'),
  S('xiangge','门口那张纸上的人，现在就在我们店里吧？','The woman on that notice is in our bar right now, isn\'t she?'),
  C(['「是。我想先听她把话说完。」','"Yes. I want to hear her out first."',2,[
      S('xiangge','（他盯了你很久）……行。我当没看见——就到天亮。','(He stares at you a long time) …Fine. I didn\'t see anything. Until sunrise.'),
      S('xiangge','天亮以后，我是律师。你也得是个讲道理的人。','After sunrise, I\'m a lawyer. And you\'d better be someone who listens to reason.'),
      FLAG('xiang_ok')]],
    ['「你看错了。」','"You\'re seeing things."',-1,[
      S('xiangge','兄弟，我考了三次律考。说谎的人什么样，我闭着眼都认得。','Brother, I sat the bar exam three times. I can spot a liar with my eyes shut.'),
      S('xiangge','……算了。今晚我只管门。别的，我不管。','…Whatever. Tonight I\'m only minding the door. Nothing else.')]]),
  S('xiangge','给我来一杯。我还得守门，【别太烈】。要【有气泡】的，【带点辣】的，提神。','Pour me one. I\'m still on the door, so 【nothing too strong】. 【Something fizzy】, 【with a bit of a kick】, to keep me sharp.'),
  MX({accept:['jp_highball','gin_tonic','shirley','michelada'],best:'moscow_mule',want:['气泡','辛辣'],avoid:['甜','奶香'],str:'low'},
   [S('xiangge','（一口下去，长长地「哈」了一声）……姜够冲。这下谁来，我都顶得住。','(One gulp and a long "hah") …Proper ginger kick. Now I can hold that door against anyone.'),
    FLAG('xiang_guard')],
   [S('xiangge','嗯，能喝。','Mm. Drinkable.')],
   [S('xiangge','（喝了一口就皱眉）……甜了吧唧的。我是守门的，不是来过生日的。','(One sip and a frown) …Sickly sweet. I\'m guarding a door, not attending a birthday party.')],
   [S('xiangge','（一口下去，他愣住了）……咖啡味？','(One sip and he freezes) …Coffee?'),
    S('xiangge','考第三次律考那一周，我每天晚上就靠这个味道撑着。……你这是在提醒我，别忘了自己是干什么的。','The week of my third bar exam, this taste is what kept me going every night. …You\'re reminding me what I\'m actually here for.'),
    FLAG('xiang_guard'),FLAG('xiang_ok')])]},

 {who:'ella',steps:[
  CARD('— 01:40 —','— 1:40 AM —'),
  N('你搬来梯子，把镀金话筒奖杯从酒柜正中间那格取了下来。比想象中沉。','You fetch the stepladder and lift the gold microphone trophy down from the centre cubby. It\'s heavier than you expected.'),
  N('底座拧开的时候，「叮当」一声。','When you unscrew the base, there\'s a little "clink."'),
  FX('flash'),
  N('里面是一张折成小方块的餐巾纸。纸巾上，印着一个褪了色的「九」字。','Inside is a paper napkin folded into a small square. Printed on it, a faded character: "Nine."'),
  N('打开——一颗鸽子蛋大小的红宝石，在紫光底下红得像一滴血。宝石穿在一只金色的大圈耳环上。','You unfold it. A ruby the size of a pigeon\'s egg, red as a drop of blood under the purple light. It\'s threaded onto a big gold hoop earring.'),
  IF('ella_ear',[N('（右耳那只。原来她把耳环摘下来，当成了挂钩。）','(The right-ear hoop. She took it off and used it as a hook.)')]),
  N('餐巾纸背面，有一行钢笔字，笔画很重：「不知道是谁的。放回原处。——九」','On the back of the napkin, in heavy fountain-pen strokes: "Don\'t know whose this is. Put back where I found it. — Nine"'),
  S('ella','（她盯着那行字，看了很久）……他拿着这颗石头，在外面待了两天。','(She stares at the line for a long time) …He had this stone out there with him for two days.'),
  S('ella','二十万的悬赏，就贴在他每天路过的电线杆上。……他就这么放回来了？','A two-hundred-grand bounty taped to a pole he walks past every day. …And he just put it back?'),
  N('（酒哥就是这样的人。连一颗来路不明的石头，都要等它的主人。）','(That\'s Brother Jiu for you. Even a stone of unknown origin, he\'ll wait for its owner to come back.)'),
  N('红宝石在你手心里。艾辣看着它，没有伸手。','The ruby is in your palm. Ella looks at it but doesn\'t reach for it.'),
  C(['「在交给任何人之前——先告诉我，它到底是谁的。」','"Before I hand this to anyone, tell me whose it really is."',2,[
      S('ella','（她靠回椅背，第一次没有笑）……我外婆的。','(She sits back, and for the first time she isn\'t smiling) …My grandma\'s.'),
      S('ella','她的嫁妆。二十年前，码头拆迁，咖啡摊要关，她借了一笔钱。放贷的，就是宋鸿。','Her dowry. Twenty years ago they demolished the docks and her coffee stall had to close, so she borrowed money. The lender was Song Hong.'),
      S('ella','利滚利。三个月后，他拿走了这颗石头，说是「抵押」。然后带出国，换了个名字——「鸽血红」，配上一张假的来历证明。','Interest on interest. Three months later he took this stone as "collateral." Then he took it abroad, gave it a new name, "Pigeon\'s Blood," and a forged provenance.'),
      S('ella','这个月，他把它运回来上拍。底价三千万。','This month he brought it back for auction. Reserve price: thirty million.'),
      S('ella','我偷的，都是从这种人手里偷的。（她看着你）……从来没偷过你这种人。','Everything I\'ve ever stolen, I stole from people like him. (She looks at you) …Never from someone like you.'),
      FLAG('ella_story')]],
    ['「二十万的悬赏。你能出得比这更多吗？」','"There\'s a two-hundred-grand bounty. Can you top that?"',-2,[
      S('ella','（她看了你很久，笑了。笑得很冷）……原来你也是有标价的。','(She looks at you a long while, then smiles. A cold smile) …So you have a price tag too.'),
      S('ella','行啊。开个价，调酒师。我听着。','Go on, then. Name your price, bartender. I\'m listening.'),
      FLAG('ella_price')]],
    ['（攥紧红宝石，不说话）','(Close your fist around the ruby and say nothing)',1,[
      N('她倾过身来，红唇离你的耳朵只有一寸。','She leans across, her red lips an inch from your ear.'),
      S('ella','攥紧点。它比你想的，要烫手得多。','Hold it tight. It\'s a lot hotter than you think.'),
      N('（她身上，是雨水、皮革，还有一点点咖啡的味道。）','(She smells of rain, leather, and the faintest trace of coffee.)'),
      FLAG('ruby_held')]]),
  IF('trophy_seen',[
    S('ella','冯涛拍了奖杯的照片。天亮之前，宋鸿一定会亲自来。……我们没多少时间了。','Feng Tao photographed the trophy. Song Hong will come in person before dawn. …We don\'t have much time.')]),
  S('ella','最后一杯。（她把手放在吧台上，手指轻轻敲着）','One last drink. (She rests a hand on the counter, fingers tapping lightly)'),
  S('ella','这回，别给我酸的了。来杯【苦的】，【够烈】的。【不要甜】，【不要奶】——像真话那样，难喝，但是干净。','This time, nothing sour. Something 【bitter】, 【properly strong】. 【No sugar】, 【no cream】. Like the truth: hard to swallow, but clean.'),
  N('（苦，烈，干净。……还有她身上那一点点咖啡味。）','(Bitter, strong, clean. …And that faint trace of coffee on her.)'),
  MX({accept:['negroni','old_fashioned','sazerac','manhattan','last_word'],best:'mezcal_negroni',want:['苦','烈'],avoid:['甜','奶香','气泡'],str:'high'},
   [S('ella','（喝了一口，闭上眼睛）……烟熏的。','(She sips and closes her eyes) …Smoky.'),
    S('ella','像码头上，凌晨四点，煤炉子刚生起来的那股味。','Like the docks at four in the morning, when the coal stove\'s just been lit.'),
    S('ella','（她睁开眼睛，看着你）你这个人，我有点舍不得骗了。','(She opens her eyes and looks at you) I\'m starting to not want to lie to you.'),
    AFF(1),FLAG('ella_trust2')],
   [S('ella','嗯。够苦，不够狠。','Mm. Bitter enough. Not mean enough.')],
   [EMO('💢'),
    S('ella','……甜的？（她把杯子推开）我说的是真话，不是情话。','…Sweet? (She pushes the glass away) I asked for the truth, not sweet talk.')],
   [S('ella','（一口下去，她的手停在杯子上，很久没动）……咖啡。','(One sip, and her hand stays frozen on the glass for a long time) …Coffee.'),
    S('ella','又黑又苦。……跟外婆煤炉子上那壶，一个味儿。','Black and bitter. …Same as the pot on Grandma\'s coal stove.'),
    S('ella','（她低下头，声音很小）我已经十年，没跟任何人说过她了。今天说了两次。','(Head bowed, very quietly) I haven\'t talked about her to anyone in ten years. Tonight I\'ve done it twice.'),
    IF('!ella_story',[
      S('ella','……那颗石头，是她的嫁妆。宋鸿用一笔高利贷，从一个摆咖啡摊的老太太手里拿走的。我只是，把它拿回来。','…That stone was her dowry. Song Hong took it from an old woman with a coffee stall, with one loan-shark contract. I\'m only taking it back.'),
      FLAG('ella_story')]),
    AFF(2),FLAG('ella_trust2'),FLAG('ella_grandma')]),
  FX('light'),
  N('大厅的灯，忽然全亮了。','Suddenly every light in the lounge comes on.'),
  N('莫姐站在办公室门口，一只手还按在开关上。','Sister Mo stands in the office doorway, one hand still on the switch.'),
  WHO('mojie'),
  S('mojie','……我在里面听了半个小时了。','…I\'ve been listening in there for half an hour.')]},

 {who:'mojie',steps:[
  CARD('— 02:30 · 距离天亮，还有三个小时 —','— 2:30 AM · Three hours until dawn —'),
  N('莫姐在吧台边坐下，把手机屏幕朝上放在台面上。跟一周前一模一样。','Sister Mo sits at the bar and lays her phone face-up on the counter. Exactly like a week ago.'),
  S('mojie','这是我的店。上周，我差一点就因为一个奖杯，把它整个赔进去。','This is my bar. Last week I nearly lost the whole place over one trophy.'),
  S('mojie','今晚，同一个奖杯里，又掉出来一颗三千万的石头。……你说，我是不是该转行。','Tonight, out of the very same trophy, falls a thirty-million-yuan stone. …Tell me, should I change careers?'),
  C(['「莫姐，这事我来担。不会让店出事。」','"Sister Mo, this is on me. The bar won\'t get hurt."',2,[
      S('mojie','（她看了你一眼）……口气跟酒哥越来越像了。','(She gives you a look) …You sound more like Brother Jiu every day.')]],
    ['「她外婆的东西，被人用高利贷骗走了。」','"It was her grandmother\'s. Someone took it with a loan-shark contract."',1,[
      S('mojie','我听见了。（她没看艾辣）……可我只听了一面之词。','I heard. (She doesn\'t look at Ella) …But I\'ve only heard one side.')],'ella_story'],
    ['「报警吧。最省事。」','"Let\'s just call the police. Simplest way."',0,[
      S('mojie','最省事的路，往往最贵。……上周我差一点就学会了这一课。','The simplest road is usually the most expensive. …I nearly learned that last week.')]]),
  S('mojie','先给我一杯。……要【清醒】、【干净】的，【不要甜】。【草本】的那种。我得想想，怎么跟一个通缉犯做生意。','Pour me one first. …Something 【clear-headed】 and 【clean】. 【Not sweet】. 【Herbal】. I need to work out how one does business with a wanted woman.'),
  MX({accept:['last_word','dry_martini','rose_lychee','negroni'],best:'sake_tini',want:['草本','优雅'],avoid:['甜','奶香','气泡'],str:'mid'},
   [S('mojie','（喝了一口，手指离开了手机）……好。我想清楚了。','(Sips, and her fingers leave the phone) …Good. I\'ve thought it through.'),
    S('mojie','这家店，我交给你看了一个礼拜了。……你决定。我信你。','I\'ve trusted you with this bar for a week now. …You decide. I\'ll back you.'),
    FLAG('mo_backs')],
   [S('mojie','……可以。你决定吧。','…Fine. It\'s your call.')],
   [S('mojie','（放下杯子）……今晚我们俩，都不太清醒。','(Sets the glass down) …Neither of us is thinking straight tonight.')],
   [S('mojie','（喝了一口，笑了）……咖啡。','(Sips and smiles) …Coffee.'),
    S('mojie','我在办公室熬夜对账的时候，就喝这个。你连这个都知道。','That\'s what I drink when I\'m up all night doing the books in the office. You even know that.'),
    S('mojie','你决定吧。我信你。','You decide. I\'ll back you.'),
    FLAG('mo_backs')]),
  WHO('ella'),
  N('艾辣站起来，把皮夹克的拉链拉到了顶。左耳的金圈，在灯下闪了一下。','Ella stands and zips her leather jacket to the collar. The gold hoop in her left ear catches the light.'),
  S('ella','好了，调酒师。石头在你手里，人在你店里。','Alright, bartender. The stone\'s in your hand, and I\'m in your bar.'),
  S('ella','你打算怎么处置我们俩？','So what are you going to do with the two of us?'),
  IF('ella_doubt',[S('ella','（她看着你抬起过的那只手）……我猜，你早就想好了。','(Looking at the hand you raised earlier) …I suspect you made up your mind a while ago.')]),
  CT(15,[
      N('你还在犹豫。艾辣看着你，看了很久，然后轻轻笑了一下。','You\'re still hesitating. Ella looks at you for a long time, then gives a soft little laugh.'),
      N('她伸手，从你掌心里把红宝石拈了起来，把那只空着的金耳环放在了吧台上。','She reaches over and plucks the ruby from your palm, leaving the empty gold hoop on the counter.'),
      S('ella','你不用选。……我替你选。','You don\'t have to choose. …I\'ll choose for you.'),
      N('后门「吱呀」一声。风铃都没响。','The back door creaks. The bell never even rings.'),
      FLAG('ella_gone')],
    ['（拿起电话）「报警。人和石头，一起交给警察。」','(Pick up the phone) "I\'m calling the police. The woman and the stone, both."',0,[
      FLAG('call_police')]],
    ['（把红宝石放进她手心）「走后门。快。」','(Press the ruby into her palm) "Back door. Go. Now."',2,[
      FLAG('ella_gone')]],
    ['「石头你拿回去。但宋鸿那边——我们得让他自己去跟警察解释。」','"You take the stone back. But Song Hong? We make him explain himself to the police."',3,[
      FLAG('partner')],['door_held','ella_story',{aff:'ella',min:6}]]),
  IF('partner',[
    S('ella','（她愣住了。然后慢慢地、慢慢地笑了起来）……调酒师，你这是要入伙？','(She freezes. Then, slowly, slowly, she starts to smile) …Bartender, are you asking to join the crew?'),
    WHO('kevin'),
    S('kevin','（从沙发后面探出头）冯涛拿钱要进门的录像、那辆车上个月三次深夜停在后巷……我全都有。','(Popping up from behind the sofa) Footage of Feng Tao waving cash to get in, that car parked in our back alley three nights last month… I\'ve got all of it.'),
    WHO('xiangge'),
    S('xiangge','私人悬赏、无立案、来历证明造假、高利贷抵押……（他掰着手指）够他喝一壶的。我天亮就去递材料。','Private bounty, no case filed, forged provenance, loan-shark collateral… (counting on his fingers) That\'s plenty to sink him. I\'ll file it all at sunrise.'),
    IF('footage_xiang',[S('xiangge','红外录像我已经收到了。酒哥那三秒，我剪掉了。','I\'ve already got the infrared footage. I cut Brother Jiu\'s three seconds.')]),
    WHO('mojie'),
    S('mojie','（她叹了口气，把手机收进了口袋）……我就当今晚，什么都没发生过。','(She sighs and slips her phone into her pocket) …As far as I\'m concerned, nothing happened tonight.'),
    WHO('ella'),
    S('ella','（她从你手里拿起那只空的金耳环，戴回了右耳）这样，两边就对称了。','(She takes the empty gold hoop from your hand and puts it back in her right ear) There. Symmetrical again.'),
    S('ella','我欠你一杯，调酒师。……不对，欠你一次。','I owe you a drink, bartender. …No. I owe you one.'),
    CARD('— 三个月后 —','— Three months later —'),
    N('新闻里说，鸿运拍卖行因涉嫌走私文物、伪造来历证明被立案调查，老板宋鸿被带走时，用西装外套蒙着头。','The news says the Hongyun Auction House is under investigation for smuggling and forged provenance. Song Hong was led away with his suit jacket over his head.'),
    N('那颗「鸽血红」，再也没有出现在任何一场拍卖会上。','The "Pigeon\'s Blood" never appeared at another auction.'),
    N('某个周五，吧台上多了一张明信片。没有署名，只有一个鲜红的唇印，和一行字：「码头的咖啡摊，重新开张了。来喝一杯？」','One Friday, a postcard turns up on the bar. No signature, just a bright red lip print and one line: "The coffee stall on the docks is open again. Come for a cup?"'),
    N('明信片底下，压着一只金色的大圈耳环。','Under the postcard lies a single big gold hoop earring.'),
    END('accomplice','红唇同伙','Partner in Crime')],
   [IF('call_police',[
      N('你拨通了电话。艾辣没有跑。','You dial. Ella doesn\'t run.'),
      S('ella','（她坐回凳子上，把两只手腕并在一起，伸到你面前）……你是个好人，调酒师。','(She sits back down on the stool and holds out both wrists to you, side by side) …You\'re a good person, bartender.'),
      S('ella','可惜，好人不一定站对了边。','Shame good people don\'t always pick the right side.'),
      IF(['footage_xiang','door_held'],[
        WHO('xiangge'),
        S('xiangge','（他在警察到之前，把一个 U 盘塞进了你手里）……私人悬赏、门口那辆车、上个月三次深夜停车。都在里面。人归警察，可这颗石头的来历，得有人替她说。','(Before the police arrive he presses a USB stick into your hand) …The private bounty, that car outside, the three late-night visits last month. It\'s all on there. She belongs to the police now, but someone has to speak for where that stone came from.'),
        N('后来，宋鸿也被叫去问了话。可那颗石头，最后还是被当成「赃物」，锁进了证物室。','Later, Song Hong was called in for questioning too. But the stone ended up filed as "stolen property" and locked in an evidence room.')],
       [N('警察来的时候，宋鸿也到了。他站在门口，看着那颗红宝石被装进证物袋，笑得很客气。','When the police arrive, so does Song Hong. He stands by the door and watches the ruby go into an evidence bag, smiling politely.')]),
      N('警车的灯，红一下，蓝一下，照在她的红唇上。上车之前，她回过头，冲你眨了一下眼睛。','The patrol car\'s lights flash red, then blue, across her red lips. Before she gets in, she looks back and winks at you.'),
      N('第二天，门口那张悬赏通告被人撕掉了。电线杆上，只剩下四个胶带印。','The next day, someone has torn the reward notice down. On the pole, only four tape marks remain.'),
      END('red_cuffs','红唇落网','Red Lips, Caught')],
     [N('后门轻轻合上了。雨停了。','The back door eases shut. The rain has stopped.'),
      N('你低头，吧台上留着一张纸巾。纸巾上，是一个鲜红的唇印。','You look down. On the counter lies a napkin with a bright red lip print on it.'),
      IF('ella_trust2',[N('唇印旁边，一行小字：「欠你一杯。会回来还的。——辣」','Beside it, in small letters: "I owe you a drink. I\'ll be back to pay. — E"')]),
      N('天亮的时候，那辆黑色轿车已经不在街对面了。宋鸿再也没有出现过。门口的悬赏通告，被雨泡烂了，没人再去换。','By dawn the black sedan is gone from across the street. Song Hong never shows up again. The reward notice by the door rots in the rain, and no one replaces it.'),
      N('只有莫姐偶尔会问：「那个女的……后来怎么样了？」','Only Sister Mo occasionally asks, "That woman… whatever happened to her?"'),
      N('你什么都没说，只是给她调了一杯，又黑又苦的。','You don\'t say anything. You just make her a drink, black and bitter.'),
      END('let_her_go','放她走','Let Her Go')])])]}
 ]}
];

