  ['little_fortune','小幸运','Little Fortune','第二夜：推李宇童一把，并让他对你足够信任。','Night 2: give Li Yutong a push, and earn his trust.'],
  ['sprout','芽','Sprout','第三夜：为芽点亮台灯、听她讲那幅画，再调出让她满意的一杯。','Night 3: light the lamp for Ya, hear about her painting, and mix her something she loves.'],
  ['off_camera','镜头之外','Off Camera','第五夜：看穿 Ace 的恐惧，并在镜头熄灭时为他打光。','Night 5: see through Ace\'s fear, and light him up when the camera dies.'],
  ['red_cuffs','红唇落网','Red Lips, Caught','番外第八夜：最后关头，拿起电话报警。','Night 8: when it comes down to it, pick up the phone and call the police.'],
  ['let_her_go','放她走','Let Her Go','番外第八夜：把红宝石还给艾辣，让她从后门离开——或者犹豫到她自己走掉。','Night 8: give Ella the ruby and let her out the back door, or hesitate until she leaves on her own.'],
  ['accomplice','红唇同伙','Partner in Crime','番外第八夜：查清悬赏的真相、帮翔哥守住门、听艾辣讲完外婆的故事并赢得她的信任，然后提议一起扳倒宋鸿。','Night 8: uncover the truth about the bounty, help Brother Xiang hold the door, hear Ella\'s story about her grandmother and win her trust, then propose bringing Song Hong down together.']
